    logger.error('Initiate call error:', error.message);
    if (error.response?.data) {
      return res.status(error.response.status || 500).json({
        success: false,
        error: error.response.data?.error?.message || 'Failed to initiate call',
      });
    }
    next(error);
  }
}

/**
