var callIDPattern = regexp.MustCompile(`^[A-Za-z0-9._=-]{1,128}$`)

// roomPattern restricts LiveKit room names we are willing to join.
var roomPattern = regexp.MustCompile(`^call-[A-Za-z0-9._=-]{1,120}$`)

type server struct {
