	s.notifyCB = s.notifyBackend

	srv := &http.Server{
		Addr:              cfg.ListenAddr,
		Handler:           s.routes(),
		ReadHeaderTimeout: 5 * time.Second,
		ReadTimeout:       15 * time.Second,
		WriteTimeout:      30 * time.Second,
	}
	go func() {
		log.Printf("call-bridge listening on %s", cfg.ListenAddr)
		if err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			log.Fatalf("http: %v", err)
		}
	}()

	stop := make(chan os.Signal, 1)
	signal.Notify(stop, syscall.SIGINT, syscall.SIGTERM)
	<-stop
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	_ = srv.Shutdown(ctx)
}

func (s *server) routes() http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
		writeJSON(w, 200, map[string]any{"ok": true, "activeSessions": s.mgr.Count()})
	})
	mux.HandleFunc("POST /v1/sessions/inbound", s.auth(s.handleInbound))
	mux.HandleFunc("POST /v1/sessions/outbound", s.auth(s.handleOutbound))
	mux.HandleFunc("POST /v1/sessions/{id}/answer", s.auth(s.handleAnswer))
	mux.HandleFunc("DELETE /v1/sessions/{id}", s.auth(s.handleDelete))
	return mux
}

func (s *server) auth(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		got := []byte(r.Header.Get("X-Bridge-Secret"))
		if subtle.ConstantTimeCompare(got, []byte(s.cfg.BridgeSecret)) != 1 {
			writeJSON(w, http.StatusUnauthorized, map[string]any{"error": "unauthorized"})
			return
		}
		r.Body = http.MaxBytesReader(w, r.Body, 128*1024)
		next(w, r)
	}
}

