func validate(w http.ResponseWriter, req sessionRequest, needSDP bool) bool {
	if !callIDPattern.MatchString(req.CallID) || !roomPattern.MatchString(req.Room) {
		writeJSON(w, 400, map[string]any{"error": "invalid callId or room"})
		return false
	}
	if needSDP && (req.SDP == "" || len(req.SDP) > 64*1024) {
		writeJSON(w, 400, map[string]any{"error": "invalid sdp"})
		return false
	}
	return true
}

func (s *server) handleInbound(w http.ResponseWriter, r *http.Request) {
	var req sessionRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil || !validate(w, req, true) {
		if err != nil {
			writeJSON(w, 400, map[string]any{"error": "bad json"})
		}
		return
	}
	sess, err := s.newSession(req)
	if err != nil {
		log.Printf("[%s] inbound session failed: %v", req.CallID, err)
		writeJSON(w, 502, map[string]any{"error": "session setup failed"})
		return
	}
	answer, err := sess.AcceptOffer(req.SDP)
	if err != nil {
		log.Printf("[%s] accept offer failed: %v", req.CallID, err)
		sess.Close("negotiation_failed")
		writeJSON(w, 422, map[string]any{"error": "sdp negotiation failed"})
		return
	}
	writeJSON(w, 200, map[string]any{"sdp": answer})
}

func (s *server) handleOutbound(w http.ResponseWriter, r *http.Request) {
	var req sessionRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil || !validate(w, req, false) {
		if err != nil {
			writeJSON(w, 400, map[string]any{"error": "bad json"})
		}
		return
	}
	sess, err := s.newSession(req)
	if err != nil {
		log.Printf("[%s] outbound session failed: %v", req.CallID, err)
		writeJSON(w, 502, map[string]any{"error": "session setup failed"})
		return
	}
	offer, err := sess.CreateOffer()
	if err != nil {
		sess.Close("negotiation_failed")
		writeJSON(w, 422, map[string]any{"error": "sdp negotiation failed"})
		return
	}
	writeJSON(w, 200, map[string]any{"sdp": offer})
}

func (s *server) handleAnswer(w http.ResponseWriter, r *http.Request) {
	id := r.PathValue("id")
	var req sessionRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil || req.SDP == "" || len(req.SDP) > 64*1024 || !callIDPattern.MatchString(id) {
		writeJSON(w, 400, map[string]any{"error": "invalid request"})
		return
	}
	sess, ok := s.mgr.Get(id)
	if !ok {
		writeJSON(w, 404, map[string]any{"error": "no such session"})
		return
	}
	if err := sess.SetAnswer(req.SDP); err != nil {
		log.Printf("[%s] set answer failed: %v", id, err)
		sess.Close("negotiation_failed")
		writeJSON(w, 422, map[string]any{"error": "sdp negotiation failed"})
		return
	}
	writeJSON(w, 200, map[string]any{"ok": true})
}

func (s *server) handleDelete(w http.ResponseWriter, r *http.Request) {
	id := r.PathValue("id")
	if !callIDPattern.MatchString(id) {
		writeJSON(w, 400, map[string]any{"error": "invalid id"})
		return
	}
	if sess, ok := s.mgr.Get(id); ok {
		sess.Close("terminated")
	}
	writeJSON(w, 200, map[string]any{"ok": true})
}

// notifyBackend tells the Node backend that a call's media leg ended (best effort).
func (s *server) notifyBackend(callID, reason string) {
	if s.cfg.CallbackURL == "" {
		return
	}
	body, _ := json.Marshal(map[string]string{"callId": callID, "event": "media_ended", "reason": reason})
	req, err := http.NewRequest(http.MethodPost, s.cfg.CallbackURL, bytes.NewReader(body))
	if err != nil {
		return
	}
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("X-Bridge-Secret", s.cfg.BridgeSecret)
	client := &http.Client{Timeout: 5 * time.Second}
	go func() {
		resp, err := client.Do(req)
		if err != nil {
			log.Printf("[%s] backend callback failed: %v", callID, err)
			return
		}
		resp.Body.Close()
	}()
}

func writeJSON(w http.ResponseWriter, code int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(code)
	_ = json.NewEncoder(w).Encode(v)
}

