package main

import (
	"fmt"
	"os"
	"strconv"
)

// Config holds all runtime settings, read from environment variables.
type Config struct {
	ListenAddr     string // HTTP listen address, e.g. 127.0.0.1:8090
	BridgeSecret   string // shared secret the Node backend sends in X-Bridge-Secret
	CallbackURL    string // Node backend URL that receives media events (optional)
	LiveKitURL     string // ws(s)://... of the self-hosted LiveKit server
	LiveKitAPIKey  string
	LiveKitSecret  string
	PublicIP       string // public IPv4 of the VPS, advertised to Meta in ICE candidates
	UDPPortMin     uint16 // UDP range used for the Meta media leg
	UDPPortMax     uint16
	IncludeLoopack bool // tests only
}

func loadConfig() (Config, error) {
	c := Config{
		ListenAddr:    getenv("BRIDGE_LISTEN", "127.0.0.1:8090"),
		BridgeSecret:  os.Getenv("BRIDGE_SECRET"),
		CallbackURL:   os.Getenv("BRIDGE_CALLBACK_URL"),
		LiveKitURL:    os.Getenv("LIVEKIT_URL"),
		LiveKitAPIKey: os.Getenv("LIVEKIT_API_KEY"),
		LiveKitSecret: os.Getenv("LIVEKIT_API_SECRET"),
		PublicIP:      os.Getenv("BRIDGE_PUBLIC_IP"),
	}
	min, err := strconv.Atoi(getenv("BRIDGE_UDP_MIN", "40000"))
	if err != nil {
		return c, fmt.Errorf("BRIDGE_UDP_MIN: %w", err)
	}
	max, err := strconv.Atoi(getenv("BRIDGE_UDP_MAX", "40200"))
	if err != nil {
		return c, fmt.Errorf("BRIDGE_UDP_MAX: %w", err)
	}
	if min <= 0 || max > 65535 || min >= max {
		return c, fmt.Errorf("invalid UDP range %d-%d", min, max)
	}
	c.UDPPortMin, c.UDPPortMax = uint16(min), uint16(max)

	if len(c.BridgeSecret) < 32 {
		return c, fmt.Errorf("BRIDGE_SECRET must be set and at least 32 characters")
	}
