  try {
    const r = await axios.get(`${BASE}${path}`, { headers: { Authorization: `Bearer ${token}` }, params, timeout: 20000 });
    return { ok: true, data: r.data };
  } catch (e) {
    return { ok: false, error: e.response?.data?.error?.message || e.message };
  }
};

