package main

import (
	"bytes"
	"context"
	"crypto/subtle"
	"encoding/json"
	"errors"
	"log"
	"net/http"
	"os"
	"os/signal"
	"regexp"
	"syscall"
	"time"
)

// callIDPattern matches Meta call ids (wacid.xxxx) and our own test ids; blocks path tricks.
var callIDPattern = regexp.MustCompile(`^[A-Za-z0-9._=-]{1,128}$`)

// roomPattern restricts LiveKit room names we are willing to join.
var roomPattern = regexp.MustCompile(`^call-[A-Za-z0-9._=-]{1,120}$`)

type server struct {
	cfg      Config
	mgr      *Manager
	newLink  func(cfg Config, room, callID string) (RoomLink, error)
	notifyCB func(callID, reason string)
}

func main() {
	cfg, err := loadConfig()
	if err != nil {
		log.Fatalf("config: %v", err)
	}
	s := &server{cfg: cfg, mgr: NewManager(), newLink: NewLiveKitLink}
	s.notifyCB = s.notifyBackend

	srv := &http.Server{
		Addr:              cfg.ListenAddr,
		Handler:           s.routes(),
		ReadHeaderTimeout: 5 * time.Second,
		ReadTimeout:       15 * time.Second,
		WriteTimeout:      30 * time.Second,
	}
	go func() {
		log.Printf("call-bridge listening on %s", cfg.ListenAddr)
		if err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			log.Fatalf("http: %v", err)
		}
	}()

	stop := make(chan os.Signal, 1)
	signal.Notify(stop, syscall.SIGINT, syscall.SIGTERM)
	<-stop
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	_ = srv.Shutdown(ctx)
}

func (s *server) routes() http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
		writeJSON(w, 200, map[string]any{"ok": true, "activeSessions": s.mgr.Count()})
	})
	mux.HandleFunc("POST /v1/sessions/inbound", s.auth(s.handleInbound))
	mux.HandleFunc("POST /v1/sessions/outbound", s.auth(s.handleOutbound))
	mux.HandleFunc("POST /v1/sessions/{id}/answer", s.auth(s.handleAnswer))
	mux.HandleFunc("DELETE /v1/sessions/{id}", s.auth(s.handleDelete))
	return mux
}

func (s *server) auth(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		got := []byte(r.Header.Get("X-Bridge-Secret"))
		if subtle.ConstantTimeCompare(got, []byte(s.cfg.BridgeSecret)) != 1 {
			writeJSON(w, http.StatusUnauthorized, map[string]any{"error": "unauthorized"})
			return
		}
		r.Body = http.MaxBytesReader(w, r.Body, 128*1024)
		next(w, r)
	}
}

type sessionRequest struct {
	CallID string `json:"callId"`
	Room   string `json:"room"`
	SDP    string `json:"sdp"`
}

func (s *server) newSession(req sessionRequest) (*Session, error) {
	link, err := s.newLink(s.cfg, req.Room, req.CallID)
	if err != nil {
		return nil, err
	}
	sess, err := NewSession(s.cfg, req.CallID, link, func(id, reason string) {
		s.mgr.Remove(id)
		if s.notifyCB != nil {
			s.notifyCB(id, reason)
		}
	})
	if err != nil {
		link.Close()
		return nil, err
	}
	if err := s.mgr.Add(sess); err != nil {
		sess.Close("duplicate")
		return nil, err
	}
	return sess, nil
}

func validate(w http.ResponseWriter, req sessionRequest, needSDP bool) bool {
	if !callIDPattern.MatchString(req.CallID) || !roomPattern.MatchString(req.Room) {
		writeJSON(w, 400, map[string]any{"error": "invalid callId or room"})
		return false
	}
	if needSDP && (req.SDP == "" || len(req.SDP) > 64*1024) {
		writeJSON(w, 400, map[string]any{"error": "invalid sdp"})
		return false
	}
	return true
}

func (s *server) handleInbound(w http.ResponseWriter, r *http.Request) {
	var req sessionRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil || !validate(w, req, true) {
		if err != nil {
			writeJSON(w, 400, map[string]any{"error": "bad json"})
		}
		return
	}
	sess, err := s.newSession(req)
	if err != nil {
		log.Printf("[%s] inbound session failed: %v", req.CallID, err)
		writeJSON(w, 502, map[string]any{"error": "session setup failed"})
		return
	}
	answer, err := sess.AcceptOffer(req.SDP)
	if err != nil {
		log.Printf("[%s] accept offer failed: %v", req.CallID, err)
		sess.Close("negotiation_failed")
		writeJSON(w, 422, map[string]any{"error": "sdp negotiation failed"})
		return
	}
	writeJSON(w, 200, map[string]any{"sdp": answer})
}

func (s *server) handleOutbound(w http.ResponseWriter, r *http.Request) {
	var req sessionRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil || !validate(w, req, false) {
		if err != nil {
			writeJSON(w, 400, map[string]any{"error": "bad json"})
		}
		return
	}
	sess, err := s.newSession(req)
	if err != nil {
		log.Printf("[%s] outbound session failed: %v", req.CallID, err)
		writeJSON(w, 502, map[string]any{"error": "session setup failed"})
		return
	}
	offer, err := sess.CreateOffer()
	if err != nil {
		sess.Close("negotiation_failed")
		writeJSON(w, 422, map[string]any{"error": "sdp negotiation failed"})
		return
	}
	writeJSON(w, 200, map[string]any{"sdp": offer})
}

func (s *server) handleAnswer(w http.ResponseWriter, r *http.Request) {
	id := r.PathValue("id")
	var req sessionRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil || req.SDP == "" || len(req.SDP) > 64*1024 || !callIDPattern.MatchString(id) {
		writeJSON(w, 400, map[string]any{"error": "invalid request"})
		return
	}
	sess, ok := s.mgr.Get(id)
	if !ok {
		writeJSON(w, 404, map[string]any{"error": "no such session"})
		return
	}
	if err := sess.SetAnswer(req.SDP); err != nil {
		log.Printf("[%s] set answer failed: %v", id, err)
		sess.Close("negotiation_failed")
		writeJSON(w, 422, map[string]any{"error": "sdp negotiation failed"})
		return
	}
	writeJSON(w, 200, map[string]any{"ok": true})
}

func (s *server) handleDelete(w http.ResponseWriter, r *http.Request) {
	id := r.PathValue("id")
	if !callIDPattern.MatchString(id) {
		writeJSON(w, 400, map[string]any{"error": "invalid id"})
		return
	}
	if sess, ok := s.mgr.Get(id); ok {
		sess.Close("terminated")
	}
	writeJSON(w, 200, map[string]any{"ok": true})
}

// notifyBackend tells the Node backend that a call's media leg ended (best effort).
func (s *server) notifyBackend(callID, reason string) {
	if s.cfg.CallbackURL == "" {
		return
	}
	body, _ := json.Marshal(map[string]string{"callId": callID, "event": "media_ended", "reason": reason})
	req, err := http.NewRequest(http.MethodPost, s.cfg.CallbackURL, bytes.NewReader(body))
	if err != nil {
		return
	}
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("X-Bridge-Secret", s.cfg.BridgeSecret)
	client := &http.Client{Timeout: 5 * time.Second}
	go func() {
		resp, err := client.Do(req)
		if err != nil {
			log.Printf("[%s] backend callback failed: %v", callID, err)
			return
		}
		resp.Body.Close()
	}()
}

func writeJSON(w http.ResponseWriter, code int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(code)
	_ = json.NewEncoder(w).Encode(v)
}

