// RoomLink connects one WhatsApp call leg to a LiveKit room (or a fake in tests).
type RoomLink interface {
	// PublishCustomer sends the customer's audio (from Meta) into the room.
	PublishCustomer(pkt *rtp.Packet) error
	// SetStaffAudioHandler registers where audio from the answering staff member is delivered.
	SetStaffAudioHandler(fn func(pkt *rtp.Packet))
	Close()
}

// Session is one WhatsApp call's media leg between Meta and the room.
type Session struct {
	ID string

	pc   *webrtc.PeerConnection
	out  *webrtc.TrackLocalStaticRTP // audio sent to Meta (staff voice)
	link RoomLink

	onEnded   func(id, reason string)
	closeOnce sync.Once
	closed    chan struct{}
}

func newAPI(cfg Config) (*webrtc.API, error) {
	me := &webrtc.MediaEngine{}
	// Meta calling uses Opus (48 kHz). Only register what we support.
	if err := me.RegisterCodec(webrtc.RTPCodecParameters{
		RTPCodecCapability: webrtc.RTPCodecCapability{
			MimeType: webrtc.MimeTypeOpus, ClockRate: 48000, Channels: 2,
			SDPFmtpLine: "minptime=10;useinbandfec=1",
		},
		PayloadType: 111,
	}, webrtc.RTPCodecTypeAudio); err != nil {
		return nil, err
	}

	se := webrtc.SettingEngine{}
	if err := se.SetEphemeralUDPPortRange(cfg.UDPPortMin, cfg.UDPPortMax); err != nil {
		return nil, err
	}
	se.SetNetworkTypes([]webrtc.NetworkType{webrtc.NetworkTypeUDP4})
	if cfg.PublicIP != "" {
		se.SetNAT1To1IPs([]string{cfg.PublicIP}, webrtc.ICECandidateTypeHost)
	}
	if cfg.IncludeLoopack {
		se.SetIncludeLoopbackCandidate(true)
	}
	return webrtc.NewAPI(webrtc.WithMediaEngine(me), webrtc.WithSettingEngine(se)), nil
}

// NewSession creates the peer connection for a call. It does not negotiate yet.
func NewSession(cfg Config, id string, link RoomLink, onEnded func(id, reason string)) (*Session, error) {
	api, err := newAPI(cfg)
	if err != nil {
		return nil, err
	}
	// No STUN/TURN: the VPS has a public IP and Meta's media servers are public.
	pc, err := api.NewPeerConnection(webrtc.Configuration{})
	if err != nil {
		return nil, err
	}
	out, err := webrtc.NewTrackLocalStaticRTP(
		webrtc.RTPCodecCapability{MimeType: webrtc.MimeTypeOpus, ClockRate: 48000, Channels: 2},
		"audio", "bjs-bridge")
	if err != nil {
		pc.Close()
		return nil, err
	}
	if _, err := pc.AddTrack(out); err != nil {
		pc.Close()
		return nil, err
	}

	s := &Session{ID: id, pc: pc, out: out, link: link, onEnded: onEnded, closed: make(chan struct{})}

	link.SetStaffAudioHandler(func(pkt *rtp.Packet) {
		if err := s.out.WriteRTP(pkt); err != nil && !errors.Is(err, io.ErrClosedPipe) {
			log.Printf("[%s] write to Meta failed: %v", id, err)
		}
	})

	pc.OnTrack(func(track *webrtc.TrackRemote, _ *webrtc.RTPReceiver) {
		if track.Kind() != webrtc.RTPCodecTypeAudio {
			return
		}
		for {
			pkt, _, err := track.ReadRTP()
			if err != nil {
				return
			}
			if err := s.link.PublishCustomer(pkt); err != nil {
				log.Printf("[%s] publish to room failed: %v", id, err)
			}
		}
	})

	pc.OnConnectionStateChange(func(st webrtc.PeerConnectionState) {
		log.Printf("[%s] media state: %s", id, st)
		switch st {
		case webrtc.PeerConnectionStateFailed:
			s.Close("media_failed")
		case webrtc.PeerConnectionStateClosed, webrtc.PeerConnectionStateDisconnected:
			// Disconnected can recover; give it a grace period.
			if st == webrtc.PeerConnectionStateDisconnected {
				go func() {
					time.Sleep(10 * time.Second)
					if pc.ConnectionState() == webrtc.PeerConnectionStateDisconnected {
						s.Close("media_disconnected")
					}
				}()
				return
			}
			s.Close("media_closed")
		}
	})
	return s, nil
}

func gatherAndReturn(pc *webrtc.PeerConnection) (string, error) {
	<-webrtc.GatheringCompletePromise(pc)
	ld := pc.LocalDescription()
	if ld == nil {
		return "", errors.New("no local description")
	}
	return ld.SDP, nil
}

// AcceptOffer handles a user-initiated call: Meta's SDP offer in, our SDP answer out.
// The answer contains all ICE candidates (non-trickle), as Meta requires.
func (s *Session) AcceptOffer(offerSDP string) (string, error) {
	if err := s.pc.SetRemoteDescription(webrtc.SessionDescription{Type: webrtc.SDPTypeOffer, SDP: offerSDP}); err != nil {
		return "", fmt.Errorf("set remote offer: %w", err)
	}
	answer, err := s.pc.CreateAnswer(nil)
	if err != nil {
		return "", fmt.Errorf("create answer: %w", err)
	}
	if err := s.pc.SetLocalDescription(answer); err != nil {
		return "", fmt.Errorf("set local answer: %w", err)
	}
	return gatherAndReturn(s.pc)
}

// CreateOffer starts a business-initiated call: our SDP offer, sent to Meta in the connect request.
func (s *Session) CreateOffer() (string, error) {
	offer, err := s.pc.CreateOffer(nil)
	if err != nil {
		return "", fmt.Errorf("create offer: %w", err)
	}
	if err := s.pc.SetLocalDescription(offer); err != nil {
		return "", fmt.Errorf("set local offer: %w", err)
	}
	return gatherAndReturn(s.pc)
}

// SetAnswer applies Meta's SDP answer (from the call connect webhook) for outbound calls.
func (s *Session) SetAnswer(answerSDP string) error {
	return s.pc.SetRemoteDescription(webrtc.SessionDescription{Type: webrtc.SDPTypeAnswer, SDP: answerSDP})
}

// Close tears everything down once and reports why.
func (s *Session) Close(reason string) {
	s.closeOnce.Do(func() {
		close(s.closed)
		s.link.Close()
		_ = s.pc.Close()
		if s.onEnded != nil {
			s.onEnded(s.ID, reason)
		}
	})
}

// Manager tracks active sessions by call id.
type Manager struct {
	mu       sync.Mutex
	sessions map[string]*Session
}

func NewManager() *Manager { return &Manager{sessions: map[string]*Session{}} }

func (m *Manager) Add(s *Session) error {
	m.mu.Lock()
	defer m.mu.Unlock()
	if _, exists := m.sessions[s.ID]; exists {
		return fmt.Errorf("session %s already exists", s.ID)
	}
	m.sessions[s.ID] = s
	return nil
}

func (m *Manager) Get(id string) (*Session, bool) {
	m.mu.Lock()
	defer m.mu.Unlock()
	s, ok := m.sessions[id]
	return s, ok
}

func (m *Manager) Remove(id string) {
	m.mu.Lock()
	delete(m.sessions, id)
	m.mu.Unlock()
}

func (m *Manager) Count() int {
	m.mu.Lock()
	defer m.mu.Unlock()
	return len(m.sessions)
}

