// staffIdentityPrefix: only participants whose identity starts with this are forwarded to
// the customer. This keeps recorders/egress or any other participant out of the customer's audio.
const staffIdentityPrefix = "staff-"

// CustomerIdentity is the LiveKit identity used for the WhatsApp customer's leg.
func CustomerIdentity(callID string) string { return "wa-customer-" + callID }

type liveKitLink struct {
	room  *lksdk.Room
	track *lksdk.LocalTrack

	mu      sync.RWMutex
	handler func(pkt *rtp.Packet)
	closed  bool
}

// NewLiveKitLink joins a room as the WhatsApp customer's audio participant.
func NewLiveKitLink(cfg Config, roomName, callID string) (RoomLink, error) {
	l := &liveKitLink{}

	cb := lksdk.NewRoomCallback()
	cb.ParticipantCallback.OnTrackSubscribed = func(track *webrtc.TrackRemote, _ *lksdk.RemoteTrackPublication, rp *lksdk.RemoteParticipant) {
		if track.Kind() != webrtc.RTPCodecTypeAudio || !strings.HasPrefix(rp.Identity(), staffIdentityPrefix) {
			return
		}
		go func() {
			for {
				pkt, _, err := track.ReadRTP()
				if err != nil {
					return
				}
				l.mu.RLock()
				h := l.handler
				l.mu.RUnlock()
				if h != nil {
					h(pkt)
				}
			}
		}()
	}

	room, err := lksdk.ConnectToRoom(cfg.LiveKitURL, lksdk.ConnectInfo{
		APIKey:              cfg.LiveKitAPIKey,
		APISecret:           cfg.LiveKitSecret,
		RoomName:            roomName,
		ParticipantIdentity: CustomerIdentity(callID),
		ParticipantName:     "WhatsApp customer",
	}, cb, lksdk.WithAutoSubscribe(true))
	if err != nil {
		return nil, fmt.Errorf("connect to livekit: %w", err)
	}

	track, err := lksdk.NewLocalTrack(webrtc.RTPCodecCapability{
		MimeType: webrtc.MimeTypeOpus, ClockRate: 48000, Channels: 2,
	})
	if err != nil {
		room.Disconnect()
		return nil, err
	}
	if _, err := room.LocalParticipant.PublishTrack(track, &lksdk.TrackPublicationOptions{
		Name: "customer", Source: livekit.TrackSource_MICROPHONE,
	}); err != nil {
		room.Disconnect()
		return nil, fmt.Errorf("publish customer track: %w", err)
	}
	l.room, l.track = room, track
	log.Printf("[%s] joined LiveKit room %s", callID, roomName)
	return l, nil
}

func (l *liveKitLink) PublishCustomer(pkt *rtp.Packet) error {
	l.mu.RLock()
	closed := l.closed
	l.mu.RUnlock()
	if closed {
		return nil
	}
	return l.track.WriteRTP(pkt, nil)
}

func (l *liveKitLink) SetStaffAudioHandler(fn func(pkt *rtp.Packet)) {
	l.mu.Lock()
	l.handler = fn
	l.mu.Unlock()
}

func (l *liveKitLink) Close() {
	l.mu.Lock()
	if l.closed {
		l.mu.Unlock()
		return
	}
	l.closed = true
	l.mu.Unlock()
	if l.room != nil {
		l.room.Disconnect()
	}
}

