const VoiceMessagePlayer = ({ src, isOutbound }: { src: string, isOutbound: boolean }) => {
  const [isPlaying, setIsPlaying] = useState(false)
  const [progress, setProgress] = useState(0)
  const [duration, setDuration] = useState(0)
  const [currentTime, setCurrentTime] = useState(0)
  const audioRef = useRef<HTMLAudioElement>(null)

  useEffect(() => {
    const audio = audioRef.current
    if (!audio) return

    const setAudioData = () => {
      setDuration(audio.duration)
      setCurrentTime(audio.currentTime)
    }

    const setAudioTime = () => {
      setCurrentTime(audio.currentTime)
      setProgress(Number.isFinite(audio.duration) && audio.duration > 0 ? (audio.currentTime / audio.duration) * 100 : 0)
    }

    const onEnd = () => {
      setIsPlaying(false)
      setProgress(0)
      setCurrentTime(0)
    }

    const onPause = () => setIsPlaying(false)
    const onPlay = () => setIsPlaying(true)
    const onError = () => { setIsPlaying(false); setAudioError(true) }

    audio.addEventListener('loadeddata', setAudioData)
    audio.addEventListener('loadedmetadata', setAudioData)
    audio.addEventListener('timeupdate', setAudioTime)
    audio.addEventListener('ended', onEnd)
    audio.addEventListener('pause', onPause)
    audio.addEventListener('play', onPlay)
    audio.addEventListener('error', onError)

    return () => {
      audio.removeEventListener('loadeddata', setAudioData)
      audio.removeEventListener('loadedmetadata', setAudioData)
      audio.removeEventListener('timeupdate', setAudioTime)
      audio.removeEventListener('ended', onEnd)
      audio.removeEventListener('pause', onPause)
      audio.removeEventListener('play', onPlay)
      audio.removeEventListener('error', onError)
    }
  }, [])

  const [audioError, setAudioError] = useState(false)

  const togglePlay = async () => {
    const audio = audioRef.current
    if (!audio) return
    if (isPlaying) {
      audio.pause()
      setIsPlaying(false)
      return
    }
    try {
      // iOS Safari rejects play() if the source can't be decoded; don't flip UI state blindly.
      await audio.play()
      setIsPlaying(true)
      setAudioError(false)
    } catch (err) {
      console.error('Voice playback failed:', err)
      setIsPlaying(false)
      setAudioError(true)
    }
  }

  const handleSeek = (e: React.ChangeEvent<HTMLInputElement>) => {
    const audio = audioRef.current
    if (!audio) return
    const seekTime = (Number(e.target.value) / 100) * duration
    audio.currentTime = seekTime
    setProgress(Number(e.target.value))
    setCurrentTime(seekTime)
  }

  const formatTime = (time: number) => {
    if (!Number.isFinite(time)) return '0:00'
    const minutes = Math.floor(time / 60)
    const seconds = Math.floor(time % 60)
    return `${minutes}:${seconds < 10 ? '0' : ''}${seconds}`
  }

  return (
    <div className="flex items-center gap-1.5 min-w-[260px] max-w-[280px] py-1 px-1 select-none">
      <audio ref={audioRef} src={src} preload="metadata" />

      {/* Play/Pause Button */}
      <div className="flex-shrink-0 flex items-center justify-center mr-0.5">
        <button
          onClick={togglePlay}
          className="w-[42px] h-[42px] flex items-center justify-center text-[#54656f] hover:bg-black/5 rounded-full transition-colors focus:outline-none"
        >
          {isPlaying ? (
            <svg viewBox="0 0 24 24" width="28" height="28" fill="currentColor">
              <path d="M9 16h2V8H9v8zm4-8v8h2V8h-2z" />
            </svg>
          ) : (
            <svg viewBox="0 0 24 24" width="28" height="28" fill="currentColor" className="ml-0.5">
              <path d="M8 5.14v14l11-7-11-7z" />
            </svg>
          )}
        </button>
      </div>

      {/* Progress & Content */}
      <div className="flex flex-col flex-1 justify-center">
        {/* Track and Thumb */}
        <div className="relative w-full h-[4px] mt-2 mb-1.5 flex items-center group">
          <input
            type="range"
            min="0"
            max="100"
            value={isNaN(progress) ? 0 : progress}
            onChange={handleSeek}
            className="w-full h-full rounded-full appearance-none cursor-pointer focus:outline-none relative z-10 bg-transparent [&::-webkit-slider-thumb]:appearance-none [&::-webkit-slider-thumb]:w-[13px] [&::-webkit-slider-thumb]:h-[13px] [&::-webkit-slider-thumb]:rounded-full [&::-webkit-slider-thumb]:border-none [&::-webkit-slider-thumb]:mt-[-4.5px]"
          />
          <style jsx>{`
            input[type='range']::-webkit-slider-thumb {
              background-color: #00a884 !important;
              box-shadow: 0 1px 2px rgba(0,0,0,0.1);
            }
            input[type='range']::-moz-range-thumb {
              background-color: #00a884 !important;
              width: 13px;
              height: 13px;
              border-radius: 50%;
              border: none;
            }
          `}</style>

          <div
            className="absolute top-0 left-0 h-full rounded-full pointer-events-none z-0 bg-[#00a884]"
            style={{ width: `${progress || 0}%` }}
          />
          <div
            className="absolute top-0 left-0 w-full h-full rounded-full pointer-events-none z-0 bg-black/10"
          />
        </div>

        {/* Dynamic Timestamp */}
        <div className="text-[11px] text-[#667781] leading-none mb-1">
          {audioError ? (
            <a href={src} target="_blank" rel="noopener noreferrer" className="text-red-500 underline">Can&apos;t play here – open audio</a>
          ) : (isPlaying ? formatTime(currentTime) : formatTime(duration))}
        </div>
      </div>

      {/* Avatar Group */}
      <div className="flex-shrink-0 relative ml-1.5 self-center">
        <div className="w-[45px] h-[45px] rounded-full flex items-center justify-center bg-[#dfe5e7]">
          <svg viewBox="0 0 24 24" width="28" height="28" className="text-white" fill="currentColor">
            <path d="M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z" />
          </svg>
        </div>
        <div className="absolute -right-[1px] -bottom-[1px] bg-white rounded-full p-[1.5px] shadow-sm">
          <div className="bg-[#00a884] rounded-full p-[3px]">
            <svg viewBox="0 0 24 24" width="13" height="13" className="text-white" fill="currentColor">
              <path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3z" />
              <path d="M17 11c0 2.76-2.24 5-5 5s-5-2.24-5-5H5c0 3.53 2.61 6.43 6 6.92V21h2v-3.08c3.39-.49 6-3.39 6-6.92h-2z" />
            </svg>
          </div>
        </div>
      </div>
    </div>
  )
}

