                        {replyingToMsg.text || replyingToMsg.caption || (replyingToMsg.type !== 'text' ? replyingToMsg.type.charAt(0).toUpperCase() + replyingToMsg.type.slice(1) : '')}
                      </span>
                    </div>
                    {replyingToMsg.mediaUrl && replyingToMsg.type === 'image' && (
