        setReplyingToMsg(null)

        // Actual API call using the client
        const savedMsg = await chatsApi.sendMessage(chatId, { text: textToSend, replyToMessageId: replyId })

        // Register the confirmed ID before replacing temp so the socket event is ignored
        confirmedMessageIds.current.add(savedMsg._id)

        // Replace temp message with actual
        setMessages(prev => prev.map(m => m._id === tempMessage._id ? savedMsg : m))
      }
    } catch (error: any) {
      console.error('Failed to send message:', error)
      // Mark failed messages with 'failed' status instead of removing
      setMessages(prev => prev.map(m =>
