                                    {message.quotedMessage.type === 'document' && (
                                      <div className="flex items-center gap-1.5 text-[11px]">
                                        <svg viewBox="0 0 24 24" width="13" height="13" fill="currentColor" className="text-gray-500 flex-shrink-0"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8l-8-6z"/></svg>
                                        <span className="text-gray-600 truncate" dangerouslySetInnerHTML={{__html: linkifyText(message.quotedMessage.fileName || message.quotedMessage.caption || 'Document')}} />
