                          setShowQuickReplies(true)
                          setQuickReplyQuery(val.slice(1).toLowerCase())
                          setSelectedQuickReplyIdx(0)
                        } else {
                          setShowQuickReplies(false)
                        }

                        // AI Message Improvement - trigger on typing pause
                        if (!isNote) {
                          aiMessageService.requestImprovement(
                            val,
                            (suggestion) => setAiSuggestion(suggestion),
                            () => {}, // Ignore errors - only show when processing completes
                            (isLoading) => setIsAiLoading(isLoading)
                          )
                        } else {
                          // Clear AI suggestion when in note mode
                          aiMessageService.cancel()
                          setAiSuggestion(null)
                          setAiError(null)
                        }
                      }}
                      onKeyDown={(e) => {
                        if (showQuickReplies) {
                          if (e.key === 'ArrowDown') {
                            e.preventDefault()
                            setSelectedQuickReplyIdx(prev => (prev + 1) % filteredQuickRepliesForInput.length)
                          } else if (e.key === 'ArrowUp') {
                            e.preventDefault()
                            setSelectedQuickReplyIdx(prev => (prev - 1 + filteredQuickRepliesForInput.length) % filteredQuickRepliesForInput.length)
                          } else if (e.key === 'Enter') {
                            e.preventDefault()
                            if (filteredQuickRepliesForInput[selectedQuickReplyIdx]) {
                              handleSelectQuickReply(filteredQuickRepliesForInput[selectedQuickReplyIdx])
                            }
                          } else if (e.key === 'Escape') {
                            setShowQuickReplies(false)
                          }
                        } else if (e.key === 'Enter') {
                          const shouldSend = !e.shiftKey && !e.metaKey && !e.ctrlKey && !isMobileComposerViewport()
                          if (shouldSend) {
                            e.preventDefault()
                            void handleSendMessage()
                          }
                        }
                      }}
                      onPaste={(e) => {
                        const items = e.clipboardData?.items;
                        if (items) {
                          for (let i = 0; i < items.length; i++) {
                            if (items[i].type.indexOf('image') !== -1) {
                              e.preventDefault(); // Stop image from pasting as text
                              const file = items[i].getAsFile();
                              if (file) {
                                setPastedImage(file);
                                break; // Handle one pasted image
                              }
                            }
