                    </svg>
                  </div>
                  <div className="text-left flex-1">
                    <p className="text-sm font-semibold text-gray-800">View Auto Messages</p>
                    <p className="text-[11px] text-gray-500">Bot, code detection & OCR replies</p>
                  </div>
                  <svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor" className="text-gray-400 group-hover:text-gray-600 transition-colors">
                    <path d="M8.59 16.59L13.17 12 8.59 7.41 10 6l6 6-6 6z" />
                  </svg>
                </button>
              </div>
            </div>
          </div>
