                              {msg.flowName && (
                                <span className="text-[10px] font-medium text-purple-500 bg-purple-50 px-2 py-0.5 rounded-md">
                                  {msg.flowName}
                                </span>
                              )}
                            </div>
                            <span className="text-[11px] text-gray-400 font-medium whitespace-nowrap">
                              {new Date(msg.createdAt).toLocaleString('en-IN', {
                                day: '2-digit', month: 'short',
                                hour: '2-digit', minute: '2-digit',
                                hour12: true
                              })}
                            </span>
                          </div>

                          {/* Product Code Badge */}
                          {msg.productCode && (
                            <div className="flex items-center gap-2 mb-2">
                              <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded bg-gray-100 text-gray-600 text-[11px] font-mono font-bold border border-gray-200">
                                <svg viewBox="0 0 24 24" width="11" height="11" fill="currentColor"><path d="M3 17.25V21h3.75L17.81 9.94l-3.75-3.75L3 17.25zM20.71 7.04c.39-.39.39-1.02 0-1.41l-2.34-2.34c-.39-.39-1.02-.39-1.41 0l-1.83 1.83 3.75 3.75 1.83-1.83z" /></svg>
                                Code: {msg.productCode}
                              </span>
                              {msg.productInfo && (
                                <span className="text-[10px] text-gray-500">
                                  {msg.productInfo.category && `${msg.productInfo.category.charAt(0).toUpperCase() + msg.productInfo.category.slice(1)}`}
                                  {msg.productInfo.weight && msg.productInfo.category && msg.productInfo.category.toLowerCase() !== 'silver' ? ` · ${msg.productInfo.weight}gm` : ''}
                                </span>
                              )}
                            </div>
                          )}

                          {/* Message Content */}
                          <div className="bg-white rounded-lg border border-gray-100 p-3 shadow-sm">
                            <p className="text-sm text-gray-700 whitespace-pre-wrap line-clamp-4">{msg.text || msg.caption || '(Media message)'}</p>
                          </div>

                          {/* Status */}
                          <div className="flex items-center gap-1.5 mt-2">
                            <div className={`w-1.5 h-1.5 rounded-full ${
                              msg.status === 'read' ? 'bg-blue-500' :
                              msg.status === 'delivered' ? 'bg-green-500' :
                              msg.status === 'sent' ? 'bg-gray-400' :
                              msg.status === 'failed' ? 'bg-red-500' : 'bg-gray-300'
                            }`} />
                            <span className="text-[10px] text-gray-400 capitalize">{msg.status || 'sent'}</span>
                          </div>
                        </div>
                      )
                    })}
                  </div>
                )}
              </div>
            </div>
          </div>
        )}

        <ProductSelectionPopup
          isOpen={showProductPopup}
          onClose={() => setShowProductPopup(false)}
          onSend={handleSendProducts}
        />

        {/* Zoom Image Modal */}
        {zoomImage && (
          <div
            className="fixed inset-0 z-[100] flex items-center justify-center bg-black/90 p-4"
            onClick={() => setZoomImage(null)}
          >
            <div className="relative w-full h-full flex flex-col items-center justify-center pointer-events-none">
              <div className="absolute top-4 right-4 flex gap-4 z-10 pointer-events-auto">
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    const fetchAndDownload = async () => {
                      try {
                        const response = await fetch(zoomImage);
                        const blob = await response.blob();
                        const blobUrl = window.URL.createObjectURL(blob);
                        const link = document.createElement('a');
                        link.href = blobUrl;
                        link.download = 'whatsapp-image.jpg';
                        document.body.appendChild(link);
                        link.click();
                        document.body.removeChild(link);
                        window.URL.revokeObjectURL(blobUrl);
                      } catch (error) {
                        window.open(zoomImage, '_blank');
                      }
                    };
                    fetchAndDownload();
                  }}
                  className="p-2 text-white bg-white/10 hover:bg-white/20 rounded-full transition-colors"
                  title="Download"
                >
                  <svg viewBox="0 0 24 24" width="24" height="24" fill="currentColor">
                    <path d="M19 9h-4V3H9v6H5l7 7 7-7zM5 18v2h14v-2H5z" />
                  </svg>
                </button>
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    setZoomImage(null);
                  }}
                  className="p-2 text-white bg-white/10 hover:bg-white/20 rounded-full transition-colors"
                  title="Close"
                >
                  <svg viewBox="0 0 24 24" width="24" height="24" fill="currentColor">
                    <path d="M19 6.41L17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12 19 6.41z" />
                  </svg>
                </button>
              </div>
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img
                src={zoomImage}
                alt="Zoomed Image"
                className="max-w-full max-h-[90vh] object-contain pointer-events-auto cursor-default"
                onClick={(e) => e.stopPropagation()}
              />
            </div>
          </div>
        )}

        {/* Reassignment Confirmation Modal */}
        {confirmAssign && (
          <div className="fixed inset-0 z-[110] flex items-center justify-center bg-black/60 p-4 backdrop-blur-sm animate-in fade-in duration-200">
            <div className="bg-white rounded-2xl shadow-2xl max-w-sm w-full overflow-hidden animate-in zoom-in-95 duration-200">
              <div className="p-6 text-center">
                <div className="w-16 h-16 bg-primary/10 rounded-full flex items-center justify-center mx-auto mb-4 text-primary">
                  <svg viewBox="0 0 24 24" width="32" height="32" fill="currentColor">
                    <path d="M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z" />
                  </svg>
                </div>
                <h3 className="text-xl font-bold text-gray-900 mb-2">Confirm Reassignment</h3>
                <p className="text-gray-500 mb-6">
                  Are you sure you want to assign this chat to <strong className="text-gray-900">{confirmAssign.name}</strong>?
                </p>
                <div className="flex gap-3">
                  <button
                    onClick={() => setConfirmAssign(null)}
                    className="flex-1 px-4 py-2.5 rounded-xl border border-gray-200 text-gray-700 font-medium hover:bg-gray-50 transition-colors"
                  >
                    Cancel
                  </button>
                  <button
                    onClick={executeAssignment}
                    className="flex-1 px-4 py-2.5 rounded-xl bg-gradient-primary text-white font-medium hover:opacity-90 transition-opacity shadow-lg shadow-primary/20"
                  >
                    Confirm
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Toast notification for staff when assigned a chat */}
        {toast && (
          <div className="fixed bottom-6 right-6 z-[200] flex items-start gap-3 bg-white border border-gray-200 shadow-2xl rounded-2xl px-5 py-4 max-w-sm animate-in slide-in-from-bottom-4 duration-300">
            <div className="w-10 h-10 rounded-full bg-[#00a884]/10 flex items-center justify-center text-[#00a884] flex-shrink-0 mt-0.5">
              <svg viewBox="0 0 24 24" width="22" height="22" fill="currentColor">
                <path d="M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z" />
              </svg>
            </div>
            <div className="flex-1 min-w-0">
              <p className="text-sm font-semibold text-gray-900">Chat Assigned</p>
              <p className="text-sm text-gray-500 mt-0.5">{toast.message}</p>
            </div>
            <button
              onClick={() => setToast(null)}
              className="text-gray-400 hover:text-gray-600 transition-colors ml-1 mt-0.5 flex-shrink-0"
            >
              <svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor">
                <path d="M19 6.41L17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12 19 6.41z" />
              </svg>
            </button>
          </div>
        )}

        {/* Close Chat Confirmation Modal */}
        <Modal
          isOpen={showCloseModal}
          onClose={() => setShowCloseModal(false)}
          title="Complete Chat"
        >
          <div className="space-y-6">
            <p className="text-gray-600">
              Are you sure you want to complete this chat? It will be moved to the closed status.
            </p>
            <div className="flex justify-end gap-3 pt-4 border-t border-gray-100">
              <button
                onClick={() => setShowCloseModal(false)}
                className="px-4 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-lg hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary"
              >
                Cancel
              </button>
              <button
                onClick={handleCloseChat}
                disabled={isClosing}
                className="px-4 py-2 text-sm font-medium text-white bg-green-600 rounded-lg hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-green-500 disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
              >
                {isClosing ? 'Completing...' : 'Complete Chat'}
              </button>
            </div>
          </div>
        </Modal>

        {/* Reopen Chat Confirmation Modal */}
        <Modal
          isOpen={showReopenModal}
          onClose={() => setShowReopenModal(false)}
          title="Reopen Chat"
        >
          <div className="space-y-6">
            <p className="text-gray-600">
              Are you sure you want to reopen this chat? It will be moved back to <strong>Open</strong> status and staff can continue messaging the customer.
            </p>
            <div className="flex justify-end gap-3 pt-4 border-t border-gray-100">
              <button
                onClick={() => setShowReopenModal(false)}
                className="px-4 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-lg hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary"
              >
                Cancel
              </button>
              <button
                onClick={() => { setShowReopenModal(false); handleReopenChat() }}
                disabled={isReopening}
                className="px-4 py-2 text-sm font-medium text-white bg-green-600 rounded-lg hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-green-500 disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
              >
                {isReopening ? 'Reopening...' : '↩ Yes, Reopen Chat'}
              </button>
            </div>
          </div>
        </Modal>

        {/* Chat Template Modal */}
        {chat && (
          <ChatTemplateModal
            isOpen={isTemplateModalOpen}
            onClose={() => setIsTemplateModalOpen(false)}
            onSuccess={(sentMessage?: any) => {
              setIsTemplateModalOpen(false)
              if (sentMessage && sentMessage._id) {
                // Register the confirmed ID so the socket event is ignored
                confirmedMessageIds.current.add(sentMessage._id)
                // Add the message to the chat instantly (skip if already present from socket)
                setMessages(prev => {
                  if (prev.some(m => m._id === sentMessage._id)) return prev
                  return [...prev, sentMessage]
                })
              } else {
                // Fallback: reload chat data if no message returned
                loadChatData()
              }
            }}
            chatId={chat._id}
            wabaId={typeof chat.wabaId === 'object' && chat.wabaId !== null ? (chat.wabaId as any)._id : chat.wabaId}
          />
        )}

        {/* Context Menu */}
        {contextMenuMsg && (
          <div
            className="fixed z-[100] bg-white rounded-lg shadow-xl border border-gray-100 py-1.5 min-w-[160px] text-sm text-gray-700 font-medium overflow-hidden"
            style={{
              top: contextMenuMsg.y,
              left: contextMenuMsg.x,
            }}
            onClick={(e) => e.stopPropagation()}
          >
            <button
              onClick={() => {
                setReplyingToMsg(contextMenuMsg.message)
                setContextMenuMsg(null)
                composerInputRef.current?.focus()
              }}
              className="w-full text-left px-4 py-2 hover:bg-gray-100 flex items-center gap-2 transition-colors"
            >
              <svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor" className="text-gray-500"><path d="M10 9V5l-7 7 7 7v-4.1c5 0 8.5 1.6 11 5.1-1-5-4-10-11-11z" /></svg>
              Reply
            </button>
            <button
              onClick={() => {
                const textToCopy = contextMenuMsg.message.text || contextMenuMsg.message.caption
                if (textToCopy) {
                  navigator.clipboard.writeText(textToCopy)
                }
                setContextMenuMsg(null)
              }}
              className="w-full text-left px-4 py-2 hover:bg-gray-100 flex items-center gap-2 transition-colors"
            >
              <svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor" className="text-gray-500"><path d="M16 1H4c-1.1 0-2 .9-2 2v14h2V3h12V1zm3 4H8c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h11c1.1 0 2-.9 2-2V7c0-1.1-.9-2-2-2zm0 16H8V7h11v14z" /></svg>
              Copy
            </button>
            {contextMenuMsg.isOutbound && (
              <button
                onClick={() => {
                  setActiveReactionMsg(contextMenuMsg.message._id)
                  setContextMenuMsg(null)
                }}
                className="w-full text-left px-4 py-2 hover:bg-gray-100 flex items-center gap-2 transition-colors"
              >
                <svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor" className="text-gray-500"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm3.5 14H8.5c-.28 0-.5-.22-.5-.5s.22-.5.5-.5h7c.28 0 .5.22.5.5s-.22.5-.5.5zm1.5-3H7V11h10v2zm0-4H7V7h10v2z" /></svg>
                Like
              </button>
            )}
            <div className="w-full bg-gray-100 h-[1px] my-1"></div>
            <button
              onClick={async () => {
                try {
                  await chatsApi.deleteMessage(contextMenuMsg.message._id)
                } catch (e) {
                  console.error('Delete message error', e)
                }
                setContextMenuMsg(null)
              }}
              className="w-full text-left px-4 py-2 hover:bg-red-50 text-red-600 flex items-center gap-2 transition-colors font-semibold"
            >
              <svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor" className="text-red-500"><path d="M6 19c0 1.1.9 2 2 2h8c1.1 0 2-.9 2-2V7H6v12zm2.46-7.12l1.41-1.41L12 12.59l2.12-2.12 1.41 1.41L13.41 14l2.12 2.12-1.41 1.41L12 15.41l-2.12 2.12-1.41-1.41L10.59 14l-2.13-2.12zM15.5 4l-1-1h-5l-1 1H5v2h14V4z" /></svg>
              Delete
            </button>
          </div>
        )}
      </div>

      <Modal isOpen={showNicknameModal} onClose={() => setShowNicknameModal(false)} title="Edit Nickname">
        <form onSubmit={handleUpdateNickname}>
          <div className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Nickname
              </label>
              <input
                type="text"
                value={nicknameInput}
                onChange={(e) => setNicknameInput(e.target.value)}
                placeholder="Enter a custom name..."
                className="w-full rounded-lg border border-gray-300 py-2 px-3 text-sm focus:border-primary focus:outline-none focus:ring-1 focus:ring-primary"
                autoFocus
              />
              <p className="mt-2 text-xs text-gray-500">
                This name will be displayed instead of their WhatsApp name. Clear the input to use their original name.
              </p>
            </div>
            <div className="flex justify-end gap-3 pt-4 border-t border-gray-100">
              <button
                type="button"
                onClick={() => setShowNicknameModal(false)}
                className="px-4 py-2 text-sm font-medium text-gray-700 hover:bg-gray-100 rounded-lg transition-colors"
              >
                Cancel
              </button>
              <button
                type="submit"
                disabled={isUpdatingNickname}
                className="px-4 py-2 bg-primary text-white text-sm font-medium rounded-lg hover:bg-primary/90 transition-colors disabled:opacity-50"
              >
                {isUpdatingNickname ? 'Saving...' : 'Save Nickname'}
              </button>
            </div>
          </div>
        </form>
      </Modal>

      {/* Paste Image Preview Modal */}
      {pastedImage && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg overflow-hidden flex flex-col animate-in zoom-in-95 duration-200">
            <div className="p-4 border-b border-gray-100 flex items-center justify-between">
              <h3 className="font-semibold text-gray-900">Send Screenshot?</h3>
              <button 
                onClick={() => setPastedImage(null)}
                className="p-1 hover:bg-gray-100 rounded-full transition-colors"
              >
                <svg viewBox="0 0 24 24" width="20" height="20" fill="currentColor" className="text-gray-500">
                  <path d="M19 6.41L17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12z" />
                </svg>
              </button>
            </div>

            <div className="flex-1 bg-gray-50 p-4 flex items-center justify-center min-h-[300px] max-h-[60vh] overflow-hidden">
              {/* eslint-disable-next-line @next/next/no-img-element */}
              {pastedImageUrl && (
                <img 
                  src={pastedImageUrl} 
                  alt="Pasted Preview" 
                  className="max-w-full max-h-full object-contain rounded-lg shadow-md"
                />
              )}
            </div>

            <div className="p-4 border-t border-gray-100 flex justify-end gap-3 bg-white">
              <button
                onClick={() => setPastedImage(null)}
                className="px-6 py-2.5 text-sm font-medium text-gray-700 hover:bg-gray-100 rounded-xl transition-all"
              >
                Cancel
              </button>
              <button
                onClick={() => {
                  processFile(pastedImage);
                  setPastedImage(null);
                }}
                className="px-8 py-2.5 bg-[#00a884] text-white text-sm font-semibold rounded-xl hover:bg-[#008f6f] transition-all shadow-md shadow-green-200 flex items-center gap-2"
              >
                <svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor">
                  <path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z" />
                </svg>
                Send Image
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Incoming Call Banner */}
      {incomingCall && (
        <div className="fixed top-4 left-1/2 -translate-x-1/2 z-[200] animate-in slide-in-from-top duration-300">
          <div className="bg-white rounded-2xl shadow-2xl border border-gray-200 px-6 py-4 flex items-center gap-4 min-w-[360px]">
            <div className="w-12 h-12 rounded-full bg-green-100 flex items-center justify-center animate-pulse">
              <svg viewBox="0 0 24 24" width="24" height="24" fill="#16a34a">
                <path d="M20.01 15.38c-1.23 0-2.42-.2-3.53-.56a.977.977 0 00-1.01.24l-1.57 1.97c-2.83-1.35-5.48-3.9-6.89-6.83l1.95-1.66c.27-.28.35-.67.24-1.02-.37-1.11-.56-2.3-.56-3.53 0-.54-.45-.99-.99-.99H4.19C3.65 3 3 3.24 3 3.99 3 13.28 10.73 21 20.01 21c.71 0 .99-.63.99-1.18v-3.45c0-.54-.45-.99-.99-.99z" />
              </svg>
            </div>
            <div className="flex-1">
              <p className="font-semibold text-gray-900 text-sm">Incoming Call</p>
              <p className="text-xs text-gray-500">{formatInternationalPhone(incomingCall.waId)}</p>
            </div>
            <div className="flex items-center gap-2">
              <button
                onClick={() => setIncomingCall(null)}
                className="w-10 h-10 rounded-full bg-red-500 hover:bg-red-600 flex items-center justify-center text-white transition-colors shadow-lg"
                title="Decline"
              >
                <svg viewBox="0 0 24 24" width="20" height="20" fill="currentColor">
                  <path d="M12 9c-1.6 0-3.15.25-4.6.72v3.1c0 .39-.23.74-.56.9-.98.49-1.87 1.12-2.66 1.85-.18.18-.43.28-.7.28-.28 0-.53-.11-.71-.29L.29 13.08c-.18-.17-.29-.42-.29-.7 0-.28.11-.53.29-.71C3.34 8.78 7.46 7 12 7s8.66 1.78 11.71 4.67c.18.18.29.43.29.71 0 .28-.11.53-.29.71l-2.48 2.48c-.18.18-.43.29-.71.29-.27 0-.52-.11-.7-.28a11.27 11.27 0 00-2.67-1.85.996.996 0 01-.56-.9v-3.1C15.15 9.25 13.6 9 12 9z" />
                </svg>
              </button>
              <button
                onClick={() => {
                  setActiveCall(incomingCall)
                  setIncomingCall(null)
                  setCallDuration(0)
                  callTimerRef.current = setInterval(() => setCallDuration(prev => prev + 1), 1000)
                }}
                className="w-10 h-10 rounded-full bg-green-500 hover:bg-green-600 flex items-center justify-center text-white transition-colors shadow-lg"
                title="Accept"
              >
                <svg viewBox="0 0 24 24" width="20" height="20" fill="currentColor">
                  <path d="M20.01 15.38c-1.23 0-2.42-.2-3.53-.56a.977.977 0 00-1.01.24l-1.57 1.97c-2.83-1.35-5.48-3.9-6.89-6.83l1.95-1.66c.27-.28.35-.67.24-1.02-.37-1.11-.56-2.3-.56-3.53 0-.54-.45-.99-.99-.99H4.19C3.65 3 3 3.24 3 3.99 3 13.28 10.73 21 20.01 21c.71 0 .99-.63.99-1.18v-3.45c0-.54-.45-.99-.99-.99z" />
                </svg>
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Active Call Bar */}
      {activeCall && (
        <div className="fixed bottom-20 left-1/2 -translate-x-1/2 z-[150]">
          <div className="bg-green-600 text-white rounded-full px-5 py-2.5 flex items-center gap-3 shadow-xl">
            <span className="w-2.5 h-2.5 bg-white rounded-full animate-pulse"></span>
            <span className="text-sm font-medium">
              {activeCall.direction === 'inbound' ? 'Incoming' : 'Outgoing'} Call · {Math.floor(callDuration / 60)}:{(callDuration % 60).toString().padStart(2, '0')}
            </span>
            <button
              onClick={async () => {
                try {
                  await callsApi.terminateCall(activeCall._id)
                  setActiveCall(null)
                  setCallDuration(0)
                  if (callTimerRef.current) clearInterval(callTimerRef.current)
                } catch (err: any) {
                  hotToast.error(err.response?.data?.error || 'End call failed')
                }
              }}
              className="ml-1 w-8 h-8 rounded-full bg-red-500 hover:bg-red-600 flex items-center justify-center transition-colors"
              title="End call"
            >
              <svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor">
                <path d="M12 9c-1.6 0-3.15.25-4.6.72v3.1c0 .39-.23.74-.56.9-.98.49-1.87 1.12-2.66 1.85-.18.18-.43.28-.7.28-.28 0-.53-.11-.71-.29L.29 13.08c-.18-.17-.29-.42-.29-.7 0-.28.11-.53.29-.71C3.34 8.78 7.46 7 12 7s8.66 1.78 11.71 4.67c.18.18.29.43.29.71 0 .28-.11.53-.29.71l-2.48 2.48c-.18.18-.43.29-.71.29-.27 0-.52-.11-.7-.28a11.27 11.27 0 00-2.67-1.85.996.996 0 01-.56-.9v-3.1C15.15 9.25 13.6 9 12 9z" />
              </svg>
            </button>
          </div>
        </div>
      )}

      {/* Call Log Panel */}
      <CallLogPanel
        chatId={chatId}
        isOpen={showCallLogs}
        onClose={() => setShowCallLogs(false)}
      />
    </div>
  )
}

'use client'

import Link from 'next/link'
import { formatInternationalPhone } from '@/lib/phone'
import { useParams, useSearchParams, useRouter } from 'next/navigation'
import { useState, useEffect, useRef } from 'react'
import { chatsApi } from '@/lib/api/chats'
import { useSocket } from '@/lib/hooks/useSocket'
import { useAuthStore } from '@/store/authStore'
import { usersApi } from '@/lib/api/users'
import { wabaApi, Waba } from '@/lib/api/wabas'
import { tagsApi, Tag } from '@/lib/api/tags'
import { User } from '@/lib/api/auth'
import StartChatModal from '@/components/chat/StartChatModal'

type ChatFilterTab = 'all' | 'open' | 'waiting' | 'unread' | 'closed'

export default function ChatLayoutClient() {
    const params = useParams()
    const searchParams = useSearchParams()
    const router = useRouter()
    const activeChatId = params.id as string | undefined

    const [chats, setChats] = useState<any[]>([])
    const [loading, setLoading] = useState(true)
    const tabFromUrl = (searchParams.get('tab') as ChatFilterTab) || 'open'
    const [activeTab, setActiveTab] = useState<ChatFilterTab>(tabFromUrl)
    const [counts, setCounts] = useState({ all: 0, open: 0, waiting: 0, unread: 0, closed: 0 })
    const { socket } = useSocket()
    const { user } = useAuthStore()
    const isStaff = user?.role === 'staff'
    const isAdmin = user?.role === 'admin' || user?.role === 'superadmin'

    const [staffList, setStaffList] = useState<User[]>([])
    const [wabaList, setWabaList] = useState<Waba[]>([])
    const [availableTags, setAvailableTags] = useState<Tag[]>([])
    const [filterStaffId, setFilterStaffId] = useState('')
    const [filterWabaId, setFilterWabaId] = useState('')
    const [filterTagId, setFilterTagId] = useState('') // New
    const [toast, setToast] = useState<{ message: string; chatId: string } | null>(null)
    const [incomingCallAlert, setIncomingCallAlert] = useState<{ chatId: string; waId: string } | null>(null)

    // Search state
    const [searchQuery, setSearchQuery] = useState('')
    const [searchResults, setSearchResults] = useState<any[]>([])
    const [searchLoading, setSearchLoading] = useState(false)
    const searchTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null)
    const isSearchActive = searchQuery.trim().length > 0

    // UI state for Inbox column
    const [isMyChatsOpen, setIsMyChatsOpen] = useState(true)
    const [isTeamMemberOpen, setIsTeamMemberOpen] = useState(true)
    const [isTagsOpen, setIsTagsOpen] = useState(true)
    const [isWabasOpen, setIsWabasOpen] = useState(true)

    // Start chat modal state
    const [showStartChatModal, setShowStartChatModal] = useState(false)

    useEffect(() => {
        if (isAdmin) {
            loadFilters()
        }
        loadTags()
    }, [isAdmin])

    const loadFilters = async () => {
        try {
            const [u, w] = await Promise.all([
                usersApi.list({ limit: 100 }),
                wabaApi.list()
            ])
            setStaffList(u.users)
            setWabaList(w)
        } catch (e) {
            console.error('Failed to load admin filters', e)
        }
    }

    const loadTags = async () => {
        try {
            const tags = await tagsApi.list()
            setAvailableTags(tags)
        } catch (error) {
            console.error('Failed to load tags', error)
        }
    }

    useEffect(() => {
        loadChats()
        loadCounts()
    }, [activeTab, filterStaffId, filterWabaId, filterTagId])

    const loadCounts = async () => {
        try {
            const queryParams: any = {}
            if (filterWabaId) queryParams.wabaId = filterWabaId
            if (filterTagId) queryParams.tagId = filterTagId
            if (isStaff && user?._id) {
                queryParams.assignedTo = user._id
            } else if (filterStaffId) {
                queryParams.assignedTo = filterStaffId
            }

            const data = await chatsApi.getStats(queryParams)
            setCounts(data)
        } catch (error) {
            console.error('Failed to load chat counts:', error)
        }
    }

    useEffect(() => {
        if (!socket) return

        const handleChatUpdate = () => {
            if (!isSearchActive) {
                loadChats()
                loadCounts()
            }
        }

        socket.on('chat:update', handleChatUpdate)
        socket.on('message:new', handleChatUpdate)
        socket.on('chat:new', handleChatUpdate)

        const handleAssignedToMe = (data: { chatId: string; chat: any; assignedByName: string }) => {
            loadChats()
            loadCounts()
            setToast({
                message: `Chat assigned to you by ${data.assignedByName}`,
                chatId: data.chatId,
            })
            setTimeout(() => setToast(null), 6000)
        }
        socket.on('chat:assigned:me', handleAssignedToMe)

        const handleIncomingCall = (data: { chatId?: string; callLog?: { waId?: string } }) => {
            if (!data?.chatId) return
            setIncomingCallAlert({ chatId: data.chatId, waId: data?.callLog?.waId || '' })
        }

        const clearCallAlert = (data: { chatId?: string }) => {
            if (!data?.chatId) return
            setIncomingCallAlert((prev) => (prev?.chatId === data.chatId ? null : prev))
        }

        socket.on('call:incoming', handleIncomingCall)
        socket.on('call:status', clearCallAlert)
        socket.on('call:terminated', clearCallAlert)

        return () => {
            socket.off('chat:update', handleChatUpdate)
            socket.off('message:new', handleChatUpdate)
            socket.off('chat:new', handleChatUpdate)
            socket.off('chat:assigned:me', handleAssignedToMe)
            socket.off('call:incoming', handleIncomingCall)
            socket.off('call:status', clearCallAlert)
            socket.off('call:terminated', clearCallAlert)
        }
    }, [socket, activeTab, filterStaffId, filterWabaId, filterTagId, isStaff, user?._id, isSearchActive])

    const loadChats = async () => {
        try {
            setLoading(true)
            let queryParams: any = {}

            if (activeTab === 'open') queryParams.status = 'open'
            if (activeTab === 'closed') queryParams.status = 'closed'
            if (activeTab === 'waiting') queryParams.isWaiting = true
            if (activeTab === 'unread') queryParams.isUnread = true

            if (filterWabaId) queryParams.wabaId = filterWabaId
            if (filterTagId) queryParams.tags = filterTagId

            if (isStaff && user?._id) {
                queryParams.assignedTo = user._id
            } else if (filterStaffId) {
                queryParams.assignedTo = filterStaffId
            }

            const data = await chatsApi.list(queryParams)
            setChats(data.chats || [])
        } catch (error) {
            console.error('Failed to load chats:', error)
        } finally {
            setLoading(false)
        }
    }

    // Debounced search
    const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const value = e.target.value
        setSearchQuery(value)

        if (searchTimeoutRef.current) clearTimeout(searchTimeoutRef.current)

        if (value.trim().length === 0) {
            setSearchResults([])
            setSearchLoading(false)
            return
        }

        setSearchLoading(true)
        searchTimeoutRef.current = setTimeout(async () => {
            try {
                const params: any = {}
                if (filterWabaId) params.wabaId = filterWabaId
                const data = await chatsApi.search(value.trim(), params)
                setSearchResults(data.chats || [])
            } catch (err) {
                console.error('Search failed', err)
                setSearchResults([])
            } finally {
                setSearchLoading(false)
            }
        }, 350)
    }

    const clearSearch = () => {
        setSearchQuery('')
        setSearchResults([])
        if (searchTimeoutRef.current) clearTimeout(searchTimeoutRef.current)
    }

    const handleChatCreated = (chatId: string) => {
        // Navigate to the newly created chat
        router.push(`/chats/${chatId}`)
    }

    const displayedChats = isSearchActive ? searchResults : chats
    const displayedLoading = isSearchActive ? searchLoading : loading

    const tabs = [
        { id: 'open', label: 'Open', count: counts.open },
        { id: 'closed', label: 'Closed', count: counts.closed },
        { id: 'waiting', label: 'Awaiting reply', count: counts.waiting },
        { id: 'unread', label: 'Unread', count: counts.unread },
        { id: 'all', label: 'All', count: counts.all },
    ]

    // Column width config
    const col2Width = 'w-64'
    const col3Width = 'w-72 lg:w-80'

    // If a chat is active on mobile, hide the list columns
    const hideListOnMobile = activeChatId ? 'hidden md:flex' : 'flex'

    return (
        <>
            <div className={`shrink-0 hidden lg:flex bg-white border-r border-gray-200 flex-col h-full overflow-y-auto w-64`}>
                {/* Inbox Sidebar (Column 2) */}
                <div className="p-4 border-b border-gray-200 flex items-center justify-between">
                    <div className="flex items-center gap-2">
                        <div className="w-8 h-8 rounded bg-green-100 flex items-center justify-center text-green-700 font-bold">
                            {user?.name?.charAt(0) || 'B'}
                        </div>
                        <h2 className="font-semibold text-gray-900">Inbox</h2>
                    </div>
                    <div className="flex gap-2">
                        <button className="text-gray-500 hover:text-gray-700">
                            <svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" strokeWidth="2"><circle cx="12" cy="12" r="10" /><path d="M12 8v4l3 3" /></svg>
                        </button>
                        <button className="text-gray-500 hover:text-gray-700">
                            <svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" strokeWidth="2"><path d="M21 15a2 2 0 01-2 2H7l-4 4V5a2 2 0 012-2h14a2 2 0 012 2z" /></svg>
                        </button>
                    </div>
                </div>

                <div className="p-2 flex-1 flex flex-col gap-1">
                    {/* My chats accordion */}
                    <div>
                        <button
                            onClick={() => setIsMyChatsOpen(!isMyChatsOpen)}
                            className="w-full flex items-center justify-between px-3 py-2 text-sm text-gray-700 hover:bg-gray-100 rounded-md font-medium"
                        >
                            <div className="flex items-center gap-2">
                                <svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor" className="text-gray-400"><path d="M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z" /></svg>
                                My chats
                            </div>
                            <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="2" className={`transform transition-transform ${isMyChatsOpen ? 'rotate-180' : ''}`}><path d="M19 9l-7 7-7-7" /></svg>
                        </button>
                        {isMyChatsOpen && (
                            <div className="mt-1 ml-6 space-y-1">
                                {tabs.map(tab => (
                                    <button
                                        key={tab.id}
                                        onClick={() => setActiveTab(tab.id as ChatFilterTab)}
                                        className={`w-full flex items-center justify-between px-3 py-1.5 text-sm rounded-md ${activeTab === tab.id ? 'bg-green-50 text-green-700 font-medium' : 'text-gray-600 hover:bg-gray-50'}`}
                                    >
                                        {tab.label}
                                        {tab.count > 0 && (
                                            <span className="text-xs text-gray-500">{tab.count}</span>
                                        )}
                                    </button>
                                ))}
                            </div>
                        )}
                    </div>

                    {/* Quick filters */}
                    <div className="mt-4 mb-2">
                        <button
                            onClick={() => setFilterStaffId('null')}
                            className={`w-full flex items-center gap-2 px-3 py-2 text-sm rounded-md cursor-pointer ${filterStaffId === 'null' ? 'bg-green-50 text-green-700' : 'text-gray-700 hover:bg-gray-100'}`}>
                            <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="2" className="text-gray-400"><path d="M12 2A10 10 0 0 0 2 12a10 10 0 0 0 10 10 10 10 0 0 0 10-10A10 10 0 0 0 12 2m0 14.5c-2.5 0-4.71-1.28-6-3.22.03-1.99 4-3.08 6-3.08 1.99 0 5.97 1.09 6 3.08-1.29 1.94-3.5 3.22-6 3.22m0-8.5a2.5 2.5 0 0 1-2.5-2.5A2.5 2.5 0 0 1 12 3a2.5 2.5 0 0 1 2.5 2.5A2.5 2.5 0 0 1 12 8" /></svg>
                            Unassigned
                        </button>
                    </div>

                    <hr className="border-gray-200 my-2" />

                    {/* Team member */}
                    {isAdmin && (
                        <div>
                            <button
                                onClick={() => setIsTeamMemberOpen(!isTeamMemberOpen)}
                                className="w-full flex items-center justify-between px-3 py-2 text-sm text-gray-700 hover:bg-gray-100 rounded-md font-medium"
                            >
                                Team member
                                <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="2" className={`transform transition-transform ${isTeamMemberOpen ? 'rotate-180' : ''}`}><path d="M19 9l-7 7-7-7" /></svg>
