                                <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="2" className={`transform transition-transform ${isWabasOpen ? 'rotate-180' : ''}`}><path d="M19 9l-7 7-7-7" /></svg>
                            </button>
                            {isWabasOpen && (
