                                                            {chat.wabaId.businessName}
                                                        </span>
                                                    )}
                                                    {chat.isUnread && (
                                                        <span className="w-4 h-4 rounded-full bg-green-500 text-white text-[10px] flex items-center justify-center font-bold">
                                                            1
                                                        </span>
                                                    )}
                                                </div>
                                                <p className="text-xs text-gray-500 whitespace-nowrap ml-2">
                                                    {chat.lastMessageAt && new Date(chat.lastMessageAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: true })}
                                                </p>
                                            </div>
                                            {/* Show matched message snippet when search matched by message content */}
                                            {isSearchActive && chat.matchSource === 'message' && chat.matchedMessage ? (
                                                <div className="flex items-center gap-1 mt-0.5">
                                                    <svg viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" strokeWidth="2" className="text-green-500 flex-shrink-0">
                                                        <circle cx="11" cy="11" r="8" />
                                                        <path d="m21 21-4.35-4.35" />
                                                    </svg>
                                                    <p className="text-xs text-green-700 truncate flex-1 italic">
                                                        &quot;{chat.matchedMessage.length > 60 ? chat.matchedMessage.substring(0, 60) + '…' : chat.matchedMessage}&quot;
                                                    </p>
                                                </div>
                                            ) : (
                                                 <div className="flex items-center gap-1 w-full overflow-hidden">
                                                     {chat.lastMessageDirection === 'outbound' && (
                                                         (() => {
                                                             switch (chat.lastMessageStatus) {
                                                                 case 'read':
                                                                     return (
                                                                         <svg viewBox="0 0 16 15" width="14" height="14" fill="currentColor" className="text-[#53bdeb] flex-shrink-0">
                                                                             <path d="M15.01 3.316l-.478-.372a.365.365 0 0 0-.51.063L8.666 9.879a.32.32 0 0 1-.484.033l-.358-.325a.32.32 0 0 0-.484.032l-.378.483a.418.418 0 0 0 .036.541l1.32 1.266c.143.14.361.125.484-.033l6.272-8.048a.366.366 0 0 0-.064-.512zm-4.1 0l-.478-.372a.365.365 0 0 0-.51.063L4.566 9.879a.32.32 0 0 1-.484.033L1.891 7.769a.366.366 0 0 0-.515.006l-.423.433a.364.364 0 0 0 .006.514l3.258 3.185c.143.14.361.125.484-.033l6.272-8.048a.365.365 0 0 0-.063-.51z" />
                                                                         </svg>
                                                                     );
                                                                 case 'delivered':
                                                                     return (
                                                                         <svg viewBox="0 0 16 15" width="14" height="14" fill="currentColor" className="text-gray-400 flex-shrink-0">
                                                                             <path d="M15.01 3.316l-.478-.372a.365.365 0 0 0-.51.063L8.666 9.879a.32.32 0 0 1-.484.033l-.358-.325a.32.32 0 0 0-.484.032l-.378.483a.418.418 0 0 0 .036.541l1.32 1.266c.143.14.361.125.484-.033l6.272-8.048a.366.366 0 0 0-.064-.512zm-4.1 0l-.478-.372a.365.365 0 0 0-.51.063L4.566 9.879a.32.32 0 0 1-.484.033L1.891 7.769a.366.366 0 0 0-.515.006l-.423.433a.364.364 0 0 0 .006.514l3.258 3.185c.143.14.361.125.484-.033l6.272-8.048a.365.365 0 0 0-.063-.51z" />
                                                                         </svg>
