          },
        },
      },
      {
        headers: {
          Authorization: `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
      }
    );

    logger.info(`Call permission request sent to ${to}, response: ${JSON.stringify(res.data)}`);

