  const [showCloseModal, setShowCloseModal] = useState(false)
  const [showReopenModal, setShowReopenModal] = useState(false)
  const [isClosing, setIsClosing] = useState(false)
  const [isReopening, setIsReopening] = useState(false)

  const [showNicknameModal, setShowNicknameModal] = useState(false)
  const [nicknameInput, setNicknameInput] = useState('')
  const [isUpdatingNickname, setIsUpdatingNickname] = useState(false)

  const [isTogglingDnd, setIsTogglingDnd] = useState(false)
  const [isBlockingContact, setIsBlockingContact] = useState(false)
  const [isTogglingOptOut, setIsTogglingOptOut] = useState(false)

  // Navigate to a message by id, highlight it briefly and attempt to load older messages if needed
  const navigateToMessage = (targetMsgId?: string | null) => {
    if (!targetMsgId) return
    // try to map to local message _id when messageId refers to external id
    const localMatch = messages.find((m) => m.messageId === targetMsgId || m._id === targetMsgId)
    const localId = localMatch?._id || targetMsgId
    setHighlightedMessageId(localId)
    // clear highlight after 2s
    setTimeout(() => setHighlightedMessageId((current) => (current === localId ? null : current)), 2000)

    const scrollToElement = () => {
      const el = document.querySelector(`[data-message-id="${localId}"]`)
      if (el) {
        ;(el as HTMLElement).scrollIntoView({ behavior: 'smooth', block: 'center' })
        return true
      }
      return false
    }

    if (scrollToElement()) return

    // If element not found, attempt to load older messages by nudging scroll and polling
    let attempts = 0
    const iv = setInterval(() => {
      attempts += 1
      if (scrollToElement()) {
        clearInterval(iv)
        return
      }
      // nudge scroll up to encourage lazy-loading older messages
      window.scrollBy({ top: -600, left: 0, behavior: 'smooth' })
      if (attempts >= 12) clearInterval(iv)
    }, 300)
  }

  const [isRecording, setIsRecording] = useState(false)
  const [recordingDuration, setRecordingDuration] = useState(0)
  const [recordedAudio, setRecordedAudio] = useState<{ blob: Blob; url: string; duration: number } | null>(null)
  const [voiceMessageError, setVoiceMessageError] = useState<string | null>(null)
  const mediaRecorderRef = useRef<MediaRecorder | null>(null)
  const audioChunksRef = useRef<BlobPart[]>([])
  const recordingTimerRef = useRef<NodeJS.Timeout | null>(null)
  const fileInputRef = useRef<HTMLInputElement>(null)

  // Quick Replies (Slash Commands)
  const [quickReplies, setQuickReplies] = useState<QuickReply[]>([])
  const [showQuickReplies, setShowQuickReplies] = useState(false)
  const [quickReplyQuery, setQuickReplyQuery] = useState('')
  const [selectedQuickReplyIdx, setSelectedQuickReplyIdx] = useState(0)
  const [quickReplyTab, setQuickReplyTab] = useState<'all' | 'me'>('all')
  const quickReplyRef = useRef<HTMLDivElement>(null)

  // Automated Messages Panel
  const [showAutoMessages, setShowAutoMessages] = useState(false)
  const [autoMessages, setAutoMessages] = useState<AutoMessage[]>([])
  const [autoMessagesTotal, setAutoMessagesTotal] = useState(0)
  const [autoMessagesLoading, setAutoMessagesLoading] = useState(false)

  // Calling state
  const [showCallMenu, setShowCallMenu] = useState(false)
  const [showCallLogs, setShowCallLogs] = useState(false)
  const [activeCall, setActiveCall] = useState<CallLog | null>(null)
  const [incomingCall, setIncomingCall] = useState<CallLog | null>(null)
  const [callDuration, setCallDuration] = useState(0)
  const [isInitiatingCall, setIsInitiatingCall] = useState(false)
  const [isJoiningCallAudio, setIsJoiningCallAudio] = useState(false)
  const callTimerRef = useRef<NodeJS.Timeout | null>(null)
  const livekitRoomRef = useRef<Room | null>(null)

  const messagesEndRef = useRef<HTMLDivElement>(null)
  const messagesContainerRef = useRef<HTMLDivElement>(null)
  const isInitialLoadRef = useRef(true)
  // Tracks message _ids confirmed via HTTP response so the subsequent socket
  // broadcast for the same message is ignored (prevents duplicates).
  const confirmedMessageIds = useRef<Set<string>>(new Set())
  // Stores original send data for failed messages so they can be retried
  const failedMessageData = useRef<Map<string, { type: string; mediaUrl?: string; text?: string; caption?: string }>>(new Map())
  const [retryingMsgId, setRetryingMsgId] = useState<string | null>(null)
  const [pastedImage, setPastedImage] = useState<File | null>(null)
  const [pastedImageUrl, setPastedImageUrl] = useState<string | null>(null)
  const composerInputRef = useRef<HTMLTextAreaElement>(null)
