    setAiError(null)
    aiMessageService.cancel()

    setSending(true)

    try {
      if (isNote) {
        // Optimistic update
        const tempMessage: Message = {
          _id: 'temp-' + Date.now(),
          chatId,
          waId: chat?.waId || '',
          direction: 'internal',
          type: 'note',
          text: textToSend,
          status: 'sent',
          createdAt: new Date().toISOString()
        }
        setMessages(prev => [...prev, tempMessage])

        const savedMsg = await chatsApi.addNote(chatId, textToSend)
        setMessages(prev => prev.map(m => m._id === tempMessage._id ? savedMsg : m))
      } else {
        // Optimistic update
