  const processFile = async (file: File, forceDocument = false) => {
    if (sending) return
    setSending(true)
    try {
      const formData = new FormData()
      formData.append('file', file)

      let type = 'document'
      if (!forceDocument) {
        if (file.type.startsWith('image/')) type = 'image'
        else if (file.type.startsWith('video/')) type = 'video'
        else if (file.type.startsWith('audio/')) type = 'audio'
      }

      formData.append('type', type)

      // Create local URL for preview if it's an image or video
      let localMediaUrl: string | undefined = undefined;
      if (type === 'image' || type === 'video') {
        localMediaUrl = URL.createObjectURL(file);
      }

      // Optimistic update for file
      const tempMessage: Message = {
        _id: 'temp-' + Date.now(),
        chatId,
        waId: chat?.waId || '',
        direction: 'outbound',
        type: type as any,
        caption: type === 'document' ? file.name : '', // Don't show "Uploading..." as caption for images, we use visual indicators
        mediaUrl: localMediaUrl,
        status: 'sent',
        createdAt: new Date().toISOString()
      }
      setMessages(prev => [...prev, tempMessage])

      const uploadRes = await chatsApi.uploadFile(formData)
      if (!uploadRes.success) throw new Error('Upload failed')

      const replyId = replyingToMsg ? replyingToMsg._id : undefined
      setReplyingToMsg(null)

      const savedMsg = await chatsApi.sendMessage(chatId, { type, mediaUrl: uploadRes.url, caption: type === 'document' ? file.name : '', replyToMessageId: replyId })

      // Register the confirmed ID before replacing temp so the socket event is ignored
      confirmedMessageIds.current.add(savedMsg._id)

      // Replace temp message
      setMessages(prev => prev.map(m => m._id === tempMessage._id ? savedMsg : m))
    } catch (error: any) {
      console.error('Failed to send file:', error)
      // Mark as failed instead of removing — store retry data
      setMessages(prev => prev.map(m => {
        if (m._id.toString().startsWith('temp-')) {
          failedMessageData.current.set(m._id, { type: m.type, mediaUrl: m.mediaUrl, caption: m.caption })
          return { ...m, status: 'failed' as any }
        }
        return m
      }))
    } finally {
      setSending(false)
      if (fileInputRef.current) fileInputRef.current.value = ''
    }
  }

