  // In-chat message search
  const [showMsgSearch, setShowMsgSearch] = useState(false)
  const [msgSearchQuery, setMsgSearchQuery] = useState('')
  const [searchMatchIndex, setSearchMatchIndex] = useState(0)
  const msgSearchInputRef = useRef<HTMLInputElement>(null)
  const [dbSearchMatches, setDbSearchMatches] = useState<Message[]>([])
  const [searchLoading, setSearchLoading] = useState(false)
  const dbSearchTimeoutRef = useRef<NodeJS.Timeout | null>(null)

  // New states for Sidebar, Notes, tags
  const [showInfo, setShowInfo] = useState(false)
  const [isNote, setIsNote] = useState(false)
  const [availableTags, setAvailableTags] = useState<Tag[]>([])
  const [showTagDropdown, setShowTagDropdown] = useState(false)
  const [newTagName, setNewTagName] = useState('')
  const [newTagColor, setNewTagColor] = useState('#00a884')
  const [isCreatingTag, setIsCreatingTag] = useState(false)

  const [activeStaff, setActiveStaff] = useState<UserType[]>([])
  const [isAssigning, setIsAssigning] = useState(false)
  const [confirmAssign, setConfirmAssign] = useState<{ id: string; name: string } | null>(null)
  const [toast, setToast] = useState<{ message: string; chatId: string } | null>(null)
  const { user: currentUser } = useAuthStore()
  const isAdmin = currentUser?.role === 'admin' || currentUser?.role === 'superadmin'
  const isStaff = currentUser?.role === 'staff'
  const canAssign = isAdmin || isStaff

  const [showCloseModal, setShowCloseModal] = useState(false)
  const [showReopenModal, setShowReopenModal] = useState(false)
  const [isClosing, setIsClosing] = useState(false)
  const [isReopening, setIsReopening] = useState(false)

  const [showNicknameModal, setShowNicknameModal] = useState(false)
  const [nicknameInput, setNicknameInput] = useState('')
  const [isUpdatingNickname, setIsUpdatingNickname] = useState(false)

  const [isTogglingDnd, setIsTogglingDnd] = useState(false)
  const [isBlockingContact, setIsBlockingContact] = useState(false)
  const [isTogglingOptOut, setIsTogglingOptOut] = useState(false)

  // Navigate to a message by id, highlight it briefly and attempt to load older messages if needed
  const navigateToMessage = (targetMsgId?: string | null) => {
    if (!targetMsgId) return
    // try to map to local message _id when messageId refers to external id
    const localMatch = messages.find((m) => m.messageId === targetMsgId || m._id === targetMsgId)
    const localId = localMatch?._id || targetMsgId
    setHighlightedMessageId(localId)
    // clear highlight after 2s
    setTimeout(() => setHighlightedMessageId((current) => (current === localId ? null : current)), 2000)

    const scrollToElement = () => {
      const el = document.querySelector(`[data-message-id="${localId}"]`)
      if (el) {
        ;(el as HTMLElement).scrollIntoView({ behavior: 'smooth', block: 'center' })
        return true
      }
      return false
    }

    if (scrollToElement()) return

    // If element not found, attempt to load older messages by nudging scroll and polling
    let attempts = 0
    const iv = setInterval(() => {
      attempts += 1
      if (scrollToElement()) {
        clearInterval(iv)
        return
      }
      // nudge scroll up to encourage lazy-loading older messages
      window.scrollBy({ top: -600, left: 0, behavior: 'smooth' })
      if (attempts >= 12) clearInterval(iv)
    }, 300)
  }

  const [isRecording, setIsRecording] = useState(false)
  const [recordingDuration, setRecordingDuration] = useState(0)
  const [recordedAudio, setRecordedAudio] = useState<{ blob: Blob; url: string; duration: number } | null>(null)
  const [voiceMessageError, setVoiceMessageError] = useState<string | null>(null)
  const mediaRecorderRef = useRef<MediaRecorder | null>(null)
  const audioChunksRef = useRef<BlobPart[]>([])
  const recordingTimerRef = useRef<NodeJS.Timeout | null>(null)
  const fileInputRef = useRef<HTMLInputElement>(null)

  // Quick Replies (Slash Commands)
  const [quickReplies, setQuickReplies] = useState<QuickReply[]>([])
  const [showQuickReplies, setShowQuickReplies] = useState(false)
  const [quickReplyQuery, setQuickReplyQuery] = useState('')
  const [selectedQuickReplyIdx, setSelectedQuickReplyIdx] = useState(0)
  const [quickReplyTab, setQuickReplyTab] = useState<'all' | 'me'>('all')
  const quickReplyRef = useRef<HTMLDivElement>(null)

  // Automated Messages Panel
  const [showAutoMessages, setShowAutoMessages] = useState(false)
  const [autoMessages, setAutoMessages] = useState<AutoMessage[]>([])
  const [autoMessagesTotal, setAutoMessagesTotal] = useState(0)
  const [autoMessagesLoading, setAutoMessagesLoading] = useState(false)

  // Calling state
  const [showCallMenu, setShowCallMenu] = useState(false)
  const [showCallLogs, setShowCallLogs] = useState(false)
  const [activeCall, setActiveCall] = useState<CallLog | null>(null)
  const [incomingCall, setIncomingCall] = useState<CallLog | null>(null)
  const [callDuration, setCallDuration] = useState(0)
  const [isInitiatingCall, setIsInitiatingCall] = useState(false)
  const [isJoiningCallAudio, setIsJoiningCallAudio] = useState(false)
  const callTimerRef = useRef<NodeJS.Timeout | null>(null)
  const livekitRoomRef = useRef<Room | null>(null)

  const messagesEndRef = useRef<HTMLDivElement>(null)
  const messagesContainerRef = useRef<HTMLDivElement>(null)
  const isInitialLoadRef = useRef(true)
  // Tracks message _ids confirmed via HTTP response so the subsequent socket
  // broadcast for the same message is ignored (prevents duplicates).
  const confirmedMessageIds = useRef<Set<string>>(new Set())
  // Stores original send data for failed messages so they can be retried
  const failedMessageData = useRef<Map<string, { type: string; mediaUrl?: string; text?: string; caption?: string }>>(new Map())
  const [retryingMsgId, setRetryingMsgId] = useState<string | null>(null)
  const [pastedImage, setPastedImage] = useState<File | null>(null)
  const [pastedImageUrl, setPastedImageUrl] = useState<string | null>(null)
  const composerInputRef = useRef<HTMLTextAreaElement>(null)
  const { socket } = useSocket()

  const capitalizeFirstCharacter = (value: string) => {
    if (!value) return value
    const first = value.charAt(0)
    const upper = first.toLocaleUpperCase()
    if (first === upper) return value
    return `${upper}${value.slice(1)}`
  }

  const isMobileComposerViewport = () => {
    if (typeof window === 'undefined') return false
    return window.matchMedia('(max-width: 768px)').matches
  }

  const buildReadinessMessage = (details: string[]) => {
    const lines = ['Calling is not ready for this number:']
    details.forEach((d, i) => lines.push(`${i + 1}. ${d}`))
    lines.push('Fix these in Meta, then try again.')
    return lines.join('\n')
  }

  const isMetaPrerequisiteError = (errorMessage: string) => {
    const msg = (errorMessage || '').toLowerCase()
    return msg.includes('2593151') || msg.includes('configure webhooks or set up session initiation protocol')
  }

  const preflightCallingCheck = async () => {
    try {
      const data = await callsApi.getReadiness(chatId)
      const blockers = data.readiness?.blockers || []
      if (blockers.length > 0 || !data.readiness?.ready) {
        const details = [...blockers]
        if (data.readiness?.metaErrorHint) details.push(data.readiness.metaErrorHint)
        details.push(`Docs: ${data.readiness?.docs || 'https://developers.facebook.com/docs/whatsapp/cloud-api/calling#step-1-prerequisites'}`)
        hotToast.error(buildReadinessMessage(details), { duration: 8000 })
        return false
      }
      return true
    } catch (err: any) {
      const msg = err?.response?.data?.error || err?.message || 'Failed to verify calling prerequisites'
      hotToast.error(msg)
      return false
    }
  }

  const stopCallClock = () => {
    if (callTimerRef.current) {
      clearInterval(callTimerRef.current)
      callTimerRef.current = null
    }
    setCallDuration(0)
  }

  const startCallClock = () => {
    stopCallClock()
    callTimerRef.current = setInterval(() => setCallDuration(prev => prev + 1), 1000)
  }

  const disconnectCallAudio = async () => {
    const room = livekitRoomRef.current
    if (!room) return
    try {
      room.removeAllListeners()
      await room.disconnect()
    } catch (e) {
      console.error('LiveKit disconnect failed:', e)
    } finally {
      livekitRoomRef.current = null
    }
  }

  const joinCallAudio = async (callLogId: string) => {
    if (!callLogId || livekitRoomRef.current) return
    setIsJoiningCallAudio(true)
    try {
      const { session } = await callsApi.getMediaSession(callLogId)
      const room = new Room({
        adaptiveStream: true,
        dynacast: true,
      })

      room.on(RoomEvent.Disconnected, () => {
        livekitRoomRef.current = null
      })

      await room.connect(session.livekitUrl, session.token)
      await room.localParticipant.setMicrophoneEnabled(true)
      livekitRoomRef.current = room
    } catch (err: any) {
      const msg = err?.response?.data?.error || err?.message || 'Failed to join call audio room'
      hotToast.error(msg)
      throw err
    } finally {
      setIsJoiningCallAudio(false)
    }
  }

  const EMOJIS = [
    { char: '👍', url: 'https://cdnjs.cloudflare.com/ajax/libs/twemoji/14.0.2/svg/1f44d.svg' },
    { char: '❤️', url: 'https://cdnjs.cloudflare.com/ajax/libs/twemoji/14.0.2/svg/2764.svg' },
    { char: '😂', url: 'https://cdnjs.cloudflare.com/ajax/libs/twemoji/14.0.2/svg/1f602.svg' },
    { char: '😮', url: 'https://cdnjs.cloudflare.com/ajax/libs/twemoji/14.0.2/svg/1f62e.svg' },
    { char: '😢', url: 'https://cdnjs.cloudflare.com/ajax/libs/twemoji/14.0.2/svg/1f622.svg' },
    { char: '🙏', url: 'https://cdnjs.cloudflare.com/ajax/libs/twemoji/14.0.2/svg/1f64f.svg' }
  ]

  useEffect(() => {
    discardVoiceMessage()
    isInitialLoadRef.current = true
    loadChatData()
    // Open sidebar by default only on desktop
    if (window.innerWidth >= 1024) {
      setShowInfo(true)
    }
  }, [chatId])

  useEffect(() => {
    return () => {
      stopCallClock()
      disconnectCallAudio().catch(() => {})
    }
  }, [])

  useEffect(() => {
    const handleClick = () => {
      setContextMenuMsg(null)
      setShowCallMenu(false)
    }
    window.addEventListener('click', handleClick)
    return () => window.removeEventListener('click', handleClick)
  }, [])

  useEffect(() => {
    if (pastedImage) {
      const url = URL.createObjectURL(pastedImage)
      setPastedImageUrl(url)
      return () => {
        URL.revokeObjectURL(url)
        setPastedImageUrl(null)
      }
    }
  }, [pastedImage])

  useEffect(() => {
    return () => {
      if (recordedAudio) {
        URL.revokeObjectURL(recordedAudio.url)
      }
    }
  }, [recordedAudio])

  useEffect(() => {
    if (messages.length === 0) return

    if (isInitialLoadRef.current) {
      // On initial load, use instant scroll and add delayed retries
      // to handle images that shift the layout after loading
      isInitialLoadRef.current = false
      if (!targetMessageId) {
        messagesEndRef.current?.scrollIntoView({ behavior: 'instant' })
        // Retry after short delays to catch image loads that shift layout
        setTimeout(() => messagesEndRef.current?.scrollIntoView({ behavior: 'instant' }), 100)
        setTimeout(() => messagesEndRef.current?.scrollIntoView({ behavior: 'instant' }), 500)
      }
    } else {
      if (!targetMessageId) {
        scrollToBottom()
      }
    }
  }, [messages, targetMessageId])

  // Scroll to and highlight targeted message from search results
  useEffect(() => {
    if (!targetMessageId || messages.length === 0) return

    const msgExists = messages.some(m => m._id === targetMessageId)
    if (msgExists) {
      const timer = setTimeout(() => {
        const element = document.getElementById(`msg-${targetMessageId}`)
        if (element) {
          element.scrollIntoView({ behavior: 'smooth', block: 'center' })
          setHighlightedMessageId(targetMessageId)

          // Clear highlight after 2.5 seconds
          const flashTimer = setTimeout(() => {
            setHighlightedMessageId(null)
          }, 2500)
          return () => clearTimeout(flashTimer)
        }
      }, 300)
      return () => clearTimeout(timer)
    }
  }, [targetMessageId, messages])

  // Live session countdown timer
  // Using useRef to avoid re-renders that lose text selection
  const sessionTimeLeftRef = useRef<number | null>(null)

  useEffect(() => {
    if (!chat?.sessionExpiresAt) {
      sessionTimeLeftRef.current = null
      setSessionTimeLeft(null)
      return
    }

    const tick = () => {
      const diff = Math.floor((new Date(chat.sessionExpiresAt!).getTime() - Date.now()) / 1000)
      const timeLeft = diff > 0 ? diff : 0
      sessionTimeLeftRef.current = timeLeft
      // Only update state when transitioning to/from 0 to avoid constant re-renders
      setSessionTimeLeft(prev => {
        if ((prev === null || prev > 0) && timeLeft === 0) return 0
        if ((prev === 0 || prev === null) && timeLeft > 0) return timeLeft
        return prev
      })
    }
    tick()
    const interval = setInterval(tick, 1000)
    return () => clearInterval(interval)
  }, [chat?.sessionExpiresAt])

  useEffect(() => {
    if (!socket || !chatId) return

    const handleNewMessage = (data: { chatId: string, message: Message }) => {
      if (data.chatId?.toString() === chatId) {
        setMessages(prev => {
          // 1. Skip if this _id was already confirmed via our own HTTP response
          //    (prevents the duplicate that occurs when the socket event races the HTTP await)
          if (confirmedMessageIds.current.has(data.message._id)) {
            confirmedMessageIds.current.delete(data.message._id)
            return prev
          }

          // 2. Exact ID match check (covers normal dedup)
          if (prev.some(m => m._id === data.message._id)) return prev

          // 3. Race condition check: socket arrived before HTTP response replaced temp.
          //    Match on temp- prefix + type + content.
          if (data.message.direction !== 'inbound') {
            const tempIndex = prev.findIndex(m =>
              m._id.toString().startsWith('temp-') &&
              m.type === data.message.type &&
              (m.text === data.message.text || m.caption === data.message.caption)
            )

            if (tempIndex !== -1) {
              // Replace the temp message with the real one from the socket
              const newMessages = [...prev]
              newMessages[tempIndex] = data.message
              return newMessages
            }
          }

          // Otherwise, just add the new message
          return [...prev, data.message]
        })

        // If it's an inbound message, also mark chat as read
        if (data.message.direction === 'inbound') {
          chatsApi.markRead(chatId).catch(console.error)
        }
      }
    }

    const handleMessageStatus = (data: { chatId: string, messageId: string, waMessageId: string, status: string, errorCode?: number, errorMessage?: string }) => {
      if (data.chatId?.toString() === chatId) {
        setMessages(prev => prev.map(m =>
          m._id === data.messageId || m.messageId === data.waMessageId
            ? {
              ...m,
              status: data.status as any,
              ...(data.status === 'failed' && { errorCode: data.errorCode, errorMessage: data.errorMessage }),
            }
            : m
        ))
      }
    }

    const handleMessageReaction = (data: { chatId: string, messageId: string, reactions: any[] }) => {
      if (data.chatId === chatId) {
        setMessages(prev => prev.map(m =>
          m._id === data.messageId
            ? { ...m, reactions: data.reactions }
            : m
        ))
      }
    }

    const handleMessageDelete = (data: { chatId: string, messageId: string }) => {
      if (data.chatId === chatId) {
        setMessages(prev => prev.filter(m => m._id !== data.messageId))
        setContextMenuMsg(null)
      }
    }

    // Handle real-time assignment updates
    const handleChatAssigned = (data: { chatId: string; chat: any; systemMessage?: any }) => {
      if (data.chatId === chatId) {
        setChat(data.chat)
        // Append the real persisted system message (avoids duplicating on refresh)
        if (data.systemMessage) {
          setMessages(prev => [...prev, data.systemMessage])
        }

        // If a staff user is viewing this chat and it was reassigned to someone else,
        // redirect them away since they no longer own it
        const newAssignedId = data.chat?.assignedTo?._id || data.chat?.assignedTo
        if (isStaff && currentUser?._id && newAssignedId && newAssignedId.toString() !== currentUser._id.toString()) {
          router.push('/chats')
        }
      }
    }

    // Handle real-time chat status/metadata updates (e.g. closed → open when customer messages)
    // Preserve populated fields (tags, contactId) from local state since the backend
    // does not populate them before emitting chat:update.
    const handleChatUpdate = (data: { chatId: string; chat: any }) => {
      if (data.chatId.toString() === chatId) {
        setChat(prev => {
          if (!prev) return data.chat
          // Merge a populated contact when the backend sends one (so live changes like
          // opt-out/block/name refresh); otherwise keep the local populated contact.
          const incomingContact = data.chat?.contactId
          const incomingIsPopulated = incomingContact && typeof incomingContact === 'object'
            && ('isOptedOut' in incomingContact || 'isBlocked' in incomingContact || 'name' in incomingContact)
          return {
            ...prev,
            ...data.chat,
            // Keep the populated versions from local state
            tags: prev.tags,
            contactId: incomingIsPopulated ? { ...prev.contactId, ...incomingContact } : prev.contactId,
          }
        })
      }
    }

    // Personal notification for the assigned staff member
    const handleAssignedToMe = (data: { chatId: string; chat: any; assignedByName: string }) => {
      setToast({
        message: `Chat assigned to you by ${data.assignedByName}`,
        chatId: data.chatId,
      })
      // Auto-dismiss after 6 seconds
      setTimeout(() => setToast(null), 6000)
    }

    // Call event handlers
    const handleCallIncoming = (data: { chatId: string; callLog: CallLog }) => {
      if (data.chatId === chatId) {
        setIncomingCall(data.callLog)
      }
    }
    const handleCallStatus = (data: { chatId: string; callLog: CallLog }) => {
      if (data.chatId === chatId) {
        if (activeCall && data.callLog._id === activeCall._id && data.callLog.status !== 'accepted') {
          setActiveCall(data.callLog)
        }
        if (data.callLog.status === 'accepted') {
          setActiveCall(data.callLog)
          setIncomingCall(null)
          setCallDuration(0)
          if (callTimerRef.current) clearInterval(callTimerRef.current)
          callTimerRef.current = setInterval(() => setCallDuration(prev => prev + 1), 1000)
        } else if (data.callLog.status === 'ringing') {
          setIncomingCall(data.callLog)
        }
      }
    }
    const handleCallTerminated = (data: { chatId: string; callLog: CallLog }) => {
      if (data.chatId === chatId) {
        setActiveCall(null)
        setIncomingCall(null)
        setCallDuration(0)
        if (callTimerRef.current) clearInterval(callTimerRef.current)
      }
    }
    const handleCallOutgoing = (data: { chatId: string; callLog: CallLog }) => {
      if (data.chatId === chatId) {
        setActiveCall(data.callLog)
      }
    }
    const handleCallPermissionRequested = (data: { chatId: string }) => {
      if (data.chatId === chatId) {
        setToast({ message: 'Call permission request sent', chatId })
        setTimeout(() => setToast(null), 3000)
      }
    }

    socket.on('message:new', handleNewMessage)
    socket.on('message:status', handleMessageStatus)
    socket.on('message:reaction', handleMessageReaction)
    socket.on('chat:assigned', handleChatAssigned)
    socket.on('chat:update', handleChatUpdate)
    socket.on('chat:assigned:me', handleAssignedToMe)
    socket.on('message:delete', handleMessageDelete)
    socket.on('call:incoming', handleCallIncoming)
    socket.on('call:status', handleCallStatus)
    socket.on('call:terminated', handleCallTerminated)
    socket.on('call:outgoing', handleCallOutgoing)
    socket.on('call:permission_requested', handleCallPermissionRequested)

    return () => {
      socket.off('message:new', handleNewMessage)
      socket.off('message:status', handleMessageStatus)
      socket.off('message:reaction', handleMessageReaction)
      socket.off('chat:assigned', handleChatAssigned)
      socket.off('chat:update', handleChatUpdate)
      socket.off('chat:assigned:me', handleAssignedToMe)
      socket.off('message:delete', handleMessageDelete)
      socket.off('call:incoming', handleCallIncoming)
      socket.off('call:status', handleCallStatus)
      socket.off('call:terminated', handleCallTerminated)
      socket.off('call:outgoing', handleCallOutgoing)
      socket.off('call:permission_requested', handleCallPermissionRequested)
      if (callTimerRef.current) clearInterval(callTimerRef.current)
    }
  }, [socket, chatId, isStaff, currentUser?._id, router, activeCall])

  const loadChatData = async () => {
