      setMessages(prev => prev.map(m => {
        if (m._id.toString().startsWith('temp-')) {
          failedMessageData.current.set(m._id, { type: m.type, mediaUrl: m.mediaUrl, caption: m.caption })
          return { ...m, status: 'failed' as any }
