    }
  }

  const handleAddTag = async (tagId: string) => {
    try {
      const updatedChat = await tagsApi.addToChat(chatId, tagId)
      setChat(updatedChat.chat)
    } catch (e: any) {
      console.error(e)
      alert(e.response?.data?.message || 'Failed to add tag')
    }
  }

  const handleRemoveTag = async (tagId: string) => {
    try {
      const updatedChat = await tagsApi.removeFromChat(chatId, tagId)
      setChat(updatedChat.chat)
    } catch (e: any) {
      console.error(e)
      alert(e.response?.data?.message || 'Failed to remove tag')
    }
  }

  const handleAssignChat = async (staffId: string) => {
    // Selection changed, find staff name and show confirmation
    if (staffId === '') {
      // Confirm unassignment
      setConfirmAssign({ id: '', name: 'Unassigned' })
      return
    }

    const staff = activeStaff.find(s => s._id === staffId)
    if (staff) {
      setConfirmAssign({ id: staff._id, name: staff.name })
    }
  }

  const executeAssignment = async () => {
    if (!confirmAssign) return
    const staffId = confirmAssign.id
    setConfirmAssign(null)

    setIsAssigning(true)
    try {
      const updatedChat = await chatsApi.assign(chatId, staffId)
      setChat(updatedChat)

      // If a staff user just assigned/transferred the chat to someone else,
      // redirect them back to the chat list since they no longer own it
      if (isStaff && staffId && staffId !== currentUser?._id) {
        router.push('/chats')
      }
    } catch (error: any) {
      console.error('Failed to assign chat:', error)
      alert(error.response?.data?.message || 'Failed to assign chat')
    } finally {
      setIsAssigning(false)
    }
  }

  const handleToggleDnd = async () => {
    if (!chat || isTogglingDnd) return
    setIsTogglingDnd(true)
    try {
      const newDndStatus = !chat.isDnd
      const updatedChat = await chatsApi.toggleDnd(chatId, newDndStatus)
      setChat(prev => prev ? { ...prev, isDnd: updatedChat.isDnd } : null)
    } catch (error) {
      console.error('Failed to toggle DND:', error)
    } finally {
      setIsTogglingDnd(false)
    }
  }

  const handleToggleBlock = async () => {
    if (!chat || !chat.contactId || isBlockingContact) return

    const contactId = typeof chat.contactId === 'object' ? chat.contactId._id : chat.contactId
    const currentBlocked = chat.contactId?.isBlocked || false
    const action = currentBlocked ? 'unblock' : 'block'

    if (!confirm(`Are you sure you want to ${action} this contact?`)) return

    setIsBlockingContact(true)
    try {
      const updatedContact = await contactsApi.block(contactId, !currentBlocked)
      setChat(prev => {
        if (!prev) return null
        return {
          ...prev,
          contactId: {
            ...prev.contactId,
            isBlocked: updatedContact.isBlocked
          }
        }
      })
    } catch (error) {
      console.error('Failed to toggle block:', error)
    } finally {
      setIsBlockingContact(false)
    }
  }

  const handleToggleOptOut = async () => {
    if (!chat || !chat.contactId || isTogglingOptOut) return

    const contactId = typeof chat.contactId === 'object' ? chat.contactId._id : chat.contactId
    const currentOptedOut = chat.contactId?.isOptedOut || false

    setIsTogglingOptOut(true)
    try {
      if (currentOptedOut) {
        await contactsApi.optIn(contactId)
      } else {
        await contactsApi.optOut(contactId)
      }

      setChat(prev => {
        if (!prev) return null
        return {
          ...prev,
          contactId: {
            ...prev.contactId,
            isOptedOut: !currentOptedOut
          }
        }
      })
    } catch (error) {
      console.error('Failed to toggle opt-out:', error)
    } finally {
      setIsTogglingOptOut(false)
    }
  }

  const handleCreateAndAddTag = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!newTagName.trim()) return
    setIsCreatingTag(true)
    try {
      const createdTag = await tagsApi.create({
        name: newTagName.trim(),
        color: newTagColor
      })
      // Add to available tags
      setAvailableTags(prev => [...prev, createdTag])
      // Add to chat immediately
      await handleAddTag(createdTag._id)
      setNewTagName('')
      setNewTagColor('#00a884')
    } catch (error: any) {
      console.error('Failed to create tag', error)
      alert(error.response?.data?.message || 'Failed to create tag')
    } finally {
      setIsCreatingTag(false)
    }
  }

  const handleCloseChat = async () => {
    setIsClosing(true)
    try {
      const updatedChat = await chatsApi.close(chatId)
      setChat(updatedChat)
      setShowCloseModal(false)
      setToast({ message: 'Chat closed successfully', chatId })
      setTimeout(() => setToast(null), 3000)
    } catch (error: any) {
      console.error('Failed to close chat:', error)
      alert(error.response?.data?.message || 'Failed to close chat')
    } finally {
      setIsClosing(false)
    }
  }

  const handleReopenChat = async () => {
    setIsReopening(true)
    try {
      const updatedChat = await chatsApi.reopen(chatId)
      setChat(updatedChat)
      setToast({ message: 'Chat reopened successfully', chatId })
      setTimeout(() => setToast(null), 3000)
    } catch (error: any) {
      console.error('Failed to reopen chat:', error)
      alert(error.response?.data?.message || 'Failed to reopen chat')
    } finally {
      setIsReopening(false)
    }
  }

  const handleMarkUnread = async () => {
    try {
      await chatsApi.markUnread(chatId)
      setToast({ message: 'Chat marked as unread', chatId })
      setChat(prev => prev ? { ...prev, isUnread: true, isManuallyUnread: true } : null)
      router.push('/chats')
    } catch (error: any) {
      console.error('Failed to mark unread:', error)
      alert(error.response?.data?.message || 'Failed to mark unread')
    }
  }

  const loadAutoMessages = async () => {
    setAutoMessagesLoading(true)
    try {
      const result = await chatsApi.getAutoMessages(chatId, { limit: 100 })
      setAutoMessages(result.messages)
      setAutoMessagesTotal(result.total)
    } catch (error) {
      console.error('Failed to load auto messages:', error)
    } finally {
      setAutoMessagesLoading(false)
    }
  }

  const handleOpenAutoMessages = () => {
    setShowAutoMessages(true)
    loadAutoMessages()
  }

  const renderStatus = (status?: string) => {
    switch (status) {
      case 'queued':
        return (
          <span className="ml-1 inline-flex items-center" title="Queued">
            <svg viewBox="0 0 24 24" width="14" height="14" fill="currentColor" className="text-gray-400">
              <path d="M11.99 2C6.47 2 2 6.48 2 12s4.47 10 9.99 10C17.52 22 22 17.52 22 12S17.52 2 11.99 2zM12 20c-4.42 0-8-3.58-8-8s3.58-8 8-8 8 3.58 8 8-3.58 8-8 8zm.5-13H11v6l5.25 3.15.75-1.23-4.5-2.67z" />
            </svg>
          </span>
        );
      case 'sent':
        return (
          <svg viewBox="0 0 16 11" width="16" height="11" fill="currentColor" className="text-gray-400 ml-1 inline-block">
            <path d="M11.8 1.6 10.3.1 5.4 5 3.5 3.1 2 4.6l3.4 3.4z" />
          </svg>
        );
      case 'delivered':
        return (
          <svg viewBox="0 0 16 15" width="16" height="15" fill="currentColor" className="text-gray-400 ml-1 inline-block">
            <path d="M15.01 3.316l-.478-.372a.365.365 0 0 0-.51.063L8.666 9.879a.32.32 0 0 1-.484.033l-.358-.325a.32.32 0 0 0-.484.032l-.378.483a.418.418 0 0 0 .036.541l1.32 1.266c.143.14.361.125.484-.033l6.272-8.048a.366.366 0 0 0-.064-.512zm-4.1 0l-.478-.372a.365.365 0 0 0-.51.063L4.566 9.879a.32.32 0 0 1-.484.033L1.891 7.769a.366.366 0 0 0-.515.006l-.423.433a.364.364 0 0 0 .006.514l3.258 3.185c.143.14.361.125.484-.033l6.272-8.048a.365.365 0 0 0-.063-.51z" />
          </svg>
        );
      case 'read':
        return (
          <svg viewBox="0 0 16 15" width="16" height="15" fill="currentColor" className="text-[#53bdeb] ml-1 inline-block">
            <path d="M15.01 3.316l-.478-.372a.365.365 0 0 0-.51.063L8.666 9.879a.32.32 0 0 1-.484.033l-.358-.325a.32.32 0 0 0-.484.032l-.378.483a.418.418 0 0 0 .036.541l1.32 1.266c.143.14.361.125.484-.033l6.272-8.048a.366.366 0 0 0-.064-.512zm-4.1 0l-.478-.372a.365.365 0 0 0-.51.063L4.566 9.879a.32.32 0 0 1-.484.033L1.891 7.769a.366.366 0 0 0-.515.006l-.423.433a.364.364 0 0 0 .006.514l3.258 3.185c.143.14.361.125.484-.033l6.272-8.048a.365.365 0 0 0-.063-.51z" />
          </svg>
        );
      case 'failed':
        return (
          <span className="text-red-500 ml-1 inline-flex items-center gap-0.5" title="Failed to send">
            <svg viewBox="0 0 24 24" width="14" height="14" fill="currentColor">
              <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm1 15h-2v-2h2v2zm0-4h-2V7h2v6z" />
            </svg>
          </span>
        );
      default:
        // Before getting the 'sent' websocket update, show a single light tick (clock alternative could be used too)
        return (
          <svg viewBox="0 0 16 11" width="16" height="11" fill="currentColor" className="text-gray-400 ml-1 inline-block">
            <path d="M11.8 1.6 10.3.1 5.4 5 3.5 3.1 2 4.6l3.4 3.4z" />
          </svg>
        );
    }
  }

  const handleUpdateNickname = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!chat?.contactId?._id) return

    setIsUpdatingNickname(true)
    try {
      const updatedContact = await contactsApi.update(chat.contactId._id, { nickname: nicknameInput.trim() })
      setChat(prev => prev ? {
        ...prev,
        contactId: {
          ...prev.contactId,
          nickname: updatedContact.nickname
        }
      } as Chat : null)
      setShowNicknameModal(false)
      setToast({ message: 'Nickname updated successfully', chatId: chat._id })
      setTimeout(() => setToast(null), 3000)
    } catch (error: any) {
      console.error('Failed to update nickname:', error)
      alert(error.response?.data?.message || 'Failed to update nickname')
    } finally {
      setIsUpdatingNickname(false)
    }
  }

  if (loading) return <div className="p-6">Loading chat...</div>
  if (!chat) return <div className="p-6">Chat not found</div>

  const lastActivityDate = chat?.lastMessageAt || chat?.createdAt
  const hoursSinceLastActivity = lastActivityDate
    ? (new Date().getTime() - new Date(lastActivityDate).getTime()) / (1000 * 60 * 60)
    : 0
  const canClose = chat?.status !== 'closed' && hoursSinceLastActivity <= 24

  const closedTime = chat?.closedAt || (chat?.status === 'closed' ? chat?.updatedAt : null)
  const hoursSinceClose = closedTime
    ? (new Date().getTime() - new Date(closedTime).getTime()) / (1000 * 60 * 60)
    : 0

  // A chat can be reopened only if the WhatsApp 24-hour session window is still open.
  // Once sessionTimeLeft is 0, the customer must send a new message first.
  const canReopen = chat?.status === 'closed' && sessionTimeLeft !== null && sessionTimeLeft > 0

  const formatSessionTime = (seconds: number) => {
    const h = Math.floor(seconds / 3600)
    const m = Math.floor((seconds % 3600) / 60)
    const s = seconds % 60
    if (h > 0) return `${h}h ${m}m ${s}s`
    if (m > 0) return `${m}m ${s}s`
    return `${s}s`
  }

  const headerTags = ((chat.tags as any[]) || []).reduce<Array<{ _id: string; name: string; color: string }>>((acc, tag) => {
    if (typeof tag === 'string') {
      const matchedTag = availableTags.find((availableTag) => availableTag._id === tag)
      if (matchedTag) {
        acc.push({
          _id: matchedTag._id,
          name: matchedTag.name,
          color: matchedTag.color || '#d1d5db',
        })
      }
      return acc
    }

    if (tag && typeof tag === 'object' && tag.name) {
      acc.push({
        _id: tag._id || tag.id || tag.name,
        name: tag.name,
        color: tag.color || '#d1d5db',
      })
    }

    return acc
  }, [])

  return (
    <div className="flex flex-col h-full overflow-hidden">
      <div className="flex h-[calc(100dvh-64px)] w-full overflow-hidden bg-[#efeae2] relative min-w-0">
        <div className="flex-1 flex flex-col min-w-0 bg-[#e5ddd5] dark:bg-gray-900 relative">
          {/* Header */}
          <div className="bg-white/90 backdrop-blur-md px-4 md:px-5 py-2 md:py-3 border-b border-gray-100 flex items-center justify-between sticky top-0 z-20 shadow-sm">
            <div className="flex items-center gap-3 md:gap-4 flex-1 min-w-0">
              <Link href="/chats" className="md:hidden block p-2 -ml-2 text-gray-500 hover:bg-gray-100 rounded-full transition-colors">
                <svg viewBox="0 0 24 24" width="24" height="24" fill="currentColor">
                  <path d="M20 11H7.83l5.59-5.59L12 4l-8 8 8 8 1.41-1.41L7.83 13H20v-2z" />
                </svg>
              </Link>
              <div
                className="-ml-1 w-9 h-9 md:w-12 md:h-12 bg-[#dfe5e7] rounded-full flex items-center justify-center text-gray-400 text-lg md:text-xl font-bold flex-shrink-0 border-2 border-white shadow-sm cursor-pointer"
                onClick={() => setShowInfo(true)}
              >
                {chat.contactId?.nickname?.[0]?.toUpperCase() || chat.contactId?.name?.[0]?.toUpperCase() || chat.contactId?.nameOnWhatsApp?.[0]?.toUpperCase() || <svg viewBox="0 0 24 24" width="24" height="24" fill="currentColor"><path d="M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z" /></svg>}
              </div>
              <div className="flex-1 min-w-0">
                <button
                  type="button"
                  onClick={() => {
                    setNicknameInput(chat.contactId?.nickname || '')
                    setShowNicknameModal(true)
                  }}
                  className="block w-full min-w-0 text-left"
                  title="Rename customer"
                >
                  <h2 className="font-semibold text-gray-900 truncate text-base md:text-lg">{chat.contactId?.nickname || chat.contactId?.name || chat.contactId?.nameOnWhatsApp || formatInternationalPhone(chat.waId || chat.phoneNumber)}</h2>
                </button>
                <div className="mt-1 h-px bg-gray-200"></div>
                <div className="mt-2 flex gap-2 overflow-x-auto whitespace-nowrap pb-1 pr-2 [-ms-overflow-style:none] [scrollbar-width:none] [&::-webkit-scrollbar]:hidden">
                  {headerTags.length > 0 ? (
                    headerTags.map((tag) => (
                      <span
                        key={tag._id}
                        className="inline-flex items-center gap-1 rounded-full border border-gray-200 bg-white px-2.5 py-1 text-[11px] font-medium text-gray-700 shadow-sm"
                      >
                        <span className="h-2 w-2 rounded-full" style={{ backgroundColor: tag.color || '#d1d5db' }}></span>
                        <span>{tag.name}</span>
                      </span>
                    ))
                  ) : (
                    <span className="text-xs text-gray-400">No tags</span>
                  )}
                </div>
              </div>
            </div>

            <div className="flex items-center gap-2 md:gap-3">
              {!chat.isManuallyUnread && (
                <button
                  onClick={handleMarkUnread}
                  className="hidden md:flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold transition-all shadow-sm bg-white text-gray-600 border border-gray-200 hover:bg-gray-50 hover:text-blue-600"
                  title="Mark as unread and return to list"
                >
                  <svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor">
                    <path d="M22 6c0-1.1-.9-2-2-2H4c-1.1 0-2 .9-2 2v12c0 1.1.9 2 2 2h16c1.1 0 2-.9 2-2V6zm-2 0l-8 5-8-5h16zm0 12H4V8l8 5 8-5v10z"/>
                  </svg>
                  Mark Unread
                </button>
              )}
              <div className="flex items-center gap-2.5 rounded-full border border-white/80 bg-gradient-to-b from-white via-white to-[#f7f8fb] px-3 py-1 shadow-[0_12px_24px_rgba(15,23,42,0.1),0_2px_8px_rgba(255,255,255,0.8)_inset] backdrop-blur-md">
                {/* Call button */}
                <div className="relative">
                  <button
                    onClick={(e) => { e.stopPropagation(); setShowCallMenu(!showCallMenu) }}
                    className={`flex h-8 w-8 items-center justify-center rounded-full transition-all ${activeCall ? 'bg-gradient-to-br from-emerald-100 to-green-200 text-emerald-600 shadow-[0_6px_14px_rgba(34,197,94,0.24)] animate-pulse' : 'text-[#6b7280] hover:bg-gradient-to-br hover:from-pink-50 hover:to-orange-50 hover:text-[#ec4899]'}`}
                    title={activeCall ? 'Call in progress' : 'Voice call'}
                  >
                    <svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor">
                      <path d="M20.01 15.38c-1.23 0-2.42-.2-3.53-.56a.977.977 0 00-1.01.24l-1.57 1.97c-2.83-1.35-5.48-3.9-6.89-6.83l1.95-1.66c.27-.28.35-.67.24-1.02-.37-1.11-.56-2.3-.56-3.53 0-.54-.45-.99-.99-.99H4.19C3.65 3 3 3.24 3 3.99 3 13.28 10.73 21 20.01 21c.71 0 .99-.63.99-1.18v-3.45c0-.54-.45-.99-.99-.99z" />
                    </svg>
                    {activeCall && (
                      <span className="absolute -top-0.5 -right-0.5 w-3 h-3 bg-green-500 rounded-full border-2 border-white"></span>
                    )}
                  </button>

                  {/* Call dropdown menu */}
                  {showCallMenu && !activeCall && (
                    <div className="absolute right-0 top-full mt-1 w-56 bg-white rounded-xl shadow-xl border border-gray-100 py-2 z-50">
                      <button
                        onClick={async () => {
                          setShowCallMenu(false)
                          const ready = await preflightCallingCheck()
                          if (!ready) return
                          setIsInitiatingCall(true)
                          try {
                            const res = await callsApi.initiateCall(chatId)
                            setActiveCall(res.callLog)
                          } catch (err: any) {
                            const message = err.response?.data?.error || 'Failed to initiate call'
                            if (isMetaPrerequisiteError(message)) {
                              hotToast.error(
                                buildReadinessMessage([
                                  'Meta rejected calling enablement for this number (error 2593151).',
                                  'Subscribe your app to the calls webhook field for this WABA.',
                                  'Ensure this app is subscribed to the WABA and has whatsapp_business_messaging permission.',
                                  'If using SIP mode, configure SIP instead of webhook flow.',
                                  'Docs: https://developers.facebook.com/docs/whatsapp/cloud-api/calling#step-1-prerequisites',
                                ]),
                                { duration: 9000 }
                              )
                            } else {
                              hotToast.error(message)
                            }
                          } finally {
                            setIsInitiatingCall(false)
                          }
                        }}
                        disabled={isInitiatingCall}
                        className="w-full flex items-center gap-3 px-4 py-2.5 text-sm text-gray-700 hover:bg-gray-50 transition-colors"
                      >
                        <div className="w-8 h-8 rounded-full bg-green-50 flex items-center justify-center">
                          <svg viewBox="0 0 24 24" width="16" height="16" fill="#16a34a">
                            <path d="M20.01 15.38c-1.23 0-2.42-.2-3.53-.56a.977.977 0 00-1.01.24l-1.57 1.97c-2.83-1.35-5.48-3.9-6.89-6.83l1.95-1.66c.27-.28.35-.67.24-1.02-.37-1.11-.56-2.3-.56-3.53 0-.54-.45-.99-.99-.99H4.19C3.65 3 3 3.24 3 3.99 3 13.28 10.73 21 20.01 21c.71 0 .99-.63.99-1.18v-3.45c0-.54-.45-.99-.99-.99z" />
                          </svg>
                        </div>
                        <div>
                          <p className="font-medium">Call Now</p>
                          <p className="text-xs text-gray-400">{formatInternationalPhone(chat?.waId || chat?.phoneNumber)}</p>
                        </div>
                      </button>
                      <button
                        onClick={async () => {
                          setShowCallMenu(false)
                          const ready = await preflightCallingCheck()
                          if (!ready) return
                          try {
                            await callsApi.requestPermission(chatId)
                            setToast({ message: 'Call permission request sent', chatId })
                            setTimeout(() => setToast(null), 3000)
                          } catch (err: any) {
                            const message = err.response?.data?.error || 'Failed to send permission request'
                            if (isMetaPrerequisiteError(message)) {
                              hotToast.error(
                                buildReadinessMessage([
                                  'Meta rejected calling enablement for this number (error 2593151).',
                                  'Enable calls only after webhook prerequisites are configured.',
                                  'Docs: https://developers.facebook.com/docs/whatsapp/cloud-api/calling#step-1-prerequisites',
                                ]),
                                { duration: 9000 }
                              )
                            } else {
                              hotToast.error(message)
                            }
                          }
                        }}
                        className="w-full flex items-center gap-3 px-4 py-2.5 text-sm text-gray-700 hover:bg-gray-50 transition-colors"
                      >
                        <div className="w-8 h-8 rounded-full bg-blue-50 flex items-center justify-center">
                          <svg viewBox="0 0 24 24" width="16" height="16" fill="#2563eb">
                            <path d="M18 8h-1V6c0-2.76-2.24-5-5-5S7 3.24 7 6v2H6c-1.1 0-2 .9-2 2v10c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V10c0-1.1-.9-2-2-2zm-6 9c-1.1 0-2-.9-2-2s.9-2 2-2 2 .9 2 2-.9 2-2 2zm3.1-9H8.9V6c0-1.71 1.39-3.1 3.1-3.1 1.71 0 3.1 1.39 3.1 3.1v2z" />
                          </svg>
                        </div>
                        <div>
                          <p className="font-medium">Request Permission</p>
                          <p className="text-xs text-gray-400">Ask customer to allow calls</p>
                        </div>
                      </button>
                      <hr className="my-1 border-gray-100" />
                      <button
                        onClick={() => {
                          setShowCallMenu(false)
                          setShowCallLogs(true)
                        }}
                        className="w-full flex items-center gap-3 px-4 py-2.5 text-sm text-gray-700 hover:bg-gray-50 transition-colors"
                      >
                        <div className="w-8 h-8 rounded-full bg-gray-50 flex items-center justify-center">
                          <svg viewBox="0 0 24 24" width="16" height="16" fill="#6b7280">
                            <circle cx="12" cy="12" r="10" fill="none" stroke="#6b7280" strokeWidth="2" />
                            <path d="M12 6v6l4 2" fill="none" stroke="#6b7280" strokeWidth="2" />
                          </svg>
                        </div>
                        <div>
                          <p className="font-medium">Call History</p>
                          <p className="text-xs text-gray-400">View past calls</p>
                        </div>
                      </button>
                    </div>
                  )}

                  {/* Active call dropdown — end call */}
                  {showCallMenu && activeCall && (
                    <div className="absolute right-0 top-full mt-1 w-56 bg-white rounded-xl shadow-xl border border-gray-100 py-2 z-50">
                      <div className="px-4 py-2 text-xs text-gray-500 border-b border-gray-50">
                        <div className="flex items-center gap-2">
                          <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
