              let lastDate = '';
              let matchCounter = -1;
              return messages.map((message) => {
                const isOutbound = message.direction === 'outbound' || message.direction === 'internal';
                const messageId = message._id;

                // Compute if this message is a search match
                const isSearchMatch = msgSearchQuery.trim()
                  ? message.text?.toLowerCase().includes(msgSearchQuery.toLowerCase()) ||
                  message.caption?.toLowerCase().includes(msgSearchQuery.toLowerCase())
                  : false
                const isActiveMatch = showMsgSearch && dbSearchMatches[searchMatchIndex]?._id === message._id

                const messageDate = new Date(message.createdAt).toLocaleDateString([], { day: 'numeric', month: 'short', year: 'numeric' });
                const showDateSeparator = messageDate !== lastDate;
                if (showDateSeparator) lastDate = messageDate;

                // Aggregate reactions to show multiple emojis
                const uniqueReactions = message.reactions?.reduce((acc: any, r: any) => {
                  acc[r.emoji] = (acc[r.emoji] || 0) + 1;
                  return acc;
                }, {}) || {};

                return (
                  <div
                    key={messageId}
                    id={`msg-${messageId}`}
                    className={`w-full flex flex-col gap-2 relative transition-all duration-1000 ${
                      isActiveMatch
