                        : highlightedMessageId === messageId
                        ? 'rounded-xl outline outline-4 outline-yellow-400 outline-offset-2 bg-yellow-100/60 dark:bg-yellow-900/30'
                        : ''
                    }`}
                  >
                    {showDateSeparator && (
                      <div className="flex justify-center my-3 relative z-10">
                        <span className="bg-[#e1f3fb] text-gray-700 text-xs px-3 py-1.5 rounded-lg shadow-sm font-medium border border-[#c1e0f0]">
