                          {message.type === 'note' && (
                            <svg viewBox="0 0 24 24" width="14" height="14" fill="currentColor"><path d="M19 3H5c-1.11 0-2 .9-2 2v14c0 1.1.89 2 2 2h14c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2zm-2 10h-4v4h-2v-4H7v-2h4V7h2v4h4v2z" /></svg>
                          )}
                          <span>
                            {message.text}
                            {message.sentBy && message.type === 'note' && (
                              <span className="opacity-80 italic text-[11px] ml-1.5">
                                by {typeof message.sentBy === 'object' && 'name' in message.sentBy ? (message.sentBy as any).name : 'Admin'}
                              </span>
                            )}
                          </span>
                        </div>
                      </div>
                    ) : (
                      <div
                        data-message-id={message._id}
                        onContextMenu={(e) => {
                          e.preventDefault()
                          if (message.type === 'system' || message.type === 'note') return
                          const xOffset = e.clientX + 160 > window.innerWidth ? window.innerWidth - 170 : e.clientX
                          const yOffset = e.clientY + 200 > window.innerHeight ? window.innerHeight - 210 : e.clientY
                          setContextMenuMsg({
                            message,
                            x: xOffset,
                            y: yOffset,
                            isOutbound
                          })
