                        className={`flex items-start w-full gap-2 relative group pb-1 ${isOutbound ? 'justify-end' : 'justify-start'}`}
                      >
                        {/* Outbound Reaction Menu (Left) */}
                        {(isOutbound && chat.status !== 'closed') && (
