                            <div className="absolute top-0 -left-[8px] w-0 h-0 border-t-[12px] border-t-white border-l-[12px] border-l-transparent"></div>
                          )}
                          {isOutbound && (
                            <div className="absolute top-0 -right-[8px] w-0 h-0 border-t-[12px] border-t-[#dcf8c6] border-r-[12px] border-r-transparent"></div>
                          )}

                          <div
                            className={`px-3 pt-2 pb-1 shadow-sm rounded-lg relative ${isOutbound
                              ? 'bg-[#dcf8c6] text-gray-900 rounded-tr-none'
                              : 'bg-white text-gray-900 rounded-tl-none'
                              }`}
                          >
                            {/* Dropdown Arrow (visible on hover) */}
                            <button
                              onClick={(e) => {
