                                    if (message.replyToMessageId && typeof (message.replyToMessageId as any)._id === 'string') return (message.replyToMessageId as any)._id
                                    return message.quotedMessage?.messageId ?? null
                                  }
                                  navigateToMessage(resolveTarget())
                                }}
                                onKeyDown={(e) => {
                                  if (e.key === 'Enter' || e.key === ' ') {
                                    e.preventDefault();
                                    const resolveTarget = (): string | null => {
                                      if (typeof message.replyToMessageId === 'string') return message.replyToMessageId
                                      if (message.replyToMessageId && typeof (message.replyToMessageId as any)._id === 'string') return (message.replyToMessageId as any)._id
                                      return message.quotedMessage?.messageId ?? null
                                    }
                                    navigateToMessage(resolveTarget())
                                  }
                                }}
                                title="Click to view original message"
                                role="button"
                                tabIndex={0}
                              >
                                {/* Sender name */}
                                <p className="text-[10px] font-bold text-gray-600 mb-1.5 uppercase tracking-wide pointer-events-none">
