                                        <div className="absolute inset-0 flex items-center justify-center rounded bg-black bg-opacity-30">
                                          <svg viewBox="0 0 24 24" width="16" height="16" fill="white" className="ml-1"><path d="M8 5v14l11-7z"/></svg>
                                        </div>
                                      )}
                                    </div>
                                  )}

                                  {/* Text content */}
                                  <div className="flex-1 min-w-0 pointer-events-none">
                                    {message.quotedMessage.type === 'text' && message.quotedMessage.text && (
                                      <p className="text-[12px] text-gray-700 line-clamp-2" title={message.quotedMessage.text} dangerouslySetInnerHTML={{__html: linkifyText(message.quotedMessage.text)}} />
                                    )}

                                    {message.quotedMessage.type === 'image' && (
                                      <div className="flex items-center gap-1.5 text-[11px]">
                                        <svg viewBox="0 0 24 24" width="13" height="13" fill="currentColor" className="text-gray-500 flex-shrink-0"><path d="M21 19V5c0-1.1-.9-2-2-2H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2zM8.5 13.5l2.5 3.01L14.5 12l4.5 6H5l3.5-4.5z"/></svg>
                                        <span className="text-gray-600" dangerouslySetInnerHTML={{__html: linkifyText(message.quotedMessage.caption || 'Photo')}} />
                                      </div>
                                    )}

