                                        <span className="text-gray-600" dangerouslySetInnerHTML={{__html: linkifyText(message.quotedMessage.caption || 'Video')}} />
                                      </div>
                                    )}

                                    {message.quotedMessage.type === 'audio' && (
                                      <div className="flex items-center gap-1.5 text-[11px]">
                                        <svg viewBox="0 0 24 24" width="13" height="13" fill="currentColor" className="text-gray-500 flex-shrink-0"><path d="M12 3C6.48 3 2 6.82 2 11.5S6.48 20 12 20s10-3.82 10-8.5S17.52 3 12 3zm-2 10l-4 4V7l4 4zm6-4v8l-4-4 4-4z"/></svg>
                                        <span className="text-gray-600">Voice Message</span>
                                      </div>
                                    )}

                                    {message.quotedMessage.type === 'document' && (
                                      <div className="flex items-center gap-1.5 text-[11px]">
                                        <svg viewBox="0 0 24 24" width="13" height="13" fill="currentColor" className="text-gray-500 flex-shrink-0"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8l-8-6z"/></svg>
                                        <span className="text-gray-600 truncate" dangerouslySetInnerHTML={{__html: linkifyText(message.quotedMessage.fileName || message.quotedMessage.caption || 'Document')}} />
                                      </div>
                                    )}

                                    {!['text', 'image', 'video', 'audio', 'document'].includes(message.quotedMessage.type || '') && (
                                      <p className="text-[12px] text-gray-600" dangerouslySetInnerHTML={{__html: linkifyText(message.quotedMessage.text || 'Original message')}} />
                                    )}
                                  </div>
                                </div>
                              </div>
