                    >
                      Discard
                    </button>
                    <button
                      onClick={sendVoiceMessage}
                      disabled={sending}
                      className="flex-1 sm:flex-none bg-[#00a884] text-white rounded-lg px-4 py-2 font-medium hover:bg-[#008f6f] transition-colors disabled:opacity-50 flex items-center justify-center gap-2"
                      title="Send Voice Message"
                    >
                      <svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor">
                        <path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z" />
                      </svg>
                      Send
                    </button>
                  </div>
                </div>
              </div>
            ) : (sessionTimeLeft === 0 && !isNote) ? (
              <div className="flex flex-col sm:flex-row items-center justify-between bg-yellow-50/80 border border-yellow-200/60 p-3 rounded-xl">
                <div className="flex items-center gap-3 mb-3 sm:mb-0">
                  <div className="w-10 h-10 rounded-full bg-yellow-100 flex items-center justify-center shrink-0 text-yellow-600">
                    <svg viewBox="0 0 24 24" fill="none" strokeWidth={1.5} stroke="currentColor" className="w-6 h-6">
                      <path strokeLinecap="round" strokeLinejoin="round" d="M12 6v6h4.5m4.5 0a9 9 0 11-18 0 9 9 0 0118 0z" />
                    </svg>
                  </div>
                  <div>
                    <h4 className="text-sm font-semibold text-gray-900">24-Hour Window Expired</h4>
                    <p className="text-xs text-gray-600">You must use a Template Message to reply, or switch to Internal Note.</p>
                  </div>
                </div>
                <div className="flex gap-2 w-full sm:w-auto">
                  <button
                    onClick={() => setIsNote(true)}
                    className="flex-1 sm:flex-none px-4 py-2 rounded-lg bg-white border border-gray-200 text-gray-700 text-sm font-medium hover:bg-gray-50 transition-colors"
                  >
                    Write Note
                  </button>
                  <button
                    onClick={() => setIsTemplateModalOpen(true)}
                    className="flex-1 sm:flex-none flex items-center justify-center gap-2 px-4 py-2 rounded-lg bg-[#00a884] hover:bg-[#008f6f] text-white text-sm font-medium transition-colors shadow-sm"
                  >
                    <svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor">
                      <path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z" />
                    </svg>
                    Send Template
                  </button>
                </div>
              </div>
            ) : (
              <div className="flex flex-col">
                {replyingToMsg && (
                  <div className="flex items-center justify-between bg-gray-50 px-4 py-2 border-l-4 border-[#00a884] rounded-t-lg mx-2 mt-[-10px] mb-2 shadow-sm relative z-0">
                    <div className="flex flex-col flex-1 min-w-0 pr-4">
                      <span className="text-[#00a884] text-[13px] font-semibold truncate">
                        {replyingToMsg.direction === 'inbound'
                          ? (chat?.contactId?.nickname || chat?.contactId?.name || chat?.contactId?.nameOnWhatsApp || formatInternationalPhone(chat?.waId || chat?.phoneNumber) || 'Customer')
                          : (typeof replyingToMsg.sentBy === 'object' && 'name' in replyingToMsg.sentBy ? (replyingToMsg.sentBy as any).name : 'Staff')}
                      </span>
                      <span className="text-gray-600 text-[13px] truncate flex items-center gap-1 mt-0.5">
                        {replyingToMsg.type === 'image' && <svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor"><path d="M21 19V5c0-1.1-.9-2-2-2H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2zM8.5 13.5l2.5 3.01L14.5 12l4.5 6H5l3.5-4.5z" /></svg>}
                        {replyingToMsg.type === 'video' && <svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor"><path d="M17 10.5V7c0-.55-.45-1-1-1H4c-.55 0-1 .45-1 1v10c0 .55.45 1 1 1h12c.55 0 1-.45 1-1v-3.5l4 4v-11l-4 4z" /></svg>}
                        {replyingToMsg.type === 'audio' && <svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor"><path d="M12 14c1.66 0 2.99-1.34 2.99-3L15 5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3zm5.3-3c0 3-2.54 5.1-5.3 5.1S6.7 14 6.7 11H5c0 3.41 2.72 6.23 6 6.72V21h2v-3.28c3.28-.48 6-3.3 6-6.72h-1.7z" /></svg>}
                        {replyingToMsg.type === 'document' && <svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor"><path d="M14 2H6c-1.1 0-1.99.9-1.99 2L4 20c0 1.1.89 2 1.99 2H18c1.1 0 2-.9 2-2V8l-6-6zm2 16H8v-2h8v2zm0-4H8v-2h8v2zm-3-5V3.5L18.5 9H13z" /></svg>}
                        {replyingToMsg.text || replyingToMsg.caption || (replyingToMsg.type !== 'text' ? replyingToMsg.type.charAt(0).toUpperCase() + replyingToMsg.type.slice(1) : '')}
                      </span>
                    </div>
                    {replyingToMsg.mediaUrl && replyingToMsg.type === 'image' && (
                      <div className="w-[40px] h-[40px] shrink-0 ml-2 rounded overflow-hidden">
                        {/* eslint-disable-next-line @next/next/no-img-element */}
                        <img src={replyingToMsg.mediaUrl} alt="preview" className="w-full h-full object-cover" />
                      </div>
                    )}
                    <button onClick={() => setReplyingToMsg(null)} className="text-gray-400 hover:text-gray-600 p-1.5 ml-2 hover:bg-gray-200 rounded-full transition-colors shrink-0">
                      <svg viewBox="0 0 24 24" width="20" height="20" fill="currentColor">
                        <path d="M19 6.41L17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12z" />
                      </svg>
                    </button>
                  </div>
                )}
                <div className="px-4">
                  <AISuggestionPanel
                    suggestion={aiSuggestion}
                    isLoading={isAiLoading}
                    onAccept={(suggestion) => {
                      setNewMessage(suggestion)
                      setAiSuggestion(null)
                      setAiError(null)
                      aiMessageService.cancel()
                      composerInputRef.current?.focus()
                    }}
                    onSend={handleSendAiSuggestion}
                    onDismiss={() => {
                      setAiSuggestion(null)
                      setAiError(null)
                      aiMessageService.cancel()
                    }}
                  />
                </div>
                <form onSubmit={handleSendMessage} className="flex gap-2 items-center relative z-10">
                  {/* Attachment Menu */}
                  <div className="relative shrink-0">
                    <input
                      type="file"
                      ref={fileInputRef}
                      onChange={(e) => handleFileUpload(e, false)}
                      className="hidden"
                      accept="image/*,video/*"
                    />
                    <input
                      type="file"
                      id="documentInput"
                      onChange={(e) => handleFileUpload(e, true)}
                      className="hidden"
                    />

                    <button
                      type="button"
                      onClick={() => {
                        const menu = document.getElementById('attachment-menu');
                        if (menu) menu.classList.toggle('hidden');
                      }}
                      onBlur={() => {
                        setTimeout(() => {
                          const menu = document.getElementById('attachment-menu');
                          if (menu) menu.classList.add('hidden');
                        }, 200);
                      }}
                      disabled={sending || (sessionTimeLeft === 0 && !isNote)}
                      className="text-gray-500 hover:text-gray-700 p-2 disabled:opacity-50 transition-colors relative shrink-0"
                      title={sessionTimeLeft === 0 && !isNote ? "Session expired" : "Attach"}
                    >
                      <svg viewBox="0 0 24 24" width="24" height="24" fill="currentColor" className={sending || (sessionTimeLeft === 0 && !isNote) ? 'opacity-50' : ''}>
                        <path d="M16.5 6v11.5c0 2.21-1.79 4-4 4s-4-1.79-4-4V5a2.5 2.5 0 0 1 5 0v10.5c0 .55-.45 1-1 1s-1-.45-1-1V6H10v9.5a2.5 2.5 0 0 0 5 0V5c0-2.21-1.79-4-4-4S7 2.79 7 5v12.5c0 3.04 2.46 5.5 5.5 5.5s5.5-2.46 5.5-5.5V6h-1.5z" />
                      </svg>
                    </button>

                    {/* Dropdown Menu */}
                    <div
                      id="attachment-menu"
                      className="hidden absolute bottom-full left-0 mb-2 w-48 bg-white rounded-lg shadow-lg border border-gray-100 py-2 z-50 transform origin-bottom-left transition-all"
                    >
                      <button
                        type="button"
                        onClick={() => {
                          document.getElementById('documentInput')?.click();
                          document.getElementById('attachment-menu')?.classList.add('hidden');
                        }}
                        className="w-full text-left px-4 py-3 hover:bg-gray-50 flex items-center gap-3 transition-colors"
                      >
                        <div className="w-8 h-8 rounded-full bg-[#7F66FF] flex items-center justify-center text-white shadow-sm">
                          <svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor">
                            <path d="M14 2H6c-1.1 0-1.99.9-1.99 2L4 20c0 1.1.89 2 1.99 2H18c1.1 0 2-.9 2-2V8l-6-6zm2 16H8v-2h8v2zm0-4H8v-2h8v2zm-3-5V3.5L18.5 9H13z" />
                          </svg>
                        </div>
                        <span className="text-sm font-medium text-gray-700">Document</span>
                      </button>

                      <button
                        type="button"
                        onClick={() => {
                          fileInputRef.current?.click();
                          document.getElementById('attachment-menu')?.classList.add('hidden');
                        }}
                        className="w-full text-left px-4 py-3 hover:bg-gray-50 flex items-center gap-3 transition-colors"
                      >
                        <div className="w-8 h-8 rounded-full bg-[#007AFC] flex items-center justify-center text-white shadow-sm">
                          <svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor">
                            <path d="M21 19V5c0-1.1-.9-2-2-2H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2zM8.5 13.5l2.5 3.01L14.5 12l4.5 6H5l3.5-4.5z" />
                          </svg>
                        </div>
                        <span className="text-sm font-medium text-gray-700">Photos & Videos</span>
                      </button>

                      <button
                        type="button"
                        onClick={() => {
                          setShowProductPopup(true);
                          document.getElementById('attachment-menu')?.classList.add('hidden');
                        }}
                        className="w-full text-left px-4 py-3 hover:bg-gray-50 flex items-center gap-3 transition-colors"
                      >
                        <div className="w-8 h-8 rounded-full bg-[#10b981] flex items-center justify-center text-white shadow-sm">
                          <svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor">
                            <path d="M20 6h-4V4c0-1.11-.89-2-2-2h-4c-1.11 0-2 .89-2 2v2H4c-1.11 0-1.99.89-1.99 2L2 19c0 1.11.89 2 2 2h16c1.11 0 2-.89 2-2V8c0-1.11-.89-2-2-2zm-6 0h-4V4h4v2z" />
                          </svg>
                        </div>
                        <span className="text-sm font-medium text-gray-700">Product</span>
                      </button>

                      <button
                        type="button"
                        onClick={() => {
                          setIsTemplateModalOpen(true);
                          document.getElementById('attachment-menu')?.classList.add('hidden');
                        }}
                        className="w-full text-left px-4 py-3 hover:bg-gray-50 flex items-center gap-3 transition-colors border-t border-gray-50"
                      >
                        <div className="w-8 h-8 rounded-full bg-[#00a884] flex items-center justify-center text-white shadow-sm">
                          <svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor">
                            <path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z" />
                          </svg>
                        </div>
                        <span className="text-sm font-medium text-gray-700">Template Message</span>
                      </button>
                    </div>
                  </div>

                  {/* Note Toggle */}
                  <button
                    type="button"
                    onClick={() => setIsNote(!isNote)}
                    className={`p-[7px] rounded-full transition-colors border shadow-sm shrink-0 ${isNote ? 'bg-[#fff5c4] text-yellow-700 border-yellow-300 hover:bg-yellow-200' : 'bg-gray-50 text-gray-500 border-gray-200 hover:bg-gray-100'}`}
                    title={isNote ? "Internal Note Mode ON" : "Switch to Internal Note"}
                  >
                    <svg viewBox="0 0 24 24" width="20" height="20" fill="currentColor">
                      <path d="M3 17.25V21h3.75L17.81 9.94l-3.75-3.75L3 17.25zM20.71 7.04c.39-.39.39-1.02 0-1.41l-2.34-2.34c-.39-.39-1.02-.39-1.41 0l-1.83 1.83 3.75 3.75 1.83-1.83z" />
                    </svg>
                  </button>
                  <div className="relative flex-1 flex items-center">
                    {/* Emoji Toggle Button */}
                    <button
                      type="button"
                      onClick={() => setShowEmojiPicker(!showEmojiPicker)}
                      className="absolute left-3 p-1 text-gray-400 hover:text-gray-600 transition-colors bg-transparent border-none outline-none focus:outline-none z-10"
                      title="Choose an Emoji"
                      disabled={sending || (sessionTimeLeft === 0 && !isNote)}
                    >
                      <svg viewBox="0 0 24 24" width="22" height="22" fill="currentColor">
                        <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.41 0-8-3.59-8-8s3.59-8 8-8 8 3.59 8 8-3.59 8-8 8zm3.5-9c.83 0 1.5-.67 1.5-1.5S16.33 8 15.5 8 14 8.67 14 9.5s.67 1.5 1.5 1.5zm-7 0c.83 0 1.5-.67 1.5-1.5S7.33 8 6.5 8 5 8.67 5 9.5 5.67 11 6.5 11zm3.5 6.5c2.33 0 4.31-1.46 5.11-3.5H8.89c.8 2.04 2.78 3.5 5.11 3.5z" />
                      </svg>
                    </button>
                    <textarea
                      ref={composerInputRef}
                      value={newMessage}
                      onChange={(e) => {
                        const val = capitalizeFirstCharacter(e.target.value)
                        setNewMessage(val)

                        // Slash command detection
                        if (val.startsWith('/') && !isNote) {
                          setShowQuickReplies(true)
                          setQuickReplyQuery(val.slice(1).toLowerCase())
                          setSelectedQuickReplyIdx(0)
                        } else {
                          setShowQuickReplies(false)
                        }

                        // AI Message Improvement - trigger on typing pause
                        if (!isNote) {
                          aiMessageService.requestImprovement(
                            val,
                            (suggestion) => setAiSuggestion(suggestion),
                            () => {}, // Ignore errors - only show when processing completes
                            (isLoading) => setIsAiLoading(isLoading)
                          )
                        } else {
                          // Clear AI suggestion when in note mode
                          aiMessageService.cancel()
                          setAiSuggestion(null)
                          setAiError(null)
                        }
                      }}
                      onKeyDown={(e) => {
                        if (showQuickReplies) {
                          if (e.key === 'ArrowDown') {
                            e.preventDefault()
                            setSelectedQuickReplyIdx(prev => (prev + 1) % filteredQuickRepliesForInput.length)
                          } else if (e.key === 'ArrowUp') {
                            e.preventDefault()
                            setSelectedQuickReplyIdx(prev => (prev - 1 + filteredQuickRepliesForInput.length) % filteredQuickRepliesForInput.length)
                          } else if (e.key === 'Enter') {
                            e.preventDefault()
                            if (filteredQuickRepliesForInput[selectedQuickReplyIdx]) {
                              handleSelectQuickReply(filteredQuickRepliesForInput[selectedQuickReplyIdx])
                            }
                          } else if (e.key === 'Escape') {
                            setShowQuickReplies(false)
                          }
                        } else if (e.key === 'Enter') {
