  // Live session countdown timer
  // Using useRef to avoid re-renders that lose text selection
  const sessionTimeLeftRef = useRef<number | null>(null)

  useEffect(() => {
    if (!chat?.sessionExpiresAt) {
      sessionTimeLeftRef.current = null
      setSessionTimeLeft(null)
      return
    }

    const tick = () => {
      const diff = Math.floor((new Date(chat.sessionExpiresAt!).getTime() - Date.now()) / 1000)
      const timeLeft = diff > 0 ? diff : 0
      sessionTimeLeftRef.current = timeLeft
      // Only update state when transitioning to/from 0 to avoid constant re-renders
      setSessionTimeLeft(prev => {
        if ((prev === null || prev > 0) && timeLeft === 0) return 0
        if ((prev === 0 || prev === null) && timeLeft > 0) return timeLeft
        return prev
      })
    }
    tick()
    const interval = setInterval(tick, 1000)
    return () => clearInterval(interval)
  }, [chat?.sessionExpiresAt])

  useEffect(() => {
    if (!socket || !chatId) return

    const handleNewMessage = (data: { chatId: string, message: Message }) => {
      if (data.chatId?.toString() === chatId) {
        setMessages(prev => {
          // 1. Skip if this _id was already confirmed via our own HTTP response
          //    (prevents the duplicate that occurs when the socket event races the HTTP await)
          if (confirmedMessageIds.current.has(data.message._id)) {
            confirmedMessageIds.current.delete(data.message._id)
            return prev
          }

          // 2. Exact ID match check (covers normal dedup)
          if (prev.some(m => m._id === data.message._id)) return prev

          // 3. Race condition check: socket arrived before HTTP response replaced temp.
          //    Match on temp- prefix + type + content.
          if (data.message.direction !== 'inbound') {
            const tempIndex = prev.findIndex(m =>
              m._id.toString().startsWith('temp-') &&
              m.type === data.message.type &&
              (m.text === data.message.text || m.caption === data.message.caption)
            )

            if (tempIndex !== -1) {
              // Replace the temp message with the real one from the socket
              const newMessages = [...prev]
              newMessages[tempIndex] = data.message
              return newMessages
            }
          }

          // Otherwise, just add the new message
          return [...prev, data.message]
        })

        // If it's an inbound message, also mark chat as read
        if (data.message.direction === 'inbound') {
          chatsApi.markRead(chatId).catch(console.error)
        }
      }
    }

    const handleMessageStatus = (data: { chatId: string, messageId: string, waMessageId: string, status: string, errorCode?: number, errorMessage?: string }) => {
      if (data.chatId?.toString() === chatId) {
        setMessages(prev => prev.map(m =>
          m._id === data.messageId || m.messageId === data.waMessageId
            ? {
              ...m,
              status: data.status as any,
              ...(data.status === 'failed' && { errorCode: data.errorCode, errorMessage: data.errorMessage }),
            }
            : m
        ))
      }
    }

    const handleMessageReaction = (data: { chatId: string, messageId: string, reactions: any[] }) => {
      if (data.chatId === chatId) {
        setMessages(prev => prev.map(m =>
          m._id === data.messageId
            ? { ...m, reactions: data.reactions }
            : m
        ))
      }
    }

    const handleMessageDelete = (data: { chatId: string, messageId: string }) => {
      if (data.chatId === chatId) {
        setMessages(prev => prev.filter(m => m._id !== data.messageId))
        setContextMenuMsg(null)
      }
    }

    // Handle real-time assignment updates
    const handleChatAssigned = (data: { chatId: string; chat: any; systemMessage?: any }) => {
      if (data.chatId === chatId) {
        setChat(data.chat)
        // Append the real persisted system message (avoids duplicating on refresh)
        if (data.systemMessage) {
          setMessages(prev => [...prev, data.systemMessage])
        }

        // If a staff user is viewing this chat and it was reassigned to someone else,
        // redirect them away since they no longer own it
        const newAssignedId = data.chat?.assignedTo?._id || data.chat?.assignedTo
        if (isStaff && currentUser?._id && newAssignedId && newAssignedId.toString() !== currentUser._id.toString()) {
          router.push('/chats')
        }
      }
    }

    // Handle real-time chat status/metadata updates (e.g. closed → open when customer messages)
    // Preserve populated fields (tags, contactId) from local state since the backend
    // does not populate them before emitting chat:update.
    const handleChatUpdate = (data: { chatId: string; chat: any }) => {
      if (data.chatId.toString() === chatId) {
        setChat(prev => {
          if (!prev) return data.chat
          // Merge a populated contact when the backend sends one (so live changes like
          // opt-out/block/name refresh); otherwise keep the local populated contact.
          const incomingContact = data.chat?.contactId
          const incomingIsPopulated = incomingContact && typeof incomingContact === 'object'
            && ('isOptedOut' in incomingContact || 'isBlocked' in incomingContact || 'name' in incomingContact)
          return {
            ...prev,
            ...data.chat,
            // Keep the populated versions from local state
            tags: prev.tags,
            contactId: incomingIsPopulated ? { ...prev.contactId, ...incomingContact } : prev.contactId,
          }
        })
      }
    }

    // Personal notification for the assigned staff member
    const handleAssignedToMe = (data: { chatId: string; chat: any; assignedByName: string }) => {
      setToast({
        message: `Chat assigned to you by ${data.assignedByName}`,
        chatId: data.chatId,
      })
      // Auto-dismiss after 6 seconds
      setTimeout(() => setToast(null), 6000)
    }

    // Call event handlers
    const handleCallIncoming = (data: { chatId: string; callLog: CallLog }) => {
      if (data.chatId === chatId) {
        setIncomingCall(data.callLog)
      }
    }
    const handleCallStatus = async (data: { chatId: string; callLog: CallLog }) => {
      if (data.chatId === chatId) {
        if (activeCall && data.callLog._id === activeCall._id && data.callLog.status !== 'accepted') {
          setActiveCall(data.callLog)
        }
        if (data.callLog.status === 'accepted') {
          setActiveCall(data.callLog)
          setIncomingCall(null)
          startCallClock()
          if (!livekitRoomRef.current) {
            try {
              await joinCallAudio(data.callLog._id)
            } catch (_) {}
          }
        } else if (data.callLog.status === 'ringing') {
          setIncomingCall(data.callLog)
        }
      }
    }
    const handleCallTerminated = async (data: { chatId: string; callLog: CallLog }) => {
      if (data.chatId === chatId) {
        setActiveCall(null)
        setIncomingCall(null)
        stopCallClock()
        await disconnectCallAudio()
      }
    }
    const handleCallOutgoing = (data: { chatId: string; callLog: CallLog }) => {
      if (data.chatId === chatId) {
        setActiveCall(data.callLog)
      }
    }
    const handleCallPermissionRequested = (data: { chatId: string }) => {
      if (data.chatId === chatId) {
        setToast({ message: 'Call permission request sent', chatId })
        setTimeout(() => setToast(null), 3000)
      }
    }

    socket.on('message:new', handleNewMessage)
    socket.on('message:status', handleMessageStatus)
    socket.on('message:reaction', handleMessageReaction)
    socket.on('chat:assigned', handleChatAssigned)
    socket.on('chat:update', handleChatUpdate)
    socket.on('chat:assigned:me', handleAssignedToMe)
    socket.on('message:delete', handleMessageDelete)
    socket.on('call:incoming', handleCallIncoming)
    socket.on('call:status', handleCallStatus)
    socket.on('call:terminated', handleCallTerminated)
    socket.on('call:outgoing', handleCallOutgoing)
    socket.on('call:permission_requested', handleCallPermissionRequested)

    return () => {
      socket.off('message:new', handleNewMessage)
      socket.off('message:status', handleMessageStatus)
      socket.off('message:reaction', handleMessageReaction)
      socket.off('chat:assigned', handleChatAssigned)
      socket.off('chat:update', handleChatUpdate)
      socket.off('chat:assigned:me', handleAssignedToMe)
      socket.off('message:delete', handleMessageDelete)
      socket.off('call:incoming', handleCallIncoming)
      socket.off('call:status', handleCallStatus)
      socket.off('call:terminated', handleCallTerminated)
      socket.off('call:outgoing', handleCallOutgoing)
      socket.off('call:permission_requested', handleCallPermissionRequested)
      stopCallClock()
    }
  }, [socket, chatId, isStaff, currentUser?._id, router, activeCall])

  const loadChatData = async () => {
    try {
      const limit = targetMessageId ? 300 : 100
      const [chatData, messagesData, tagsData, quickRepliesData] = await Promise.all([
        chatsApi.get(chatId),
        chatsApi.getMessages(chatId, { limit }),
        tagsApi.list(),
        quickRepliesApi.list()
      ])

      // Both admins and staff need the staff list (staff can reassign too)
      usersApi.listStaff().then(data => {
        setActiveStaff(data.users)
      }).catch(console.error)

      setChat(chatId === 'new' ? null : chatData) // Handle potential new chat state
      setChat(chatData)
      setAvailableTags(tagsData)
      setQuickReplies(quickRepliesData)
      // Messages are already ordered chronologically (oldest to newest) by the backend's .reverse()
      setMessages(messagesData.messages || [])

      // Mark as read when opening
      if (chatData.isUnread && !chatData.isManuallyUnread) {
        await chatsApi.markRead(chatId)
      }
    } catch (error) {
      console.error('Failed to load chat details:', error)
    } finally {
      setLoading(false)
    }
  }

  const scrollToBottom = () => {
    if (!showMsgSearch) messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }

  // Quick Replies Helpers
  const filteredQuickRepliesForInput = useMemo(() => {
    return quickReplies.filter(qr => {
      const matchesQuery = qr.shortcut.toLowerCase().includes(quickReplyQuery)
      const matchesTab = quickReplyTab === 'all' || (quickReplyTab === 'me' && qr.userId === currentUser?._id)
      return matchesQuery && matchesTab
    })
  }, [quickReplies, quickReplyQuery, quickReplyTab, currentUser?._id])

  const handleSelectQuickReply = async (qr: QuickReply) => {
    setShowQuickReplies(false)

    // Text-only quick reply: populate the input so the agent can review/edit before sending.
    if (!qr.mediaUrl) {
      setNewMessage(qr.message)
      return
    }

    // Media quick reply: send the media immediately, using the message as the caption,
    // so the customer receives the image (or other media) together with the text.
    if (sending) return
    setSending(true)
    setNewMessage('')

    const type = (qr.mediaType || 'image') as string
    const replyId = replyingToMsg ? replyingToMsg._id : undefined
    setReplyingToMsg(null)

    // Optimistic message
    const tempMessage: Message = {
      _id: 'temp-' + Date.now(),
      chatId,
      waId: chat?.waId || '',
      direction: 'outbound',
      type: type as any,
      caption: qr.message,
      mediaUrl: qr.mediaUrl,
      status: 'sent',
      createdAt: new Date().toISOString()
    }
    setMessages(prev => [...prev, tempMessage])

    try {
      const savedMsg = await chatsApi.sendMessage(chatId, {
        type,
        mediaUrl: qr.mediaUrl,
        caption: qr.message,
        replyToMessageId: replyId
      })
      confirmedMessageIds.current.add(savedMsg._id)
      setMessages(prev => prev.map(m => m._id === tempMessage._id ? savedMsg : m))
    } catch (error: any) {
      console.error('Failed to send quick reply media:', error)
      setMessages(prev => prev.map(m => {
        if (m._id === tempMessage._id) {
          failedMessageData.current.set(m._id, { type: m.type, mediaUrl: m.mediaUrl, caption: m.caption })
          return { ...m, status: 'failed' as any }
        }
        return m
      }))
    } finally {
      setSending(false)
    }
  }

  // Debounce and perform database search for in-chat messages
  useEffect(() => {
    if (dbSearchTimeoutRef.current) {
      clearTimeout(dbSearchTimeoutRef.current)
    }

    const trimmed = msgSearchQuery.trim()
    if (!trimmed) {
      setDbSearchMatches([])
      setSearchLoading(false)
      return
    }

    setSearchLoading(true)
    dbSearchTimeoutRef.current = setTimeout(async () => {
      try {
        const res = await messagesApi.search(trimmed, chatId)
        // Sort matches chronologically (oldest to newest) to match chat flow direction
        const sorted = (res.data || []).sort((a: any, b: any) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime())
        setDbSearchMatches(sorted)
        setSearchMatchIndex(0)
      } catch (err) {
        console.error('In-chat message search failed:', err)
        setDbSearchMatches([])
      } finally {
        setSearchLoading(false)
      }
    }, 400)

    return () => {
      if (dbSearchTimeoutRef.current) clearTimeout(dbSearchTimeoutRef.current)
    }
  }, [msgSearchQuery, chatId])

  const openMsgSearch = () => {
    setShowMsgSearch(true)
    setMsgSearchQuery('')
    setSearchMatchIndex(0)
    setDbSearchMatches([])
    setTimeout(() => msgSearchInputRef.current?.focus(), 50)
  }

  const closeMsgSearch = () => {
    setShowMsgSearch(false)
    setMsgSearchQuery('')
    setDbSearchMatches([])
    setSearchMatchIndex(0)
  }

  const goToMatch = async (idx: number) => {
    if (dbSearchMatches.length === 0) return
    const wrappedIdx = (idx + dbSearchMatches.length) % dbSearchMatches.length
    setSearchMatchIndex(wrappedIdx)

    const targetMatch = dbSearchMatches[wrappedIdx]
    const targetId = targetMatch._id

    // Check if the message is in our current messages state
    const msgExists = messages.some(m => m._id === targetId)
    if (msgExists) {
      // It exists locally! Scroll to it.
      setTimeout(() => {
        const element = document.getElementById(`msg-${targetId}`)
        if (element) {
          element.scrollIntoView({ behavior: 'smooth', block: 'center' })
          setHighlightedMessageId(targetId)

          const highlightTimer = setTimeout(() => {
            setHighlightedMessageId(null)
          }, 2500)
          return () => clearTimeout(highlightTimer)
        }
      }, 100)
    } else {
      // It does NOT exist locally! Fetch from the backend including this message.
      try {
        setLoading(true)
        const { messages: fetchedMessages } = await chatsApi.getMessages(chatId, { messageId: targetId })
        setMessages(fetchedMessages || [])

        // Wait for rendering to finish, then scroll and highlight
        setTimeout(() => {
          const element = document.getElementById(`msg-${targetId}`)
          if (element) {
            element.scrollIntoView({ behavior: 'smooth', block: 'center' })
            setHighlightedMessageId(targetId)

            const highlightTimer = setTimeout(() => {
              setHighlightedMessageId(null)
            }, 2500)
            return () => clearTimeout(highlightTimer)
          }
        }, 300)
      } catch (err) {
        console.error('Failed to load older messages for search match:', err)
      } finally {
        setLoading(false)
      }
    }
  }

  // Convert URLs in text to clickable links
  const linkifyText = (text: string) => {
    // Regex to match URLs (http, https, www, etc.)
    const urlRegex = /(https?:\/\/[^\s<>"{}|\\^`\[\]]*|www\.[^\s<>"{}|\\^`\[\]]*|[a-zA-Z0-9][a-zA-Z0-9-]*\.[a-zA-Z]{2,}\/[^\s<>"{}|\\^`\[\]]*)/gi
    return text.replace(urlRegex, (url) => {
      let href = url
      if (!url.match(/^https?:\/\//)) {
        href = url.startsWith('www.') ? `https://${url}` : `https://${url}`
      }
      return `<a href="${href}" target="_blank" rel="noopener noreferrer" class="text-blue-600 hover:text-blue-800 hover:underline break-all pointer-events-auto" onclick="event.stopPropagation()">${url}</a>`
    })
  }

  const highlightText = (text: string, query: string) => {
    if (!query.trim()) return text
    const parts = text.split(new RegExp(`(${query.replace(/[.*+?^${}()|[\\]\\]/g, '\\$&')})`, 'gi'))
    return parts.map((part, i) =>
      part.toLowerCase() === query.toLowerCase()
        ? `<mark class="bg-yellow-300 text-black rounded px-0.5">${part}</mark>`
        : part
    ).join('')
  }

  // Process text to add both links and highlighting
  const processMessageText = (text: string, query: string = '') => {
    let result = text
    // First linkify the text
    result = linkifyText(result)
    // Then highlight search results
    if (query.trim()) {
      // For highlighting, we need to be careful not to break HTML tags
      const urlRegex = /<a[^>]*>.*?<\/a>/gi
      const links = result.match(urlRegex) || []
      let linkIndex = 0
      result = result.replace(urlRegex, () => `__LINK_PLACEHOLDER_${linkIndex++}__`)

      // Highlight the non-link parts
      const parts = result.split(new RegExp(`(${query.replace(/[.*+?^${}()|[\\]\\]/g, '\\$&')})`, 'gi'))
      result = parts.map((part) =>
        part.toLowerCase() === query.toLowerCase()
          ? `<mark class="bg-yellow-300 text-black rounded px-0.5">${part}</mark>`
          : part
      ).join('')

      // Restore links
      linkIndex = 0
      result = result.replace(/__LINK_PLACEHOLDER_\d+__/g, () => links[linkIndex++])
    }
    return result
  }

  const handleSendMessage = async (e?: React.FormEvent) => {
