                  <div className="flex flex-col items-center justify-center py-16 text-gray-400">
                    <div className="animate-spin h-8 w-8 border-3 border-violet-500 border-t-transparent rounded-full mb-3" />
                    <p className="text-sm font-medium">Loading messages...</p>
                  </div>
                ) : autoMessages.length === 0 ? (
                  <div className="flex flex-col items-center justify-center py-16 text-gray-400">
                    <div className="w-16 h-16 rounded-full bg-gray-100 flex items-center justify-center mb-4">
                      <svg viewBox="0 0 24 24" width="32" height="32" fill="currentColor">
                        <path d="M20 2H4c-1.1 0-2 .9-2 2v18l4-4h14c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2zm0 14H6l-2 2V4h16v12z" />
                      </svg>
                    </div>
                    <p className="text-sm font-medium text-gray-500">No automated messages yet</p>
                    <p className="text-xs text-gray-400 mt-1">Bot and auto-reply messages will appear here</p>
                  </div>
                ) : (
                  <div className="divide-y divide-gray-50">
                    {autoMessages.map((msg) => {
                      const sourceColors: Record<string, { bg: string; text: string; border: string }> = {
                        bot: { bg: 'bg-purple-50', text: 'text-purple-700', border: 'border-purple-200' },
                        text_code: { bg: 'bg-emerald-50', text: 'text-emerald-700', border: 'border-emerald-200' },
                        image_ocr: { bg: 'bg-amber-50', text: 'text-amber-700', border: 'border-amber-200' },
                      }
                      const colors = sourceColors[msg.source] || sourceColors.bot

                      return (
                        <div key={msg._id} className="px-5 py-4 hover:bg-gray-50/50 transition-colors">
                          {/* Source Badge & Time */}
                          <div className="flex items-center justify-between mb-2">
                            <div className="flex items-center gap-2">
                              <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[11px] font-bold border ${colors.bg} ${colors.text} ${colors.border}`}>
                                {msg.source === 'bot' && (
                                  <svg viewBox="0 0 24 24" width="12" height="12" fill="currentColor"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-2 15l-5-5 1.41-1.41L10 14.17l7.59-7.59L19 8l-9 9z" /></svg>
                                )}
                                {msg.source === 'text_code' && (
                                  <svg viewBox="0 0 24 24" width="12" height="12" fill="currentColor"><path d="M20 2H4c-1.1 0-1.99.9-1.99 2L2 22l4-4h14c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2zM9 11H7V9h2v2zm4 0h-2V9h2v2zm4 0h-2V9h2v2z" /></svg>
                                )}
                                {msg.source === 'image_ocr' && (
                                  <svg viewBox="0 0 24 24" width="12" height="12" fill="currentColor"><path d="M21 19V5c0-1.1-.9-2-2-2H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2zM8.5 13.5l2.5 3.01L14.5 12l4.5 6H5l3.5-4.5z" /></svg>
                                )}
                                {msg.sourceLabel}
                              </span>
                              {msg.flowName && (
                                <span className="text-[10px] font-medium text-purple-500 bg-purple-50 px-2 py-0.5 rounded-md">
                                  {msg.flowName}
                                </span>
                              )}
                            </div>
                            <span className="text-[11px] text-gray-400 font-medium whitespace-nowrap">
                              {new Date(msg.createdAt).toLocaleString('en-IN', {
                                day: '2-digit', month: 'short',
                                hour: '2-digit', minute: '2-digit',
                                hour12: true
                              })}
                            </span>
                          </div>

                          {/* Product Code Badge */}
                          {msg.productCode && (
                            <div className="flex items-center gap-2 mb-2">
                              <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded bg-gray-100 text-gray-600 text-[11px] font-mono font-bold border border-gray-200">
                                <svg viewBox="0 0 24 24" width="11" height="11" fill="currentColor"><path d="M3 17.25V21h3.75L17.81 9.94l-3.75-3.75L3 17.25zM20.71 7.04c.39-.39.39-1.02 0-1.41l-2.34-2.34c-.39-.39-1.02-.39-1.41 0l-1.83 1.83 3.75 3.75 1.83-1.83z" /></svg>
                                Code: {msg.productCode}
                              </span>
                              {msg.productInfo && (
                                <span className="text-[10px] text-gray-500">
                                  {msg.productInfo.category && `${msg.productInfo.category.charAt(0).toUpperCase() + msg.productInfo.category.slice(1)}`}
                                  {msg.productInfo.weight && msg.productInfo.category && msg.productInfo.category.toLowerCase() !== 'silver' ? ` · ${msg.productInfo.weight}gm` : ''}
                                </span>
                              )}
                            </div>
                          )}

                          {/* Message Content */}
                          <div className="bg-white rounded-lg border border-gray-100 p-3 shadow-sm">
                            <p className="text-sm text-gray-700 whitespace-pre-wrap line-clamp-4">{msg.text || msg.caption || '(Media message)'}</p>
                          </div>

                          {/* Status */}
                          <div className="flex items-center gap-1.5 mt-2">
                            <div className={`w-1.5 h-1.5 rounded-full ${
                              msg.status === 'read' ? 'bg-blue-500' :
                              msg.status === 'delivered' ? 'bg-green-500' :
                              msg.status === 'sent' ? 'bg-gray-400' :
                              msg.status === 'failed' ? 'bg-red-500' : 'bg-gray-300'
                            }`} />
                            <span className="text-[10px] text-gray-400 capitalize">{msg.status || 'sent'}</span>
                          </div>
                        </div>
                      )
                    })}
                  </div>
                )}
              </div>
            </div>
          </div>
        )}

        <ProductSelectionPopup
          isOpen={showProductPopup}
          onClose={() => setShowProductPopup(false)}
          onSend={handleSendProducts}
        />

        {/* Zoom Image Modal */}
        {zoomImage && (
          <div
            className="fixed inset-0 z-[100] flex items-center justify-center bg-black/90 p-4"
            onClick={() => setZoomImage(null)}
          >
            <div className="relative w-full h-full flex flex-col items-center justify-center pointer-events-none">
              <div className="absolute top-4 right-4 flex gap-4 z-10 pointer-events-auto">
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    const fetchAndDownload = async () => {
                      try {
                        const response = await fetch(zoomImage);
                        const blob = await response.blob();
                        const blobUrl = window.URL.createObjectURL(blob);
                        const link = document.createElement('a');
                        link.href = blobUrl;
                        link.download = 'whatsapp-image.jpg';
                        document.body.appendChild(link);
                        link.click();
                        document.body.removeChild(link);
                        window.URL.revokeObjectURL(blobUrl);
                      } catch (error) {
                        window.open(zoomImage, '_blank');
                      }
                    };
                    fetchAndDownload();
                  }}
                  className="p-2 text-white bg-white/10 hover:bg-white/20 rounded-full transition-colors"
                  title="Download"
                >
                  <svg viewBox="0 0 24 24" width="24" height="24" fill="currentColor">
                    <path d="M19 9h-4V3H9v6H5l7 7 7-7zM5 18v2h14v-2H5z" />
                  </svg>
                </button>
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    setZoomImage(null);
                  }}
                  className="p-2 text-white bg-white/10 hover:bg-white/20 rounded-full transition-colors"
                  title="Close"
                >
                  <svg viewBox="0 0 24 24" width="24" height="24" fill="currentColor">
                    <path d="M19 6.41L17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12 19 6.41z" />
                  </svg>
                </button>
              </div>
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img
                src={zoomImage}
                alt="Zoomed Image"
                className="max-w-full max-h-[90vh] object-contain pointer-events-auto cursor-default"
                onClick={(e) => e.stopPropagation()}
              />
            </div>
          </div>
        )}

        {/* Reassignment Confirmation Modal */}
        {confirmAssign && (
          <div className="fixed inset-0 z-[110] flex items-center justify-center bg-black/60 p-4 backdrop-blur-sm animate-in fade-in duration-200">
            <div className="bg-white rounded-2xl shadow-2xl max-w-sm w-full overflow-hidden animate-in zoom-in-95 duration-200">
              <div className="p-6 text-center">
                <div className="w-16 h-16 bg-primary/10 rounded-full flex items-center justify-center mx-auto mb-4 text-primary">
                  <svg viewBox="0 0 24 24" width="32" height="32" fill="currentColor">
                    <path d="M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z" />
                  </svg>
                </div>
                <h3 className="text-xl font-bold text-gray-900 mb-2">Confirm Reassignment</h3>
                <p className="text-gray-500 mb-6">
                  Are you sure you want to assign this chat to <strong className="text-gray-900">{confirmAssign.name}</strong>?
                </p>
                <div className="flex gap-3">
                  <button
                    onClick={() => setConfirmAssign(null)}
                    className="flex-1 px-4 py-2.5 rounded-xl border border-gray-200 text-gray-700 font-medium hover:bg-gray-50 transition-colors"
                  >
                    Cancel
                  </button>
                  <button
                    onClick={executeAssignment}
                    className="flex-1 px-4 py-2.5 rounded-xl bg-gradient-primary text-white font-medium hover:opacity-90 transition-opacity shadow-lg shadow-primary/20"
                  >
                    Confirm
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Toast notification for staff when assigned a chat */}
        {toast && (
          <div className="fixed bottom-6 right-6 z-[200] flex items-start gap-3 bg-white border border-gray-200 shadow-2xl rounded-2xl px-5 py-4 max-w-sm animate-in slide-in-from-bottom-4 duration-300">
            <div className="w-10 h-10 rounded-full bg-[#00a884]/10 flex items-center justify-center text-[#00a884] flex-shrink-0 mt-0.5">
              <svg viewBox="0 0 24 24" width="22" height="22" fill="currentColor">
                <path d="M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z" />
              </svg>
            </div>
            <div className="flex-1 min-w-0">
              <p className="text-sm font-semibold text-gray-900">Chat Assigned</p>
              <p className="text-sm text-gray-500 mt-0.5">{toast.message}</p>
            </div>
            <button
              onClick={() => setToast(null)}
              className="text-gray-400 hover:text-gray-600 transition-colors ml-1 mt-0.5 flex-shrink-0"
            >
              <svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor">
                <path d="M19 6.41L17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12 19 6.41z" />
              </svg>
            </button>
          </div>
        )}

        {/* Close Chat Confirmation Modal */}
        <Modal
          isOpen={showCloseModal}
          onClose={() => setShowCloseModal(false)}
          title="Complete Chat"
        >
          <div className="space-y-6">
            <p className="text-gray-600">
              Are you sure you want to complete this chat? It will be moved to the closed status.
            </p>
            <div className="flex justify-end gap-3 pt-4 border-t border-gray-100">
              <button
                onClick={() => setShowCloseModal(false)}
                className="px-4 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-lg hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary"
              >
                Cancel
              </button>
              <button
                onClick={handleCloseChat}
                disabled={isClosing}
                className="px-4 py-2 text-sm font-medium text-white bg-green-600 rounded-lg hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-green-500 disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
              >
                {isClosing ? 'Completing...' : 'Complete Chat'}
              </button>
            </div>
          </div>
        </Modal>

        {/* Reopen Chat Confirmation Modal */}
        <Modal
          isOpen={showReopenModal}
          onClose={() => setShowReopenModal(false)}
          title="Reopen Chat"
        >
          <div className="space-y-6">
            <p className="text-gray-600">
              Are you sure you want to reopen this chat? It will be moved back to <strong>Open</strong> status and staff can continue messaging the customer.
            </p>
            <div className="flex justify-end gap-3 pt-4 border-t border-gray-100">
              <button
                onClick={() => setShowReopenModal(false)}
                className="px-4 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-lg hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary"
              >
                Cancel
              </button>
              <button
                onClick={() => { setShowReopenModal(false); handleReopenChat() }}
                disabled={isReopening}
                className="px-4 py-2 text-sm font-medium text-white bg-green-600 rounded-lg hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-green-500 disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
              >
                {isReopening ? 'Reopening...' : '↩ Yes, Reopen Chat'}
              </button>
            </div>
          </div>
        </Modal>

        {/* Chat Template Modal */}
        {chat && (
          <ChatTemplateModal
            isOpen={isTemplateModalOpen}
            onClose={() => setIsTemplateModalOpen(false)}
            onSuccess={(sentMessage?: any) => {
              setIsTemplateModalOpen(false)
              if (sentMessage && sentMessage._id) {
                // Register the confirmed ID so the socket event is ignored
                confirmedMessageIds.current.add(sentMessage._id)
                // Add the message to the chat instantly (skip if already present from socket)
                setMessages(prev => {
                  if (prev.some(m => m._id === sentMessage._id)) return prev
                  return [...prev, sentMessage]
                })
              } else {
                // Fallback: reload chat data if no message returned
                loadChatData()
              }
            }}
            chatId={chat._id}
            wabaId={typeof chat.wabaId === 'object' && chat.wabaId !== null ? (chat.wabaId as any)._id : chat.wabaId}
          />
        )}

        {/* Context Menu */}
        {contextMenuMsg && (
          <div
            className="fixed z-[100] bg-white rounded-lg shadow-xl border border-gray-100 py-1.5 min-w-[160px] text-sm text-gray-700 font-medium overflow-hidden"
            style={{
              top: contextMenuMsg.y,
              left: contextMenuMsg.x,
            }}
            onClick={(e) => e.stopPropagation()}
          >
            <button
              onClick={() => {
                setReplyingToMsg(contextMenuMsg.message)
                setContextMenuMsg(null)
                composerInputRef.current?.focus()
              }}
              className="w-full text-left px-4 py-2 hover:bg-gray-100 flex items-center gap-2 transition-colors"
            >
              <svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor" className="text-gray-500"><path d="M10 9V5l-7 7 7 7v-4.1c5 0 8.5 1.6 11 5.1-1-5-4-10-11-11z" /></svg>
              Reply
            </button>
            <button
              onClick={() => {
                const textToCopy = contextMenuMsg.message.text || contextMenuMsg.message.caption
                if (textToCopy) {
                  navigator.clipboard.writeText(textToCopy)
                }
                setContextMenuMsg(null)
              }}
              className="w-full text-left px-4 py-2 hover:bg-gray-100 flex items-center gap-2 transition-colors"
            >
              <svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor" className="text-gray-500"><path d="M16 1H4c-1.1 0-2 .9-2 2v14h2V3h12V1zm3 4H8c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h11c1.1 0 2-.9 2-2V7c0-1.1-.9-2-2-2zm0 16H8V7h11v14z" /></svg>
              Copy
            </button>
            {contextMenuMsg.isOutbound && (
              <button
                onClick={() => {
                  setActiveReactionMsg(contextMenuMsg.message._id)
                  setContextMenuMsg(null)
                }}
                className="w-full text-left px-4 py-2 hover:bg-gray-100 flex items-center gap-2 transition-colors"
              >
                <svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor" className="text-gray-500"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm3.5 14H8.5c-.28 0-.5-.22-.5-.5s.22-.5.5-.5h7c.28 0 .5.22.5.5s-.22.5-.5.5zm1.5-3H7V11h10v2zm0-4H7V7h10v2z" /></svg>
                Like
              </button>
            )}
            <div className="w-full bg-gray-100 h-[1px] my-1"></div>
            <button
              onClick={async () => {
                try {
                  await chatsApi.deleteMessage(contextMenuMsg.message._id)
                } catch (e) {
                  console.error('Delete message error', e)
                }
                setContextMenuMsg(null)
              }}
              className="w-full text-left px-4 py-2 hover:bg-red-50 text-red-600 flex items-center gap-2 transition-colors font-semibold"
            >
              <svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor" className="text-red-500"><path d="M6 19c0 1.1.9 2 2 2h8c1.1 0 2-.9 2-2V7H6v12zm2.46-7.12l1.41-1.41L12 12.59l2.12-2.12 1.41 1.41L13.41 14l2.12 2.12-1.41 1.41L12 15.41l-2.12 2.12-1.41-1.41L10.59 14l-2.13-2.12zM15.5 4l-1-1h-5l-1 1H5v2h14V4z" /></svg>
              Delete
            </button>
          </div>
        )}
      </div>

      <Modal isOpen={showNicknameModal} onClose={() => setShowNicknameModal(false)} title="Edit Nickname">
        <form onSubmit={handleUpdateNickname}>
          <div className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Nickname
              </label>
              <input
                type="text"
                value={nicknameInput}
                onChange={(e) => setNicknameInput(e.target.value)}
                placeholder="Enter a custom name..."
                className="w-full rounded-lg border border-gray-300 py-2 px-3 text-sm focus:border-primary focus:outline-none focus:ring-1 focus:ring-primary"
                autoFocus
              />
              <p className="mt-2 text-xs text-gray-500">
                This name will be displayed instead of their WhatsApp name. Clear the input to use their original name.
              </p>
            </div>
            <div className="flex justify-end gap-3 pt-4 border-t border-gray-100">
              <button
                type="button"
                onClick={() => setShowNicknameModal(false)}
                className="px-4 py-2 text-sm font-medium text-gray-700 hover:bg-gray-100 rounded-lg transition-colors"
              >
                Cancel
              </button>
              <button
                type="submit"
                disabled={isUpdatingNickname}
                className="px-4 py-2 bg-primary text-white text-sm font-medium rounded-lg hover:bg-primary/90 transition-colors disabled:opacity-50"
              >
                {isUpdatingNickname ? 'Saving...' : 'Save Nickname'}
              </button>
            </div>
          </div>
        </form>
      </Modal>

      {/* Paste Image Preview Modal */}
      {pastedImage && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg overflow-hidden flex flex-col animate-in zoom-in-95 duration-200">
            <div className="p-4 border-b border-gray-100 flex items-center justify-between">
              <h3 className="font-semibold text-gray-900">Send Screenshot?</h3>
              <button 
                onClick={() => setPastedImage(null)}
                className="p-1 hover:bg-gray-100 rounded-full transition-colors"
              >
                <svg viewBox="0 0 24 24" width="20" height="20" fill="currentColor" className="text-gray-500">
                  <path d="M19 6.41L17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12z" />
                </svg>
              </button>
            </div>

            <div className="flex-1 bg-gray-50 p-4 flex items-center justify-center min-h-[300px] max-h-[60vh] overflow-hidden">
              {/* eslint-disable-next-line @next/next/no-img-element */}
              {pastedImageUrl && (
                <img 
                  src={pastedImageUrl} 
                  alt="Pasted Preview" 
                  className="max-w-full max-h-full object-contain rounded-lg shadow-md"
                />
              )}
            </div>

            <div className="p-4 border-t border-gray-100 flex justify-end gap-3 bg-white">
              <button
                onClick={() => setPastedImage(null)}
                className="px-6 py-2.5 text-sm font-medium text-gray-700 hover:bg-gray-100 rounded-xl transition-all"
              >
                Cancel
              </button>
              <button
                onClick={() => {
                  processFile(pastedImage);
                  setPastedImage(null);
                }}
                className="px-8 py-2.5 bg-[#00a884] text-white text-sm font-semibold rounded-xl hover:bg-[#008f6f] transition-all shadow-md shadow-green-200 flex items-center gap-2"
              >
                <svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor">
                  <path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z" />
                </svg>
                Send Image
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Incoming Call Banner */}
      {incomingCall && (
        <div className="fixed top-4 left-1/2 -translate-x-1/2 z-[200] animate-in slide-in-from-top duration-300">
          <div className="bg-white rounded-2xl shadow-2xl border border-gray-200 px-6 py-4 flex items-center gap-4 min-w-[360px]">
            <div className="w-12 h-12 rounded-full bg-green-100 flex items-center justify-center animate-pulse">
              <svg viewBox="0 0 24 24" width="24" height="24" fill="#16a34a">
                <path d="M20.01 15.38c-1.23 0-2.42-.2-3.53-.56a.977.977 0 00-1.01.24l-1.57 1.97c-2.83-1.35-5.48-3.9-6.89-6.83l1.95-1.66c.27-.28.35-.67.24-1.02-.37-1.11-.56-2.3-.56-3.53 0-.54-.45-.99-.99-.99H4.19C3.65 3 3 3.24 3 3.99 3 13.28 10.73 21 20.01 21c.71 0 .99-.63.99-1.18v-3.45c0-.54-.45-.99-.99-.99z" />
              </svg>
            </div>
            <div className="flex-1">
              <p className="font-semibold text-gray-900 text-sm">Incoming Call</p>
              <p className="text-xs text-gray-500">{formatInternationalPhone(incomingCall.waId)}</p>
            </div>
            <div className="flex items-center gap-2">
              <button
                onClick={() => setIncomingCall(null)}
                className="w-10 h-10 rounded-full bg-red-500 hover:bg-red-600 flex items-center justify-center text-white transition-colors shadow-lg"
                title="Decline"
              >
