                                      return (
                                        <div key={i} className="mb-1.5">
                                          <p className="text-[14.2px] text-gray-800 leading-snug whitespace-pre-wrap" style={{ wordWrap: 'break-word' }} dangerouslySetInnerHTML={{__html: linkifyText(c.text)}} />
                                        </div>
                                      )
                                    }
                                    if (c.type === 'FOOTER') {
                                      return (
                                        <div key={i} className="mt-1 text-[12px] text-gray-500 leading-tight">
                                          <p dangerouslySetInnerHTML={{__html: linkifyText(c.text)}} />
                                        </div>
                                      )
                                    }
                                    return null
                                  })}
                                  {/* Template buttons */}
                                  {message.metadata.templateComponents.find((c: any) => c.type === 'BUTTONS') && (
                                    <div className="border-t border-gray-200/60 flex flex-col mt-2 -mx-3 -mb-1">
                                      {message.metadata.templateComponents.find((c: any) => c.type === 'BUTTONS')!.buttons?.map((btn: any, idx: number) => (
                                        <div
                                          key={idx}
                                          className={`border-b last:border-b-0 border-gray-200/50 py-2 px-3 text-center flex items-center justify-center gap-1.5 text-[#00a884] font-medium text-[13.5px] ${
                                            btn.type === 'URL' && btn.url
                                              ? 'cursor-pointer hover:bg-green-50 transition-colors'
                                              : ''
                                          }`}
                                          onClick={() => {
                                            if (btn.type === 'URL' && btn.url) {
                                              const url = btn.url.toLowerCase().startsWith('http')
                                                ? btn.url
                                                : `https://${btn.url}`
                                              window.open(url, '_blank')
                                            } else if (btn.type === 'PHONE_NUMBER' && btn.phone_number) {
                                              window.location.href = `tel:${btn.phone_number}`
                                            }
                                          }}
                                        >
                                          {btn.type === 'URL' && (
                                            <svg viewBox="0 0 24 24" width="14" height="14" fill="currentColor"><path d="M14 3h7v7h-2V6.41l-9.59 9.59-1.41-1.41L17.59 5H14V3zM5 5h6V3H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2v-6h-2v6H5V5z" /></svg>
                                          )}
                                          {btn.type === 'PHONE_NUMBER' && (
                                            <svg viewBox="0 0 24 24" width="14" height="14" fill="currentColor"><path d="M6.62 10.79c1.44 2.83 3.76 5.14 6.59 6.59l2.2-2.2c.27-.27.67-.36 1.02-.24 1.12.37 2.33.57 3.57.57.55 0 1 .45 1 1V20c0 .55-.45 1-1 1-9.39 0-17-7.61-17-17 0-.55.45-1 1-1h3.5c.55 0 1 .45 1 1 0 1.25.2 2.45.57 3.57.11.35.03.74-.25 1.02l-2.2 2.2z" /></svg>
                                          )}
                                          {btn.type === 'QUICK_REPLY' && (
                                            <svg viewBox="0 0 24 24" width="14" height="14" fill="currentColor"><path d="M10 9V5l-7 7 7 7v-4.1c5 0 8.5 1.6 11 5.1-1-5-4-10-11-11z" /></svg>
                                          )}
                                          {btn.text}
                                        </div>
                                      ))}
                                    </div>
                                  )}
                                  {/* Template name label */}
                                  {message.metadata.templateName && (
                                    <div className="flex items-center gap-1.5 mt-2 pt-1.5 border-t border-gray-200/50 -mx-3 px-3">
                                      <svg viewBox="0 0 24 24" width="12" height="12" fill="currentColor" className="text-[#00a884] shrink-0">
                                        <path d="M19 3H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2zm-5 14H7v-2h7v2zm3-4H7v-2h10v2zm0-4H7V7h10v2z" />
                                      </svg>
                                      <span className="text-[10px] text-gray-400 font-medium uppercase tracking-wider truncate">{message.metadata.templateName}</span>
                                    </div>
                                  )}
                                </div>
                              ) : (
                                <div className="bg-black/5 rounded-lg p-3 min-w-[200px] border border-black/5">
                                  <div className="flex items-center gap-2 mb-2 text-[#00a884]">
                                    <svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor">
                                      <path d="M19 3H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2zm-5 14H7v-2h7v2zm3-4H7v-2h10v2zm0-4H7V7h10v2z" />
                                    </svg>
                                    <span className="text-xs font-bold uppercase tracking-wider">Template Message</span>
                                  </div>
                                  <p className="whitespace-pre-wrap text-[14.2px] leading-snug text-gray-800">
                                    {message.text || 'This template message content will be updated when the contact replies or WhatsApp sends the callback.'}
                                  </p>
                                </div>
                              )
                            )}
                            {(!message.type || !['text', 'image', 'video', 'audio', 'document', 'template', 'interactive'].includes(message.type)) && (
                              <p className="whitespace-pre-wrap text-[14.2px] leading-snug italic text-gray-500">[{message.type} message]</p>
                            )}

                            <div className={`text-[11px] mt-0.5 flex items-center justify-end float-right ml-4 ${isOutbound ? 'text-gray-500/80' : 'text-gray-400'}`}>
                              <span className="mt-[2px] inline-block pt-[2px]">
                                {new Date(message.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: true })}
                              </span>
                              {isOutbound && renderStatus(message.status)}
                            </div>

                            {/* Clearfix for floating timestamp */}
                            <div className="clear-both"></div>
                          </div>

                          {/* Failed message retry bar */}
                          {message.status === 'failed' && isOutbound && (
                            <div className="flex flex-col items-end mt-1">
                              <button
                                onClick={(e) => {
                                  e.stopPropagation();
                                  handleRetryMessage(message._id);
                                }}
                                disabled={retryingMsgId === message._id}
                                className="flex items-center gap-1.5 px-2.5 py-1 text-[11px] font-semibold text-red-500 hover:text-red-600 hover:bg-red-50 rounded-md transition-colors cursor-pointer"
                              >
                                {retryingMsgId === message._id ? (
                                  <svg className="animate-spin h-3 w-3" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                                  </svg>
                                ) : (
                                  <svg viewBox="0 0 24 24" width="12" height="12" fill="currentColor">
                                    <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm1 15h-2v-2h2v2zm0-4h-2V7h2v6z" />
                                  </svg>
                                )}
                                Failed to send · Tap to retry
                              </button>
                              {message.errorMessage && (
                                <span className="text-[10px] text-red-400/80 px-2.5 max-w-[250px] truncate" title={message.errorMessage}>
                                  {message.errorCode ? `Error ${message.errorCode}: ` : ''}{message.errorMessage}
                                </span>
                              )}
                            </div>
                          )}

                          {/* Display Reactions */}
                          {Object.keys(uniqueReactions).length > 0 && (
                            <div className={`absolute -bottom-[10px] ${isOutbound ? 'right-2' : 'left-2'} bg-white border border-gray-200 shadow-sm rounded-full px-[6px] py-[3px] text-xs flex items-center gap-[3px] z-10 cursor-pointer hover:bg-gray-50`} onClick={() => setActiveReactionMsg(activeReactionMsg === messageId ? null : messageId)}>
                              {Object.entries(uniqueReactions).map(([emoji, count]) => {
                                const emojiUrl = EMOJIS.find(e => e.char === emoji)?.url;
                                return (
                                  <span key={emoji} className="flex items-center gap-[3px]">
                                    {emojiUrl ? (
                                      /* eslint-disable-next-line @next/next/no-img-element */
                                      <img src={emojiUrl} alt={emoji} className="w-[14px] h-[14px] object-contain" />
                                    ) : (
                                      <span className="text-[13px] leading-none">{emoji}</span>
                                    )}
                                    {(count as number) > 1 && <span className="text-gray-500 text-[11px] font-medium leading-none">{count as number}</span>}
                                  </span>
                                )
                              })}
                            </div>
                          )}
                        </div>

                        {/* Inbound Reaction Menu (Right) */}
                        {(!isOutbound && chat.status !== 'closed') && (
                          <div className="opacity-0 group-hover:opacity-100 transition-opacity self-center relative shrink-0">
                            <button
                              onClick={() => setActiveReactionMsg(activeReactionMsg === messageId ? null : messageId)}
                              className="p-1 rounded-full text-gray-400 hover:text-gray-600 hover:bg-gray-100 bg-white shadow-sm transition-colors"
                            >
                              <svg viewBox="0 0 24 24" width="20" height="20" fill="currentColor">
                                <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.41 0-8-3.59-8-8s3.59-8 8-8 8 3.59 8 8-3.59 8-8 8zm3.5-9c.83 0 1.5-.67 1.5-1.5S16.33 8 15.5 8 14 8.67 14 9.5s.67 1.5 1.5 1.5zm-7 0c.83 0 1.5-.67 1.5-1.5S7.33 8 6.5 8 5 8.67 5 9.5 5.67 11 6.5 11zm3.5 6.5c2.33 0 4.31-1.46 5.11-3.5H8.89c.8 2.04 2.78 3.5 5.11 3.5z" />
                              </svg>
                            </button>
                            {/* Emoji Picker Dropdown */}
                            {activeReactionMsg === messageId && (
                              <div className="absolute left-0 top-8 bg-white shadow-md rounded-full px-3 py-1 flex gap-2 z-50 border border-gray-200 min-w-max items-center">
                                {EMOJIS.map(emojiObj => (
                                  <button key={emojiObj.char} onClick={() => handleReact(messageId, emojiObj.char)} className="hover:scale-125 transition-transform origin-bottom hover:-translate-y-1 p-1">
                                    {/* eslint-disable-next-line @next/next/no-img-element */}
                                    <img src={emojiObj.url} alt={emojiObj.char} className="w-6 h-6 object-contain pointer-events-none" />
                                  </button>
                                ))}
                              </div>
                            )}
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                )
              })
            })()}
            <div ref={messagesEndRef} className="h-4" />
          </div>

          {/* Input Area */}
          <div className="bg-white border-t border-gray-200 p-4 pb-[calc(1rem+env(safe-area-inset-bottom))]">
            {chat.isUnread && chat.isManuallyUnread ? (
              <button
                onClick={async () => {
                  try {
                    await chatsApi.markRead(chatId);
                    setChat(prev => prev ? { ...prev, isUnread: false, isManuallyUnread: false } : null);
                  } catch (e) {
                    console.error("Failed to mark read:", e);
                  }
                }}
                className="w-full flex items-center justify-center gap-2 px-4 py-3 min-h-[52px] bg-white border border-gray-200 shadow-sm rounded-xl hover:bg-gray-50 transition-colors font-medium text-gray-700 hover:text-[#00a884] focus:outline-none"
              >
                <div className="text-[#34b7f1]">
                  <svg viewBox="0 0 16 15" width="20" height="20" fill="currentColor">
                    <path d="M15.01 3.316l-.478-.372a.365.365 0 0 0-.51.063L8.666 9.879a.32.32 0 0 1-.484.033l-.358-.325a.32.32 0 0 0-.484.032l-.378.483a.418.418 0 0 0 .036.541l1.32 1.266c.143.14.361.125.484-.033l6.272-8.048a.366.366 0 0 0-.064-.512zm-4.1 0l-.478-.372a.365.365 0 0 0-.51.063L4.566 9.879a.32.32 0 0 1-.484.033L1.891 7.769a.366.366 0 0 0-.515.006l-.423.433a.364.364 0 0 0 .006.514l3.258 3.185c.143.14.361.125.484-.033l6.272-8.048a.365.365 0 0 0-.063-.51z" />
                  </svg>
                </div>
                Mark Read
              </button>
            ) : chat.contactId?.isOptedOut ? (
              <div className="flex flex-col sm:flex-row items-center justify-center p-4 bg-indigo-50 rounded-lg border border-indigo-100 text-indigo-800 text-center">
                <svg viewBox="0 0 24 24" width="20" height="20" fill="currentColor" className="mb-2 sm:mb-0 sm:mr-2 shrink-0">
                  <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.42 0-8-3.58-8-8s3.58-8 8-8 8 3.58 8 8-3.58 8-8 8zm1-13h-2v6l5.25 3.15.75-1.23-4-2.37V7z" />
                </svg>
                <span className="font-medium">This contact has opted out. Messaging is disabled.</span>
              </div>
            ) : chat.status === 'closed' ? (
              <div className="flex flex-col sm:flex-row items-center justify-between p-4 bg-gray-50 rounded-lg border border-gray-100">
                <p className="text-gray-500 font-medium mb-3 sm:mb-0">This chat is closed. You can only send Template Messages.</p>
                <button
                  onClick={() => setIsTemplateModalOpen(true)}
                  className="flex items-center justify-center gap-2 px-4 py-2 rounded-lg bg-[#00a884] hover:bg-[#008f6f] text-white text-sm font-medium transition-colors shadow-sm"
                >
                  <svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor">
                    <path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z" />
                  </svg>
                  Send Template
                </button>
              </div>
            ) : isRecording ? (
              <div className="flex items-center gap-4 bg-red-50 p-2 rounded-full px-6 transition-all duration-300">
                <div className="w-3 h-3 bg-red-500 rounded-full animate-pulse"></div>
                <span className="text-red-500 font-medium flex-1">{formatDuration(recordingDuration)}</span>
                <button onClick={() => stopRecording(true)} className="text-gray-500 hover:text-red-500 p-2">Cancel</button>
                <button
                  onClick={() => stopRecording(false)}
                  className="bg-red-500 text-white rounded-full p-2 hover:bg-red-600 transition-colors"
                >
                  <svg viewBox="0 0 24 24" width="24" height="24" fill="currentColor">
                    <path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z" />
                  </svg>
                </button>
              </div>
            ) : recordedAudio ? (
              <div className="flex flex-col gap-2">
                {voiceMessageError && (
                  <div className="bg-red-50 border border-red-200 rounded-lg px-4 py-3 text-red-700 text-sm">
                    <div className="flex items-center gap-2">
                      <svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm1 15h-2v-2h2v2zm0-4h-2V7h2v6z" /></svg>
                      <span className="font-medium">Error:</span>
                      <span>{voiceMessageError}</span>
                    </div>
                  </div>
                )}
                <div className="flex flex-col sm:flex-row items-center gap-3 bg-green-50 p-3 rounded-lg transition-all duration-300 border border-green-200">
                  <div className="w-3 h-3 bg-green-500 rounded-full animate-pulse shrink-0"></div>
                  <span className="text-green-700 font-medium text-sm whitespace-nowrap">Review voice:</span>
                  <audio
                    src={recordedAudio.url}
                    controls
                    controlsList="nodownload"
                    className="flex-1 h-8 min-w-0 w-full sm:w-auto"
                  />
                  <div className="flex gap-2 w-full sm:w-auto">
                    <button
                      onClick={discardVoiceMessage}
                      className="flex-1 sm:flex-none px-4 py-2 text-gray-700 text-sm font-medium border border-gray-300 rounded-lg hover:bg-gray-50 transition-colors"
                    >
                      Discard
                    </button>
                    <button
                      onClick={sendVoiceMessage}
                      disabled={sending}
                      className="flex-1 sm:flex-none bg-[#00a884] text-white rounded-lg px-4 py-2 font-medium hover:bg-[#008f6f] transition-colors disabled:opacity-50 flex items-center justify-center gap-2"
                      title="Send Voice Message"
                    >
                      <svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor">
                        <path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z" />
                      </svg>
                      Send
                    </button>
                  </div>
                </div>
              </div>
            ) : (sessionTimeLeft === 0 && !isNote) ? (
              <div className="flex flex-col sm:flex-row items-center justify-between bg-yellow-50/80 border border-yellow-200/60 p-3 rounded-xl">
                <div className="flex items-center gap-3 mb-3 sm:mb-0">
                  <div className="w-10 h-10 rounded-full bg-yellow-100 flex items-center justify-center shrink-0 text-yellow-600">
                    <svg viewBox="0 0 24 24" fill="none" strokeWidth={1.5} stroke="currentColor" className="w-6 h-6">
                      <path strokeLinecap="round" strokeLinejoin="round" d="M12 6v6h4.5m4.5 0a9 9 0 11-18 0 9 9 0 0118 0z" />
                    </svg>
                  </div>
                  <div>
                    <h4 className="text-sm font-semibold text-gray-900">24-Hour Window Expired</h4>
                    <p className="text-xs text-gray-600">You must use a Template Message to reply, or switch to Internal Note.</p>
                  </div>
                </div>
                <div className="flex gap-2 w-full sm:w-auto">
                  <button
                    onClick={() => setIsNote(true)}
                    className="flex-1 sm:flex-none px-4 py-2 rounded-lg bg-white border border-gray-200 text-gray-700 text-sm font-medium hover:bg-gray-50 transition-colors"
                  >
                    Write Note
                  </button>
                  <button
                    onClick={() => setIsTemplateModalOpen(true)}
                    className="flex-1 sm:flex-none flex items-center justify-center gap-2 px-4 py-2 rounded-lg bg-[#00a884] hover:bg-[#008f6f] text-white text-sm font-medium transition-colors shadow-sm"
                  >
                    <svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor">
                      <path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z" />
                    </svg>
                    Send Template
                  </button>
                </div>
              </div>
            ) : (
              <div className="flex flex-col">
                {replyingToMsg && (
                  <div className="flex items-center justify-between bg-gray-50 px-4 py-2 border-l-4 border-[#00a884] rounded-t-lg mx-2 mt-[-10px] mb-2 shadow-sm relative z-0">
                    <div className="flex flex-col flex-1 min-w-0 pr-4">
                      <span className="text-[#00a884] text-[13px] font-semibold truncate">
                        {replyingToMsg.direction === 'inbound'
                          ? (chat?.contactId?.nickname || chat?.contactId?.name || chat?.contactId?.nameOnWhatsApp || formatInternationalPhone(chat?.waId || chat?.phoneNumber) || 'Customer')
                          : (typeof replyingToMsg.sentBy === 'object' && 'name' in replyingToMsg.sentBy ? (replyingToMsg.sentBy as any).name : 'Staff')}
                      </span>
                      <span className="text-gray-600 text-[13px] truncate flex items-center gap-1 mt-0.5">
                        {replyingToMsg.type === 'image' && <svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor"><path d="M21 19V5c0-1.1-.9-2-2-2H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2zM8.5 13.5l2.5 3.01L14.5 12l4.5 6H5l3.5-4.5z" /></svg>}
                        {replyingToMsg.type === 'video' && <svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor"><path d="M17 10.5V7c0-.55-.45-1-1-1H4c-.55 0-1 .45-1 1v10c0 .55.45 1 1 1h12c.55 0 1-.45 1-1v-3.5l4 4v-11l-4 4z" /></svg>}
                        {replyingToMsg.type === 'audio' && <svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor"><path d="M12 14c1.66 0 2.99-1.34 2.99-3L15 5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3zm5.3-3c0 3-2.54 5.1-5.3 5.1S6.7 14 6.7 11H5c0 3.41 2.72 6.23 6 6.72V21h2v-3.28c3.28-.48 6-3.3 6-6.72h-1.7z" /></svg>}
                        {replyingToMsg.type === 'document' && <svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor"><path d="M14 2H6c-1.1 0-1.99.9-1.99 2L4 20c0 1.1.89 2 1.99 2H18c1.1 0 2-.9 2-2V8l-6-6zm2 16H8v-2h8v2zm0-4H8v-2h8v2zm-3-5V3.5L18.5 9H13z" /></svg>}
                        {replyingToMsg.text || replyingToMsg.caption || (replyingToMsg.type !== 'text' ? replyingToMsg.type.charAt(0).toUpperCase() + replyingToMsg.type.slice(1) : '')}
                      </span>
                    </div>
                    {replyingToMsg.mediaUrl && replyingToMsg.type === 'image' && (
                      <div className="w-[40px] h-[40px] shrink-0 ml-2 rounded overflow-hidden">
                        {/* eslint-disable-next-line @next/next/no-img-element */}
                        <img src={replyingToMsg.mediaUrl} alt="preview" className="w-full h-full object-cover" />
                      </div>
                    )}
                    <button onClick={() => setReplyingToMsg(null)} className="text-gray-400 hover:text-gray-600 p-1.5 ml-2 hover:bg-gray-200 rounded-full transition-colors shrink-0">
                      <svg viewBox="0 0 24 24" width="20" height="20" fill="currentColor">
                        <path d="M19 6.41L17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12z" />
                      </svg>
                    </button>
                  </div>
                )}
                <div className="px-4">
                  <AISuggestionPanel
                    suggestion={aiSuggestion}
                    isLoading={isAiLoading}
                    onAccept={(suggestion) => {
                      setNewMessage(suggestion)
                      setAiSuggestion(null)
                      setAiError(null)
                      aiMessageService.cancel()
                      composerInputRef.current?.focus()
                    }}
                    onSend={handleSendAiSuggestion}
                    onDismiss={() => {
                      setAiSuggestion(null)
                      setAiError(null)
                      aiMessageService.cancel()
                    }}
                  />
                </div>
                <form onSubmit={handleSendMessage} className="flex gap-2 items-center relative z-10">
                  {/* Attachment Menu */}
                  <div className="relative shrink-0">
                    <input
                      type="file"
                      ref={fileInputRef}
                      onChange={(e) => handleFileUpload(e, false)}
                      className="hidden"
                      accept="image/*,video/*"
                    />
                    <input
                      type="file"
                      id="documentInput"
                      onChange={(e) => handleFileUpload(e, true)}
                      className="hidden"
                    />

                    <button
                      type="button"
                      onClick={() => {
                        const menu = document.getElementById('attachment-menu');
                        if (menu) menu.classList.toggle('hidden');
                      }}
                      onBlur={() => {
                        setTimeout(() => {
                          const menu = document.getElementById('attachment-menu');
                          if (menu) menu.classList.add('hidden');
                        }, 200);
                      }}
                      disabled={sending || (sessionTimeLeft === 0 && !isNote)}
                      className="text-gray-500 hover:text-gray-700 p-2 disabled:opacity-50 transition-colors relative shrink-0"
                      title={sessionTimeLeft === 0 && !isNote ? "Session expired" : "Attach"}
