import apiClient from './client'

export interface CallLog {
  _id: string
  chatId: string
  wabaId: string
  phoneNumberId: string
  callId?: string
  waId: string
  direction: 'inbound' | 'outbound'
  status: 'permission_requested' | 'permission_granted' | 'ringing' | 'accepted' | 'rejected' | 'terminated' | 'missed' | 'failed'
  duration: number
  initiatedBy?: { _id: string; name: string }
  startedAt?: string
  answeredAt?: string
  endedAt?: string
  metadata?: any
  createdAt: string
  updatedAt: string
}

export interface CallingReadiness {
  ready: boolean
  checks: {
    wabaSubscribedToApp: boolean | null
    callsFieldSubscribed: boolean | null
    cloudApiOnly: boolean | null
    messagingLimitEligible: boolean | null
    callingEnabled: boolean | null
    messagingPermission: boolean | null
  }
  blockers: string[]
  warnings: string[]
  metaErrorHint: string | null
  docs: string
}

export interface MediaSession {
  room: string
  livekitUrl: string
  token: string
  identity: string
}

export const callsApi = {
  /** Send a call permission request to the customer */
  async requestPermission(chatId: string): Promise<{ success: boolean; callLog: CallLog }> {
    const { data } = await apiClient.post(`/calls/${chatId}/request-permission`)
    return data
  },

  /** Check if this chat's WABA number is ready for Cloud API calling */
  async getReadiness(chatId: string): Promise<{ success: boolean; readiness: CallingReadiness }> {
    const { data } = await apiClient.get(`/calls/${chatId}/readiness`)
    return data
  },

  /** Initiate an outbound call to the customer */
  async initiateCall(chatId: string): Promise<{ success: boolean; callLog: CallLog }> {
    const { data } = await apiClient.post(`/calls/${chatId}/initiate`)
    return data
  },

  /** Accept an inbound ringing call */
  async acceptCall(callLogId: string): Promise<{ success: boolean; callLog: CallLog }> {
    const { data } = await apiClient.post(`/calls/${callLogId}/accept`)
    return data
  },

  /** Reject an inbound ringing call */
  async rejectCall(callLogId: string): Promise<{ success: boolean; callLog: CallLog }> {
    const { data } = await apiClient.post(`/calls/${callLogId}/reject`)
    return data
  },

  /** Get media session details for web call audio */
  async getMediaSession(callLogId: string): Promise<{ success: boolean; session: MediaSession }> {
    const { data } = await apiClient.get(`/calls/${callLogId}/media-session`)
    return data
  },

  /** Terminate an active call */
  async terminateCall(callLogId: string): Promise<{ success: boolean; callLog: CallLog }> {
    const { data } = await apiClient.post(`/calls/${callLogId}/terminate`)
    return data
  },

  /** Get call logs for a specific chat */
  async getChatCallLogs(chatId: string, params?: { page?: number; limit?: number }): Promise<{ success: boolean; logs: CallLog[]; total: number }> {
    const { data } = await apiClient.get(`/calls/${chatId}/logs`, { params })
    return data
  },

  /** Get all call logs (admin view) */
  async getAllCallLogs(params?: { page?: number; limit?: number; wabaId?: string; direction?: string; status?: string }): Promise<{ success: boolean; logs: CallLog[]; total: number }> {
    const { data } = await apiClient.get('/calls/logs', { params })
    return data
  },
}

